fn dispatch_broker_request(
    state: &ServerState,
    request: BrokerRequest,
) -> Result<BrokerResponse, TypedError> {
    dispatch_broker_request_as(
        state,
        request,
        BrokerCallerRole::AdminUid {
            uid: state.daemon_uid,
        },
    )
}

fn records_broker_response_evidence(request: &BrokerRequest) -> bool {
    !matches!(request, BrokerRequest::ResourceActivationAudit(_))
}

fn dispatch_broker_request_as(
    state: &ServerState,
    request: BrokerRequest,
    caller_role: BrokerCallerRole,
) -> Result<BrokerResponse, TypedError> {
    let socket_path = broker_socket_path(state);
    let audit_join = default_audit_join_context(&request);
    let ingest_response_evidence = records_broker_response_evidence(&request);
    let socket = connect_seqpacket(&socket_path)?;
    write_json_frame(
        &socket,
        &BrokerRequestEnvelope {
            request,
            caller_role,
            test_peer_uid: None,
            audit_join: audit_join.clone(),
        },
    )?;
    let response = read_frame(&socket)?;
    let decoded =
        serde_json::from_slice(&response).map_err(|err| TypedError::InternalBrokerUnavailable {
            path: socket_path,
            detail: err.to_string(),
        })?;
    if ingest_response_evidence {
        ingest_broker_response_evidence(state, audit_join.as_ref(), &decoded);
    }
    Ok(decoded)
}

fn dispatch_broker_request_with_timeout(
    state: &ServerState,
    request: BrokerRequest,
    timeout: Duration,
) -> Result<BrokerResponse, TypedError> {
    dispatch_broker_request_with_timeout_as(
        state,
        request,
        BrokerCallerRole::AdminUid {
            uid: state.daemon_uid,
        },
        timeout,
    )
}

fn dispatch_broker_request_with_timeout_as(
    state: &ServerState,
    request: BrokerRequest,
    caller_role: BrokerCallerRole,
    timeout: Duration,
) -> Result<BrokerResponse, TypedError> {
    let socket_path = broker_socket_path(state);
    let audit_join = default_audit_join_context(&request);
    let ingest_response_evidence = records_broker_response_evidence(&request);
    let result =
        dispatch_broker_request_to_socket(&socket_path, request, caller_role, Some(timeout));
    if ingest_response_evidence && let Ok(response) = &result {
        ingest_broker_response_evidence(state, audit_join.as_ref(), response);
    }
    result
}

fn ingest_broker_response_evidence(
    state: &ServerState,
    audit_join: Option<&AuditJoinContext>,
    response: &BrokerResponse,
) {
    let Some(join) = audit_join else {
        return;
    };
    let Ok(zone) = AuditZoneId::parse(join.zone_id.as_str()) else {
        return;
    };
    let Ok(operation) = OperationIdentity::parse(join.operation_identity.as_str()) else {
        return;
    };
    let evidence = DurabilityEvidence {
        key: ZoneOperationKey::new(zone, operation),
        outcome: if matches!(response, BrokerResponse::Error(_)) {
            d2b_audit::DurabilityOutcome::Failure
        } else {
            d2b_audit::DurabilityOutcome::Success
        },
        effect_durable: !matches!(response, BrokerResponse::Error(_)),
    };
    let plane = state
        .resource_plane
        .lock()
        .ok()
        .and_then(|plane| plane.clone());
    if let Some(plane) = plane
        && let Err(error) = plane.record_broker_evidence(evidence)
    {
        tracing::debug!(error = ?error, "broker evidence ingestion skipped");
    }
}

fn poll_broker_child_reaped(state: &ServerState) -> Result<usize, TypedError> {
    let response = dispatch_broker_request(state, BrokerRequest::PollChildReaped)?;
    match response {
        BrokerResponse::PollChildReaped(response) => {
            let count = response.notifications.len();
            for notification in response.notifications {
                state.broker_reap_log.insert(notification);
            }
            Ok(count)
        }
        BrokerResponse::Error(error) => Err(TypedError::InternalBrokerUnavailable {
            path: broker_socket_path(state),
            detail: format!(
                "PollChildReaped rejected by broker: {} ({})",
                error.message, error.kind
            ),
        }),
        other => Err(TypedError::InternalBrokerUnavailable {
            path: broker_socket_path(state),
            detail: format!("PollChildReaped returned unexpected response: {other:?}"),
        }),
    }
}

fn refresh_broker_reap_log(state: &ServerState, context: &str) {
    match poll_broker_child_reaped(state) {
        Ok(0) => {}
        Ok(count) => tracing::debug!(count, context, "broker child reap log refreshed"),
        Err(err) => tracing::debug!(error = ?err, context, "broker child reap log refresh skipped"),
    }
}

fn dispatch_broker_request_with_fds_timeout(
    state: &ServerState,
    request: BrokerRequest,
    timeout: Duration,
) -> Result<(BrokerResponse, Vec<RawFd>), TypedError> {
    dispatch_broker_request_with_fds_timeout_as(
        state,
        request,
        BrokerCallerRole::AdminUid {
            uid: state.daemon_uid,
        },
        timeout,
    )
}

fn dispatch_broker_request_with_fds_timeout_as(
    state: &ServerState,
    request: BrokerRequest,
    caller_role: BrokerCallerRole,
    timeout: Duration,
) -> Result<(BrokerResponse, Vec<RawFd>), TypedError> {
    dispatch_broker_request_with_optional_request_fds(state, request, caller_role, &[], timeout)
}

/// Ask the broker for the peer pidfd bound to one accepted local socket.
///
/// The accepted socket remains daemon-owned; this performs one SCM_RIGHTS
/// request handoff and transfers ownership only of the broker's returned
/// pidfd.  The broker never accepts a numeric PID or caller-supplied
/// credential claim for this operation.
#[allow(dead_code)]
pub(crate) fn open_accepted_socket_peer_pidfd(
    state: &ServerState,
    accepted_socket: &OwnedFd,
    timeout: Duration,
) -> Result<OwnedFd, TypedError> {
    let socket_path = broker_socket_path(state);
    let (response, received_fds) = dispatch_broker_request_with_request_fd_timeout_as(
        state,
        BrokerRequest::OpenPeerPidfdFromAcceptedSocket(
            d2b_contracts_broker::broker_wire::OpenPeerPidfdFromAcceptedSocketRequest {},
        ),
        BrokerCallerRole::AdminUid {
            uid: state.daemon_uid,
        },
        accepted_socket,
        timeout,
    )?;

    let result = match response {
        BrokerResponse::OpenPeerPidfdFromAcceptedSocket(response)
            if response.pidfd_index == 0 && received_fds.len() == 1 =>
        {
            duplicate_received_fd(
                &received_fds,
                response.pidfd_index,
                "duplicate accepted-peer pidfd",
            )
        }
        BrokerResponse::OpenPeerPidfdFromAcceptedSocket(_) => {
            Err(TypedError::InternalBrokerUnavailable {
                path: socket_path,
                detail: "accepted-peer pidfd response did not return exactly one descriptor"
                    .to_owned(),
            })
        }
        BrokerResponse::Error(error) => Err(TypedError::InternalBrokerUnavailable {
            path: socket_path,
            detail: format!("accepted-peer pidfd refused: {}", error.kind),
        }),
        other => Err(TypedError::InternalBrokerUnavailable {
            path: socket_path,
            detail: format!(
                "accepted-peer pidfd returned unexpected response: {}",
                broker_response_kind(&other)
            ),
        }),
    };
    close_received_fds(&received_fds);
    result
}

#[allow(dead_code)]
fn dispatch_broker_request_with_request_fd_timeout_as(
    state: &ServerState,
    request: BrokerRequest,
    caller_role: BrokerCallerRole,
    request_fd: &OwnedFd,
    timeout: Duration,
) -> Result<(BrokerResponse, Vec<RawFd>), TypedError> {
    dispatch_broker_request_with_optional_request_fds(
        state,
        request,
        caller_role,
        &[request_fd.as_raw_fd()],
        timeout,
    )
}

fn dispatch_broker_request_with_optional_request_fds(
    state: &ServerState,
    request: BrokerRequest,
    caller_role: BrokerCallerRole,
    request_fds: &[RawFd],
    timeout: Duration,
) -> Result<(BrokerResponse, Vec<RawFd>), TypedError> {
    let socket_path = broker_socket_path(state);
    let audit_join = default_audit_join_context(&request);
    let ingest_response_evidence = records_broker_response_evidence(&request);
    let socket = Socket::from(connect_seqpacket_with_timeout(&socket_path, Some(timeout))?);
    socket
        .set_read_timeout(Some(timeout))
        .map_err(|err| TypedError::InternalIo {
            context: format!("set broker read timeout to {timeout:?}"),
            detail: err.to_string(),
        })?;
    socket
        .set_write_timeout(Some(timeout))
        .map_err(|err| TypedError::InternalIo {
            context: format!("set broker write timeout to {timeout:?}"),
            detail: err.to_string(),
        })?;
    write_json_frame_with_fds(
        &socket,
        &BrokerRequestEnvelope {
            request,
            caller_role,
            test_peer_uid: None,
            audit_join: audit_join.clone(),
        },
        request_fds,
    )?;
    let (response, received_fds) = read_frame_with_fds(&socket)?;
    let decoded = serde_json::from_slice(&response).map_err(|err| {
        close_received_fds(&received_fds);
        TypedError::InternalBrokerUnavailable {
            path: socket_path,
            detail: err.to_string(),
        }
    })?;
    if ingest_response_evidence {
        ingest_broker_response_evidence(state, audit_join.as_ref(), &decoded);
    }
    Ok((decoded, received_fds))
}

fn dispatch_broker_ack_request(
    state: &ServerState,
    verb: &str,
    op_name: &str,
    request: BrokerRequest,
) -> Result<(), Value> {
    dispatch_broker_ack_request_as(
        state,
        verb,
        op_name,
        request,
        BrokerCallerRole::AdminUid {
            uid: state.daemon_uid,
        },
    )
}

fn dispatch_broker_ack_request_as(
    state: &ServerState,
    verb: &str,
    op_name: &str,
    request: BrokerRequest,
    caller_role: BrokerCallerRole,
) -> Result<(), Value> {
    match dispatch_broker_request_as(state, request, caller_role) {
        Ok(BrokerResponse::Ack(ack)) if ack.accepted && ack.operation == op_name => Ok(()),
        Ok(BrokerResponse::Ack(ack)) => {
            tracing::warn!(
                op_name = op_name,
                broker_ack_operation = %ack.operation,
                broker_ack_accepted = ack.accepted,
                "broker returned unexpected ack payload"
            );
            let (summary, remediation) =
                redact_broker_error_for_launcher(op_name, None, "Broker.Protocol");
            Err(broker_failure_response(verb, summary, remediation, None))
        }
        Ok(BrokerResponse::Error(error)) => {
            tracing::warn!(
                broker_kind = %error.kind,
                broker_operation = %error.operation,
                broker_target_wave = error.target_wave.as_deref().unwrap_or("none"),
                broker_message = %error.message,
                broker_action = %error.action,
                "broker live op failed"
            );
            let (summary, remediation) = redact_broker_error_for_launcher(
                op_name,
                error.target_wave.as_deref(),
                &error.kind,
            );
            Err(broker_failure_response(
                verb,
                summary,
                remediation,
                error.target_wave,
            ))
        }
        Ok(other) => {
            tracing::warn!(
                op_name = op_name,
                broker_response_kind = %broker_response_kind(&other),
                "broker returned unexpected response kind"
            );
            let (summary, remediation) =
                redact_broker_error_for_launcher(op_name, None, "Broker.Protocol");
            Err(broker_failure_response(verb, summary, remediation, None))
        }
        Err(error) => {
            tracing::warn!(op_name = op_name, error = ?error, "broker dispatch failed");
            let (summary, remediation) = redact_broker_dispatch_failure_for_launcher(op_name);
            Err(broker_failure_response(verb, summary, remediation, None))
        }
    }
}

fn load_bundle_resolver(state: &ServerState) -> Result<BundleResolver, TypedError> {
    #[cfg(test)]
    let loaded = BundleResolver::load_with_policy(
        &state.config.artifacts.bundle_path,
        &d2b_core::bundle_resolver::BundleVerifyPolicy::for_tests(),
    );
    #[cfg(not(test))]
    let loaded = BundleResolver::load(&state.config.artifacts.bundle_path);

    loaded.map_err(|err| match err {
        d2b_core::error::Error::Bundle(BundleError::Tampered { path, reason }) => {
            TypedError::BundleTampered { path, reason }
        }
        other => TypedError::InternalIo {
            context: "load bundle resolver".to_owned(),
            detail: other.to_string(),
        },
    })
}

fn open_zone_store_from_broker(
    state: &ServerState,
    zone: &ZoneId,
) -> Result<d2bd_runtime::resource_store_runtime::OpenedZoneStore, TypedError> {
    let zone_store_id =
        ZoneStoreId::parse(format!("zone-store-{}", zone.as_str())).map_err(|_| {
            TypedError::InternalConfig {
                detail: "trusted Zone store id is invalid".to_owned(),
            }
        })?;
    let (response, received_fds) = dispatch_broker_request_with_fds_timeout(
        state,
        BrokerRequest::OpenZoneStore(BrokerOpenZoneStoreRequest { zone_store_id }),
        Duration::from_secs(60),
    )?;
    if received_fds.len() != 1 {
        close_received_fds(&received_fds);
        return Err(TypedError::InternalBrokerUnavailable {
            path: broker_socket_path(state),
            detail: "OpenZoneStore did not return exactly one descriptor".to_owned(),
        });
    }
    let fd = match duplicate_received_fd(&received_fds, 0, "duplicate Zone store fd") {
        Ok(fd) => fd,
        Err(error) => {
            close_received_fds(&received_fds);
            return Err(error);
        }
    };
    close_received_fds(&received_fds);
    match response {
        BrokerResponse::OpenZoneStore(response) => {
            if response.fd_index != 0
                || response.zone_store_id.as_str() != format!("zone-store-{}", zone.as_str())
            {
                return Err(TypedError::InternalBrokerUnavailable {
                    path: broker_socket_path(state),
                    detail: "OpenZoneStore response did not match its request".to_owned(),
                });
            }
            Ok(d2bd_runtime::resource_store_runtime::OpenedZoneStore {
                response,
                database_fd: fd,
                external_inventory: None,
            })
        }
        BrokerResponse::Error(error) => Err(TypedError::InternalBrokerUnavailable {
            path: broker_socket_path(state),
            detail: format!("OpenZoneStore refused: {}", error.kind),
        }),
        other => Err(TypedError::InternalBrokerUnavailable {
            path: broker_socket_path(state),
            detail: format!("OpenZoneStore returned unexpected response: {other:?}"),
        }),
    }
}

async fn ensure_resource_activation_broker_evidence(
    state: &ServerState,
    zone: &ZoneId,
    operation_id: &str,
    broker_evidence: &d2b_resource_store_redb::BrokerEvidenceIndex,
) -> Result<DurabilityEvidence, resource_runtime::ResourceRuntimeError> {
    let zone_identity = AuditZoneId::derive(zone.as_str())
        .map_err(|_| resource_runtime::ResourceRuntimeError::HandlerNotReady)?;
    let operation_identity = OperationIdentity::derive(operation_id)
        .map_err(|_| resource_runtime::ResourceRuntimeError::HandlerNotReady)?;
    let key = ZoneOperationKey::new(zone_identity.clone(), operation_identity.clone());
    let evidence = if let Some(evidence) = broker_evidence
        .get(&key)
        .map_err(|_| resource_runtime::ResourceRuntimeError::HandlerNotReady)?
    {
        evidence
    } else {
        let audit_join = AuditJoinContext {
            zone_id: CanonicalAuditDigest::parse(zone_identity.as_str())
                .map_err(|_| resource_runtime::ResourceRuntimeError::HandlerNotReady)?,
            operation_identity: CanonicalAuditDigest::parse(operation_identity.as_str())
                .map_err(|_| resource_runtime::ResourceRuntimeError::HandlerNotReady)?,
        };
        let response = dispatch_broker_request_with_timeout(
            state,
            BrokerRequest::ResourceActivationAudit(BrokerResourceActivationAuditRequest {
                audit_join,
            }),
            Duration::from_secs(10),
        )
        .map_err(|_| resource_runtime::ResourceRuntimeError::HandlerNotReady)?;
        match response {
            BrokerResponse::ResourceActivationAudit(response) if response.recorded => {
                DurabilityEvidence {
                    key,
                    outcome: d2b_audit::DurabilityOutcome::Success,
                    effect_durable: true,
                }
            }
            BrokerResponse::Error(_) => {
                return Err(resource_runtime::ResourceRuntimeError::HandlerNotReady);
            }
            _ => return Err(resource_runtime::ResourceRuntimeError::HandlerNotReady),
        }
    };
    Ok(evidence)
}

async fn shutdown_unpublished_runtimes(
    runtimes: &mut Vec<(
        ZoneId,
        resource_runtime::ZoneResourceRuntime,
        ResourceBundle,
    )>,
) {
    while let Some((_, runtime, _)) = runtimes.pop() {
        let _ = runtime.shutdown().await;
    }
}

fn committed_zone_topology(
    resolver: &BundleResolver,
    zones: &BTreeSet<ZoneId>,
) -> Result<CommittedZoneTopology, resource_runtime::ResourceRuntimeError> {
    let topology = resolver
        .zone_topology()
        .ok_or(resource_runtime::ResourceRuntimeError::HandlerNotReady)?;
    CommittedZoneTopology::from_allocator(zones, topology)
        .map_err(|_| resource_runtime::ResourceRuntimeError::HandlerNotReady)
}

async fn open_resource_plane(
    state: &ServerState,
    resolver: &BundleResolver,
    provider_ready: bool,
) -> Result<Arc<resource_runtime::ResourcePlane>, resource_runtime::ResourceRuntimeError> {
    if !provider_ready {
        return Err(resource_runtime::ResourceRuntimeError::ProviderPathUnavailable);
    }
    let mut plane = resource_runtime::ResourcePlane::new();
    let broker_evidence = match load_broker_audit_evidence(state) {
        Ok(evidence) => evidence,
        Err(error) => {
            tracing::error!(error = ?error, "Zone resource broker evidence load failed");
            return Err(error);
        }
    };
    let zones = match d2bd_runtime::zone_authority::authoritative_zone_ids(resolver) {
        Ok(zones) => zones,
        Err(error) => {
            tracing::error!(error = ?error, "Zone resource authority index load failed");
            return Err(resource_runtime::ResourceRuntimeError::ZoneStoreIdInvalid);
        }
    };
    let topology = match committed_zone_topology(resolver, &zones) {
        Ok(topology) => topology,
        Err(error) => {
            tracing::error!(error = ?error, "Zone resource topology validation failed");
            return Err(error);
        }
    };
    plane.set_topology_root(topology.root.clone());
    let mut prepared_inputs = BTreeMap::new();
    let mut prepared_generations = BTreeMap::new();
    for zone in &zones {
        let desired_bundle = resolver
            .zone_resource_bundle_bytes(zone.as_str())
            .ok_or(resource_runtime::ResourceRuntimeError::HandlerNotReady)
            .and_then(|bytes| {
                ResourceBundle::from_json(bytes).map_err(|error| {
                    tracing::error!(
                        zone = %zone.as_str(),
                        error = ?error,
                        "resource plane Zone bundle is invalid"
                    );
                    resource_runtime::ResourceRuntimeError::HandlerNotReady
                })
            })?;
        let storage = resolver
            .zone_storage_row(zone.as_str())
            .ok_or(resource_runtime::ResourceRuntimeError::HandlerNotReady)?;
        let authority =
            d2bd_runtime::zone_authority::ZoneAuthorityIdentity::from_bundle_and_storage(
                zone,
                &desired_bundle,
                storage,
            )
            .map_err(|error| {
                tracing::error!(
                    zone = %zone.as_str(),
                    error = %error,
                    "resource plane Zone identity binding failed"
                );
                resource_runtime::ResourceRuntimeError::HandlerNotReady
            })?;
        prepared_generations.insert(zone.clone(), authority.bundle_generation().clone());
        prepared_inputs.insert(zone.clone(), (desired_bundle, authority));
    }

    let set_generation = complete_generation_set_digest(&zones, &prepared_generations)
        .map_err(|_| resource_runtime::ResourceRuntimeError::HandlerNotReady)?;
    let mut prepared_runtimes = Vec::with_capacity(zones.len());
    for zone in zones {
        tracing::error!(zone = %zone.as_str(), "resource plane opening authoritative Zone");
        let (desired_bundle, authority) = match prepared_inputs.remove(&zone) {
            Some(input) => input,
            None => {
                shutdown_unpublished_runtimes(&mut prepared_runtimes).await;
                return Err(resource_runtime::ResourceRuntimeError::HandlerNotReady);
            }
        };
        tracing::error!(
            zone = %zone.as_str(),
            resource_count = desired_bundle.resources.len(),
            "resource plane Zone bundle loaded"
        );
        let materialization_bundle = desired_bundle.clone();
        let opened = match open_zone_store_from_broker(state, &zone) {
            Ok(opened) => opened,
            Err(error) => {
                tracing::error!(zone = ?zone, error = ?error, "Zone resource store broker open failed");
                shutdown_unpublished_runtimes(&mut prepared_runtimes).await;
                return Err(resource_runtime::ResourceRuntimeError::StoreOpenFailed);
            }
        };
        let zone_state_dir = state
            .daemon_state_dir
            .parent()
            .unwrap_or(state.daemon_state_dir.as_path())
            .join("zones")
            .join(zone.as_str());
        let audit_dir = zone_state_dir.join("audit");
        let telemetry_path = zone_state_dir.join("telemetry").join("emitter.sock");
        #[cfg(not(test))]
        if !audit_dir.is_absolute() {
            shutdown_unpublished_runtimes(&mut prepared_runtimes).await;
            return Err(resource_runtime::ResourceRuntimeError::StoreOpenFailed);
        }
        let audit_sink = match AuditSink::open(&audit_dir) {
            Ok(sink) => Arc::new(sink),
            Err(error) => {
                tracing::error!(
                    zone = %zone.as_str(),
                    audit_dir = %audit_dir.display(),
                    error = ?error,
                    "Zone resource audit sink open failed",
                );
                shutdown_unpublished_runtimes(&mut prepared_runtimes).await;
                return Err(resource_runtime::ResourceRuntimeError::StoreOpenFailed);
            }
        };
        let zone_name = zone.as_str().to_owned();
        let mut runtime =
            match resource_runtime::ZoneResourceRuntime::open_production_with_identity(
                zone.clone(),
                opened,
                audit_sink,
                Arc::clone(&broker_evidence),
                telemetry_path,
                desired_bundle,
                authority,
            )
            .await
            {
                Ok(runtime) => runtime,
                Err(error) => {
                    tracing::error!(zone = %zone_name, error = ?error, "Zone resource runtime store open failed");
                    shutdown_unpublished_runtimes(&mut prepared_runtimes).await;
                    return Err(error);
                }
            };
        runtime.set_provider_path_ready(provider_ready);
        let descriptors = materialization_bundle
            .resources
            .iter()
            .filter(|resource| resource.resource_type().as_str() == "Guest")
            .filter_map(|resource| {
                resolver
                    .guest_setup_descriptor_bytes(
                        zone.as_str(),
                        resource.metadata().name().as_str(),
                    )
                    .map(|bytes| {
                        (
                            resource.metadata().name().as_str().to_owned(),
                            bytes.to_vec(),
                        )
                    })
            });
        runtime.set_guest_setup_descriptors(descriptors);
        let descriptor_catalog_keys = materialization_bundle
            .resources
            .iter()
            .filter(|resource| resource.resource_type().as_str() == "Guest")
            .filter_map(|resource| {
                resolver
                    .guest_setup_descriptor_catalog_key(
                        zone.as_str(),
                        resource.metadata().name().as_str(),
                    )
                    .map(|key| {
                        (
                            resource.metadata().name().as_str().to_owned(),
                            key.to_owned(),
                        )
                    })
            });
        runtime.set_guest_setup_descriptor_catalog_keys(descriptor_catalog_keys);
        prepared_runtimes.push((zone, runtime, materialization_bundle));
    }

    for index in 0..prepared_runtimes.len() {
        let validation = {
            let (zone, runtime, bundle) = &prepared_runtimes[index];
            runtime
                .validate_desired_bundle(bundle)
                .await
                .inspect_err(|error| {
                    tracing::error!(
                        zone = %zone.as_str(),
                        error = ?error,
                        "resource plane Zone bundle validation failed"
                    );
                })
        };
        if let Err(error) = validation {
            shutdown_unpublished_runtimes(&mut prepared_runtimes).await;
            return Err(error);
        }
    }

    let coordinator_index = prepared_runtimes
        .iter()
        .position(|(zone, _, _)| zone == &topology.root)
        .ok_or_else(|| resource_runtime::ResourceRuntimeError::HandlerNotReady)?;
    let prepare_result = prepared_runtimes[coordinator_index]
        .1
        .prepare_generation_publication(&set_generation, &prepared_generations)
        .await
        .inspect_err(|error| {
            tracing::error!(
                zone = %topology.root.as_str(),
                error = ?error,
                "resource plane generation publication prepare failed"
            );
        });
    if let Err(error) = prepare_result {
        shutdown_unpublished_runtimes(&mut prepared_runtimes).await;
        return Err(error);
    }

    for index in 0..prepared_runtimes.len() {
        let preparation = {
            let (zone, runtime, bundle) = &prepared_runtimes[index];
            runtime
                .prepare_published_bundle(bundle)
                .await
                .inspect_err(|error| {
                    tracing::error!(
                        zone = %zone.as_str(),
                        error = ?error,
                        "resource plane Zone bundle preparation failed"
                    );
                })
        };
        if let Err(error) = preparation {
            shutdown_unpublished_runtimes(&mut prepared_runtimes).await;
            return Err(error);
        }
    }

    for index in 0..prepared_runtimes.len() {
        let (zone, runtime, _) = &prepared_runtimes[index];
        let pending_operation_ids = match runtime.pending_trusted_activation_operation_ids().await {
            Ok(operation_ids) => operation_ids,
            Err(error) => {
                shutdown_unpublished_runtimes(&mut prepared_runtimes).await;
                return Err(error);
            }
        };
        for operation_id in pending_operation_ids {
            let evidence = match ensure_resource_activation_broker_evidence(
                state,
                zone,
                &operation_id,
                &broker_evidence,
            )
            .await
            {
                Ok(evidence) => evidence,
                Err(error) => {
                    shutdown_unpublished_runtimes(&mut prepared_runtimes).await;
                    return Err(error);
                }
            };
            if let Err(error) = runtime
                .ingest_broker_evidence(&operation_id, evidence)
                .await
            {
                shutdown_unpublished_runtimes(&mut prepared_runtimes).await;
                return Err(error);
            }
        }
        if let Err(error) = runtime.require_trusted_activation_outboxes_drained().await {
            shutdown_unpublished_runtimes(&mut prepared_runtimes).await;
            return Err(error);
        }
    }

    let commit_result = prepared_runtimes[coordinator_index]
        .1
        .commit_generation_publication(&set_generation, &prepared_generations)
        .await
        .inspect_err(|error| {
            tracing::error!(
                zone = %topology.root.as_str(),
                error = ?error,
                "resource plane generation publication commit failed"
            );
        });
    if let Err(error) = commit_result {
        shutdown_unpublished_runtimes(&mut prepared_runtimes).await;
        return Err(error);
    }

    let mut remaining = prepared_runtimes.into_iter();
    while let Some((_zone, mut runtime, _)) = remaining.next() {
        let installed_provider_count = state
            .provider_runtime
            .registered_provider_count()
            .try_into()
            .unwrap_or(u32::MAX);
        if let Err(error) = runtime.activate_published_bundle().await {
            let _ = runtime.shutdown().await;
            let _ = plane.shutdown().await;
            while let Some((_, runtime, _)) = remaining.next() {
                let _ = runtime.shutdown().await;
            }
            return Err(error);
        }
        let _ = runtime.publish_provider_counts(
            installed_provider_count,
            if provider_ready {
                installed_provider_count
            } else {
                0
            },
        );
        if let Err(error) = runtime
            .reconcile_process_resources(Arc::new(state.clone()))
            .await
        {
            let _ = runtime.shutdown().await;
            let _ = plane.shutdown().await;
            while let Some((_, runtime, _)) = remaining.next() {
                let _ = runtime.shutdown().await;
            }
            return Err(error);
        }
        if let Err(error) = runtime
            .reconcile_activation_resources(Arc::new(state.clone()))
            .await
        {
            tracing::warn!(
                zone = %runtime.zone().as_str(),
                error = ?error,
                "activation reconciliation degraded during startup",
            );
        }
        if let Err(error) = runtime
            .reconcile_audio_resources(Arc::new(state.clone()))
            .await
        {
            tracing::warn!(
                zone = %runtime.zone().as_str(),
                error = ?error,
                "audio reconciliation degraded during startup",
            );
        }
        if let Err(error) = runtime.reconcile_semantic_binding_resources().await {
            tracing::warn!(
                zone = %runtime.zone().as_str(),
                error = ?error,
                "semantic binding reconciliation degraded during startup",
            );
        }
        let _ = runtime.audio_binding_statuses();
        if let Err(error) = runtime.require_ready() {
            let _ = runtime.shutdown().await;
            let _ = plane.shutdown().await;
            while let Some((_, runtime, _)) = remaining.next() {
                let _ = runtime.shutdown().await;
            }
            return Err(error);
        }
        if !runtime.device_tpm_controller_registered() {
            let _ = runtime.shutdown().await;
            let _ = plane.shutdown().await;
            while let Some((_, runtime, _)) = remaining.next() {
                let _ = runtime.shutdown().await;
            }
            return Err(resource_runtime::ResourceRuntimeError::ProviderPathUnavailable);
        }
        if let Err(error) = plane.insert(runtime) {
            let _ = plane.shutdown().await;
            while let Some((_, runtime, _)) = remaining.next() {
                let _ = runtime.shutdown().await;
            }
            return Err(error);
        }
    }
    compose_gateway_zone_links(state, &mut plane, &topology).await;
    if plane.ready_zone_count() == 0 {
        let _ = plane.shutdown().await;
        return Err(resource_runtime::ResourceRuntimeError::PlaneUnavailable);
    }
    Ok(Arc::new(plane))
}

/// Compose child-local ZoneLink state after every Zone has passed the
/// generation publication barrier. The host keeps only route metadata and
/// placement refs; credential acquisition remains a Gateway Guest concern.
async fn compose_gateway_zone_links(
    state: &ServerState,
    plane: &mut resource_runtime::ResourcePlane,
    topology: &CommittedZoneTopology,
) {
    let Some(root) = plane.zone(&topology.root).ok() else {
        return;
    };
    let Some(authority_digest) = root
        .authority_bundle_generation()
        .map(|value| value.as_str().to_owned())
    else {
        tracing::error!("Gateway Guest composition refused: root Zone generation unavailable");
        return;
    };
    let authority_generation = root.current_revision().get().max(1);
    let zones = plane.zone_ids();
    for zone in zones {
        if zone == topology.root {
            continue;
        }
        let Some(parent_zone) = topology.parent(&zone) else {
            tracing::warn!(
                zone = %zone,
                "Gateway Guest composition skipped: parent Zone topology is unavailable",
            );
            continue;
        };
        let Some(parent_path) = topology.path(parent_zone) else {
            tracing::warn!(
                zone = %zone,
                "Gateway Guest composition skipped: parent Zone path is unavailable",
            );
            continue;
        };
        let Some(child_path) = topology.path(&zone) else {
            tracing::warn!(
                zone = %zone,
                "Gateway Guest composition skipped: child Zone path is unavailable",
            );
            continue;
        };
        let Some(parent) = plane.zone(parent_zone).ok() else {
            tracing::warn!(
                zone = %zone,
                parent = %parent_zone,
                "Gateway Guest composition skipped: parent Zone runtime unavailable",
            );
            continue;
        };
        let Some(parent_uid) = parent.authority_zone_uid().cloned() else {
            tracing::warn!(
                zone = %zone,
                parent = %parent_zone,
                "Gateway Guest composition skipped: parent Zone identity unavailable",
            );
            continue;
        };
        let Some(runtime) = plane.zone(&zone).ok() else {
            continue;
        };
        let links = match runtime.committed_resources_of_type("ZoneLink").await {
            Ok(links) => links,
            Err(error) => {
                tracing::warn!(
                    zone = %zone,
                    error = ?error,
                    "Gateway Guest composition skipped: ZoneLink rows unavailable",
                );
                continue;
            }
        };
        let matching_links = links
            .into_iter()
            .filter(|resource| {
                resource
                    .get("metadata")
                    .and_then(|metadata| metadata.get("zone"))
                    .and_then(Value::as_str)
                    == Some(zone.as_str())
            })
            .collect::<Vec<_>>();
        let link = match matching_links.as_slice() {
            [] => continue,
            [link] => link,
            _ => {
                if matching_links.iter().any(is_gateway_zone_link) {
                    plane.refuse_gateway_zone_link(zone.clone());
                }
                tracing::warn!(
                    zone = %zone,
                    "Gateway Guest composition refused: multiple committed ZoneLink rows",
                );
                continue;
            }
        };
        if !is_gateway_zone_link(link) {
            continue;
        }
        let Some(child_uid) = runtime.authority_zone_uid().cloned() else {
            plane.refuse_gateway_zone_link(zone.clone());
            tracing::warn!(
                zone = %zone,
                "Gateway Guest composition skipped: child Zone identity unavailable",
            );
            continue;
        };
        let composition = match ZoneLinkGatewayComposition::from_committed_resources(
            zone.clone(),
            parent_path,
            child_path,
            parent_uid,
            child_uid,
            authority_generation,
            &authority_digest,
            link,
        ) {
            Ok(composition) => composition,
            Err(error) => {
                plane.refuse_gateway_zone_link(zone.clone());
                tracing::warn!(
                    zone = %zone,
                    error = error.code(),
                    "Gateway Guest composition refused",
                );
                continue;
            }
        };
        let Some(gateway_guest) = gateway_guest_for_link(&runtime, link).await else {
            plane.refuse_gateway_zone_link(zone.clone());
            tracing::warn!(
                zone = %zone,
                "Gateway Guest composition refused: transport Provider Guest is unavailable",
            );
            if let Err(error) = plane.insert_gateway_zone_link(composition) {
                tracing::warn!(
                    zone = %zone,
                    error = ?error,
                    "Gateway Guest composition skipped: duplicate ZoneLink",
                );
            }
            continue;
        };
        composition.set_gateway_guest(gateway_guest.clone());
        let composition =
            match connect_guest_component_session_for_guest(state, &gateway_guest).await {
                Ok(session) => {
                    if let Err(error) = composition.bind_gateway_session(session) {
                        tracing::warn!(
                            zone = %zone,
                            error = error.code(),
                            "Gateway Guest session binding refused",
                        );
                    }
                    composition
                }
                Err(error) => {
                    tracing::warn!(
                        zone = %zone,
                        gateway = %gateway_guest.guest_ref().name().as_str(),
                        error = %error,
                        "Gateway Guest ComponentSession unavailable",
                    );
                    composition
                }
            };
        if let Err(error) = plane.insert_gateway_zone_link(composition) {
            tracing::warn!(
                zone = %zone,
                error = ?error,
                "Gateway Guest composition skipped: duplicate ZoneLink",
            );
        }
    }
}

async fn gateway_guest_for_link(
    runtime: &resource_runtime::ZoneResourceRuntime,
    link: &Value,
) -> Option<CommittedGuestSessionTarget> {
    let provider_ref = link
        .get("spec")
        .and_then(|spec| spec.get("transportProviderRef"))
        .and_then(Value::as_str)
        .and_then(|value| ResourceRef::parse(value).ok())?;
    gateway_guest_for_provider(runtime, &provider_ref).await
}

async fn gateway_guest_for_provider(
    runtime: &resource_runtime::ZoneResourceRuntime,
    provider_ref: &ResourceRef,
) -> Option<CommittedGuestSessionTarget> {
    let provider = runtime
        .committed_resource_value(provider_ref, "gateway-guest-provider")
        .await
        .ok()?;
    let guest_ref = provider
        .get("spec")
        .and_then(|spec| spec.get("config"))
        .and_then(|config| config.get("executionRef"))
        .and_then(Value::as_str)
        .and_then(|value| ResourceRef::parse(value).ok())
        .filter(|value| value.resource_type().as_str() == "Guest")?;
    resolve_committed_guest_session_target(runtime, &guest_ref)
        .await
        .ok()
}

fn is_gateway_zone_link(link: &Value) -> bool {
    link.get("spec")
        .and_then(|spec| spec.get("transportProviderRef"))
        .and_then(Value::as_str)
        == Some(d2b_provider_transport_azure_relay::PROVIDER_REF)
}

#[cfg(test)]
mod zone_publication_order_tests {
    #[test]
    fn complete_set_validation_and_durable_prepare_precede_all_mutating_reconcile() {
        let full_source = include_str!("composition.rs");
        let source = full_source
            .split_once("async fn open_resource_plane")
            .and_then(|(_, source)| source.split_once("const BROKER_AUDIT_EVIDENCE_PAGE_LIMIT"))
            .map(|(source, _)| source)
            .expect("resource-plane source span");
        let position = |needle: &str| {
            source
                .find(needle)
                .unwrap_or_else(|| panic!("missing publication step: {needle}"))
        };
        let validation = position("validate_desired_bundle");
        let durable_prepare = position("prepare_generation_publication");
        let store_open = position("open_zone_store_from_broker");
        let materialization = position("prepare_published_bundle");
        let pending_query = position("pending_trusted_activation_operation_ids");
        let evidence = position("ensure_resource_activation_broker_evidence(");
        let ingest = position("runtime\n                .ingest_broker_evidence");
        let barrier = position("require_trusted_activation_outboxes_drained");
        let durable_commit = position("commit_generation_publication");
        let activation = position("activate_published_bundle");
        let process_reconcile = position("reconcile_process_resources");

        assert!(validation < durable_prepare);
        assert!(durable_prepare < materialization);
        assert!(store_open < materialization);
        assert!(materialization < pending_query);
        assert!(pending_query < evidence);
        assert!(evidence < ingest);
        assert!(ingest < barrier);
        assert!(barrier < durable_commit);
        assert!(durable_commit < activation);
        assert!(activation < process_reconcile);
    }
}

const BROKER_AUDIT_EVIDENCE_PAGE_LIMIT: u32 = 16;

#[derive(serde::Deserialize)]
struct BrokerAuditEvidenceLine {
    #[serde(default)]
    zone_id: Option<AuditZoneId>,
    #[serde(default)]
    operation_identity: Option<OperationIdentity>,
    #[serde(default)]
    decision: Option<String>,
    #[serde(default)]
    result: Option<String>,
    #[serde(default)]
    zone_operation_key: Option<ZoneOperationKey>,
}

fn load_broker_audit_evidence(
    state: &ServerState,
) -> Result<Arc<d2b_resource_store_redb::BrokerEvidenceIndex>, resource_runtime::ResourceRuntimeError>
{
    let mut evidence: BTreeMap<d2b_audit::ZoneOperationKey, d2b_audit::DurabilityEvidence> =
        BTreeMap::new();
    let mut cursor = None;
    for _ in 0..1024 {
        let response = dispatch_broker_request_as(
            state,
            BrokerRequest::ExportBrokerAudit(ExportBrokerAuditRequest {
                filter: None,
                since: None,
                cursor: cursor.clone(),
                limit: BROKER_AUDIT_EVIDENCE_PAGE_LIMIT,
            }),
            BrokerCallerRole::AdminUid {
                uid: state.daemon_uid,
            },
        )
        .inspect_err(|error| {
            tracing::error!(
                error = ?error,
                "broker audit evidence export dispatch failed",
            );
        })
        .map_err(|_| resource_runtime::ResourceRuntimeError::StoreOpenFailed)?;
        let BrokerResponse::ExportBrokerAudit(response) = response else {
            tracing::error!("broker audit evidence export returned an unexpected response");
            return Err(resource_runtime::ResourceRuntimeError::StoreOpenFailed);
        };
        for entry in response.entries {
            if let Some(error) = entry.error {
                tracing::error!(
                    error = ?error,
                    "broker audit evidence entry reported an error",
                );
                return Err(resource_runtime::ResourceRuntimeError::StoreOpenFailed);
            }
            let value = entry
                .record
                .ok_or(resource_runtime::ResourceRuntimeError::StoreOpenFailed)?;
            let record_class = value
                .get("record_class")
                .and_then(Value::as_str)
                .map(str::to_owned);
            let diagnostic_or_legacy = record_class.as_deref() != Some("durability")
                || value
                    .get("durability")
                    .and_then(Value::as_bool)
                    .is_some_and(|durability| !durability);
            if diagnostic_or_legacy {
                continue;
            }
            let parsed = serde_json::from_value::<BrokerAuditEvidenceLine>(value)
                .inspect_err(|_| {
                    tracing::error!("broker durability evidence entry failed schema decoding");
                })
                .map_err(|_| resource_runtime::ResourceRuntimeError::StoreOpenFailed)?;
            let (
                Some(zone_id),
                Some(operation_identity),
                Some(decision),
                Some(result),
                Some(zone_operation_key),
            ) = (
                parsed.zone_id,
                parsed.operation_identity,
                parsed.decision,
                parsed.result,
                parsed.zone_operation_key,
            )
            else {
                tracing::error!(
                    record_class = ?record_class,
                    "broker durability evidence entry is incomplete",
                );
                return Err(resource_runtime::ResourceRuntimeError::StoreOpenFailed);
            };
            let item = evidence_from_decision_result(
                zone_id,
                operation_identity,
                Some(&zone_operation_key),
                Some(&decision),
                Some(&result),
            )
            .inspect_err(|_| {
                tracing::error!("broker durability evidence entry failed semantic conversion");
            })
            .map_err(|_| resource_runtime::ResourceRuntimeError::StoreOpenFailed)?;
            let key = item.key.clone();
            if let Some(previous) = evidence.get(&key) {
                let retry_succeeded = previous.outcome == d2b_audit::DurabilityOutcome::Failure
                    && !previous.effect_durable
                    && item.outcome == d2b_audit::DurabilityOutcome::Success
                    && item.effect_durable;
                if previous != &item && !retry_succeeded {
                    tracing::error!(
                        operation_identity = %item.key.operation().as_str(),
                        previous_outcome = ?previous.outcome,
                        current_outcome = ?item.outcome,
                        previous_effect_durable = previous.effect_durable,
                        current_effect_durable = item.effect_durable,
                        "broker durability evidence entries conflict for one operation",
                    );
                    return Err(resource_runtime::ResourceRuntimeError::StoreOpenFailed);
                }
            }
            evidence.insert(key, item);
        }
        if response.complete {
            return Ok(Arc::new(d2b_resource_store_redb::BrokerEvidenceIndex::new(
                evidence,
            )));
        }
        cursor = response.next_cursor;
        if cursor.is_none() {
            tracing::error!("broker audit evidence pagination omitted its continuation cursor");
            return Err(resource_runtime::ResourceRuntimeError::StoreOpenFailed);
        }
    }
    tracing::error!("broker audit evidence pagination exceeded its bounded page count");
    Err(resource_runtime::ResourceRuntimeError::StoreOpenFailed)
}

fn audit_resource_plane(
    state: &ServerState,
    zone: &d2b_contracts_resource::v3::ZoneId,
    action: d2bd_runtime::daemon_audit::ResourcePlaneAction,
    result: d2bd_runtime::daemon_audit::ResourcePlaneResult,
) -> Result<(), std::io::Error> {
    state.daemon_audit.write_event_with_authority(
        &d2bd_runtime::daemon_audit::DaemonEvent::ResourcePlaneLifecycle {
            zone: zone.as_str().to_owned(),
            action,
            result,
        },
        d2bd_runtime::daemon_audit::DaemonAuditLog::authority_for(
            &d2bd_runtime::daemon_audit::DaemonEvent::ResourcePlaneLifecycle {
                zone: zone.as_str().to_owned(),
                action,
                result,
            },
        ),
    )
}

fn record_authoritative_resource_plane_audit(
    state: &ServerState,
    zone: &d2b_contracts_resource::v3::ZoneId,
    action: d2bd_runtime::daemon_audit::ResourcePlaneAction,
    result: d2bd_runtime::daemon_audit::ResourcePlaneResult,
) -> Result<(), std::io::Error> {
    audit_resource_plane(state, zone, action, result)
}

async fn shutdown_resource_plane(state: &ServerState) -> Result<(), std::io::Error> {
    let plane = state
        .resource_plane
        .lock()
        .ok()
        .and_then(|mut slot| slot.take());
    if let Some(plane) = plane {
        let zones = plane.zone_ids();
        match Arc::try_unwrap(plane) {
            Ok(plane) if plane.has_live_request_owners() => {
                for zone in &zones {
                    record_authoritative_resource_plane_audit(
                        state,
                        zone,
                        d2bd_runtime::daemon_audit::ResourcePlaneAction::Shutdown,
                        d2bd_runtime::daemon_audit::ResourcePlaneResult::Refused,
                    )?;
                }
                match state.resource_plane.lock() {
                    Ok(mut slot) => *slot = Some(Arc::new(plane)),
                    Err(_) => std::mem::forget(plane),
                }
            }
            Ok(mut plane) => match plane.shutdown().await {
                Ok(()) => {
                    for zone in &zones {
                        record_authoritative_resource_plane_audit(
                            state,
                            zone,
                            d2bd_runtime::daemon_audit::ResourcePlaneAction::Shutdown,
                            d2bd_runtime::daemon_audit::ResourcePlaneResult::Closed,
                        )?;
                    }
                }
                Err(resource_runtime::ResourceRuntimeError::LiveRequestOwners) => {
                    for zone in &zones {
                        record_authoritative_resource_plane_audit(
                            state,
                            zone,
                            d2bd_runtime::daemon_audit::ResourcePlaneAction::Shutdown,
                            d2bd_runtime::daemon_audit::ResourcePlaneResult::Refused,
                        )?;
                    }
                    match state.resource_plane.lock() {
                        Ok(mut slot) => *slot = Some(Arc::new(plane)),
                        Err(_) => std::mem::forget(plane),
                    }
                    tracing::warn!("resource plane still has live request owners during shutdown");
                }
                Err(error) => {
                    for zone in &zones {
                        record_authoritative_resource_plane_audit(
                            state,
                            zone,
                            d2bd_runtime::daemon_audit::ResourcePlaneAction::Shutdown,
                            d2bd_runtime::daemon_audit::ResourcePlaneResult::Error,
                        )?;
                    }
                    tracing::warn!(error = %error, "resource plane shutdown failed");
                }
            },
            Err(plane) => {
                match state.resource_plane.lock() {
                    Ok(mut slot) => *slot = Some(plane),
                    Err(_) => std::mem::forget(plane),
                }
                for zone in &zones {
                    record_authoritative_resource_plane_audit(
                        state,
                        zone,
                        d2bd_runtime::daemon_audit::ResourcePlaneAction::Shutdown,
                        d2bd_runtime::daemon_audit::ResourcePlaneResult::Refused,
                    )?;
                }
                tracing::warn!("resource plane still has live request owners during shutdown");
            }
        }
    }
    Ok(())
}

fn acquire_vm_start_lock(state: &ServerState, vm: &str) -> Result<Flock<File>, TypedError> {
    let path = state.config.locks_dir.join(format!("vm-start-{vm}.lock"));
    let file = OpenOptions::new()
        .create(true)
        .truncate(false)
        .write(true)
        .open(&path)
        .map_err(|err| TypedError::InternalIo {
            context: format!("open VM start lock {}", path.display()),
            detail: err.to_string(),
        })?;
    Flock::lock(file, FlockArg::LockExclusive).map_err(|(_file, err)| TypedError::InternalIo {
        context: format!("lock VM start lock {}", path.display()),
        detail: err.to_string(),
    })
}

#[derive(Debug)]
enum VmRunnerLaunch {
    Legacy(Box<d2b_contracts_broker::broker_wire::SpawnRunnerResponse>),
    Provider,
    ControllerOwned,
}

fn network_tap_context_from_admission(
    admission: &NetworkAdmissionProof,
    attachment_id: ResourceUid,
) -> d2b_contracts_broker::broker_wire::NetworkTapContext {
    let key = admission.key();
    d2b_contracts_broker::broker_wire::NetworkTapContext {
        zone_uid: key.zone_uid().clone(),
        network_uid: key.network_uid().clone(),
        attachment_id,
        network_generation: key.network_generation(),
        attachment_generation: key.attachment_generation(),
        bundle_generation: key.bundle_generation().clone(),
        admitted_interface_names: admission.intent().interface_names().to_vec(),
    }
}

fn network_tap_context_for_vm(
    state: &ServerState,
    resolver: &BundleResolver,
    vm_name: &str,
) -> Option<d2b_contracts_broker::broker_wire::NetworkTapContext> {
    let plane = state.resource_plane.lock().ok()?.clone()?;
    let mut resolved = None;
    for zone in plane.zone_ids() {
        let Ok(runtime) = plane.zone(&zone) else {
            continue;
        };
        let Ok(guests) = block_on_future(runtime.committed_resources_of_type("Guest")) else {
            continue;
        };
        let Some(guest) = guests.into_iter().find(|guest| {
            guest
                .get("metadata")
                .and_then(|metadata| metadata.get("name"))
                .and_then(Value::as_str)
                == Some(vm_name)
        }) else {
            continue;
        };
        let guest_uid = guest
            .get("metadata")
            .and_then(|metadata| metadata.get("uid"))
            .and_then(Value::as_str)
            .and_then(|value| ResourceUid::parse(value.to_owned()).ok())?;
        let Some(attachment) = guest
            .get("spec")
            .and_then(|spec| spec.get("networkAttachments"))
            .and_then(Value::as_array)
            .and_then(|attachments| attachments.first())
        else {
            continue;
        };
        let Some(network_ref) = attachment
            .get("networkRef")
            .and_then(Value::as_str)
            .and_then(|value| ResourceRef::parse(value).ok())
        else {
            continue;
        };
        let Ok(networks) = block_on_future(runtime.committed_resources_of_type("Network")) else {
            continue;
        };
        let Some(network) = networks.into_iter().find(|network| {
            network
                .get("metadata")
                .and_then(|metadata| metadata.get("name"))
                .and_then(Value::as_str)
                == Some(network_ref.name().as_str())
        }) else {
            continue;
        };
        let network_uid = network
            .get("metadata")
            .and_then(|metadata| metadata.get("uid"))
            .and_then(Value::as_str)
            .and_then(|value| ResourceUid::parse(value.to_owned()).ok())?;
        let network_generation = network
            .get("metadata")
            .and_then(|metadata| metadata.get("generation"))
            .and_then(Value::as_u64)
            .and_then(|value| ResourceGeneration::new(value).ok())?;
        let Ok(zone_resources) = block_on_future(runtime.committed_resources_of_type("Zone"))
        else {
            continue;
        };
        let Some(zone_resource) = zone_resources.first() else {
            continue;
        };
        let zone_uid = zone_resource
            .get("metadata")
            .and_then(|metadata| metadata.get("uid"))
            .and_then(Value::as_str)
            .and_then(|value| ResourceUid::parse(value.to_owned()).ok())?;
        let admission_index = plane.network_admission_index();
        let admission_zone_uid = zone_uid.clone();
        let admission_network_uid = network_uid.clone();
        let Some(admission) = block_on_future(async move {
            admission_index
                .lock()
                .await
                .proof_for(&admission_zone_uid, &admission_network_uid)
        }) else {
            continue;
        };
        if admission.key().network_generation() != network_generation
            || resolver
                .installed_generation_identity()
                .is_none_or(|identity| {
                    identity.as_str() != admission.key().bundle_generation().as_str()
                })
        {
            continue;
        }
        let Some(bundle_bytes) = resolver.zone_resource_bundle_bytes(zone.as_str()) else {
            continue;
        };
        let Ok(bundle) = ResourceBundle::from_json(bundle_bytes) else {
            continue;
        };
        if bundle.zone_uid.as_ref() != Some(&zone_uid) {
            continue;
        }
        if resolved.is_some() {
            return None;
        }
        resolved = Some(network_tap_context_from_admission(&admission, guest_uid));
    }
    resolved
}

struct VmStartRunner<'a> {
    state: &'a ServerState,
    resolver: &'a BundleResolver,
    caller_role: BrokerCallerRole,
    lifecycle_authorization: Option<provider_effects::LifecycleAuthorization>,
    /// Workload identity from the `VmProcessDag` this runner was constructed
    /// for.  `None` for VMs that predate realm workload declarations; `Some`
    /// for VMs declared as realm workloads.  Threaded into every
    /// `SpawnRunner` request so the broker can record the identity in the
    /// audit trail and privilege metadata without re-reading the process DAG.
    workload_identity: Option<WorkloadIdentity>,
    network_tap_context: Option<d2b_contracts_broker::broker_wire::NetworkTapContext>,
}

impl VmStartRunner<'_> {
    fn sync_store_view(&self, vm: &str) -> Result<(), String> {
        let intent = resolve_store_view_intent_for_vm(self.resolver, vm)?;
        match dispatch_broker_request_as(
            self.state,
            BrokerRequest::StoreSync(d2b_contracts_broker::broker_wire::StoreSyncRequest {
                vm_id: VmId::new(vm),
                bundle_closure_ref: BundleClosureRef::new(intent.intent_id.clone()),
                generation_token: u32::try_from(intent.generation)
                    .map_err(|_| "store-view-generation-overflow".to_owned())?,
                tracing_span_id: None,
            }),
            self.caller_role.clone(),
        ) {
            Ok(BrokerResponse::StoreSync(_)) => Ok(()),
            Ok(BrokerResponse::Error(error)) => {
                tracing::warn!(
                    vm = %vm,
                    broker_kind = %error.kind,
                    broker_operation = %error.operation,
                    broker_message = %error.message,
                    broker_action = %error.action,
                    "StoreSync preflight dispatch failed"
                );
                Err(format!("broker-error:StoreSync:{}", error.kind))
            }
            Ok(other) => {
                tracing::warn!(
                    vm = %vm,
                    broker_response_kind = %broker_response_kind(&other),
                    "StoreSync preflight returned unexpected broker response"
                );
                Err("broker-protocol:StoreSync".to_owned())
            }
            Err(error) => {
                tracing::warn!(
                    vm = %vm,
                    error = ?error,
                    "StoreSync preflight dispatch failed"
                );
                Err("broker-dispatch:StoreSync".to_owned())
            }
        }
    }

    fn spawn_runner(
        &self,
        vm: &str,
        node: &ProcessNode,
        runner_role: RunnerRole,
        timeout: Duration,
    ) -> Result<VmRunnerLaunch, String> {
        if node.role == ProcessRole::CloudHypervisorRunner {
            return Ok(VmRunnerLaunch::ControllerOwned);
        }
        let intent_id = intent_id_legacy_runner(vm, &node.id.0);
        let intent = self
            .resolver
            .find_runner_intent(&intent_id)
            .ok_or_else(|| "bundle-intent-missing".to_owned())?;
        let role_id = tracked_role_id(node);
        // Dispatch DiskInit before SpawnRunner when the ProcessNode declares
        // disk initialization plan operations. The broker resolves those
        // operations from the trusted bundle and creates the disk images
        // required by the runtime.
        if node_requires_disk_init_dispatch(node) {
            match dispatch_broker_request_as(
                self.state,
                BrokerRequest::DiskInit(d2b_contracts_broker::broker_wire::DiskInitRequest {
                    vm_id: VmId::new(vm),
                    tracing_span_id: None,
                }),
                self.caller_role.clone(),
            ) {
                Ok(BrokerResponse::Ack(_)) => {
                    tracing::info!(
                        vm = %vm,
                        node = %node.id.0,
                        plan_op_count = node.plan_ops.len(),
                        "v1.2fu46: DiskInit plan-ops applied before SpawnRunner"
                    );
                }
                Ok(BrokerResponse::Error(error)) => {
                    tracing::warn!(
                        vm = %vm,
                        node = %node.id.0,
                        broker_kind = %error.kind,
                        broker_operation = %error.operation,
                        broker_target_wave = error.target_wave.as_deref().unwrap_or("none"),
                        broker_message = %error.message,
                        broker_action = %error.action,
                        "v1.2fu46: DiskInit pre-SpawnRunner dispatch failed"
                    );
                    return Err(format!("broker-error:DiskInit:{}", error.kind));
                }
                Ok(other) => {
                    tracing::warn!(
                        vm = %vm,
                        node = %node.id.0,
                        broker_response_kind = %broker_response_kind(&other),
                        "v1.2fu46: DiskInit returned unexpected broker response"
                    );
                    return Err("broker-protocol:DiskInit".to_owned());
                }
                Err(error) => {
                    tracing::warn!(
                        vm = %vm,
                        node = %node.id.0,
                        error = ?error,
                        "v1.2fu46: DiskInit dispatch failed"
                    );
                    return Err("broker-dispatch:DiskInit".to_owned());
                }
            }
        }
        if process_provider_runtime::ProductionProcessProviders::supports_node(node) {
            let providers = self
                .state
                .provider_runtime
                .process_providers()
                .ok_or_else(|| "provider-runtime-unavailable".to_owned())?;
            block_on_future(providers.launch_node(vm, node, timeout))?;
            return Ok(VmRunnerLaunch::Provider);
        }
        match dispatch_broker_request_with_fds_timeout_as(
            self.state,
            BrokerRequest::SpawnRunner(BrokerSpawnRunnerRequest {
                execution_ref: None,
                execution_domain: None,
                user_ref: None,
                workload_identity: self.workload_identity.clone(),
                vm_id: VmId::new(vm),
                role_id: RoleId::new(role_id.clone()),
                resource_ref: None,
                resource_uid: None,
                zone_uid: None,
                owner_ref: None,
                owner_uid: None,
                provider_ref: None,
                bundle_content_identity: None,
                provider_identity: None,
                template_identity: None,
                generation: None,
                runtime_scope: None,
                activation_input: None,
                sandbox_plan: None,
                guest_execution: None,
                role: runner_role,
                bundle_runner_intent_ref: BundleOpId::new(intent.intent_id.clone()),
                runtime_allocations: vec![],
                tracing_span_id: None,
                inherited_fd_count: 0,
                network_tap_context: self.network_tap_context.clone(),
            }),
            self.caller_role.clone(),
            timeout,
        ) {
            Ok((BrokerResponse::SpawnRunner(response), received_fds)) => {
                if let Err(error) =
                    self.register_node_pidfd(vm, node, runner_role, &response, &received_fds)
                {
                    stop_unregistered_spawned_runner(
                        self.state,
                        vm,
                        &role_id,
                        &response,
                        &received_fds,
                        self.caller_role.clone(),
                    );
                    close_received_fds(&received_fds);
                    return Err(error);
                }
                close_received_fds(&received_fds);
                Ok(VmRunnerLaunch::Legacy(Box::new(response)))
            }
            Ok((BrokerResponse::Error(error), received_fds)) => {
                close_received_fds(&received_fds);
                tracing::warn!(
                    node = %node.id.0,
                    broker_kind = %error.kind,
                    broker_operation = %error.operation,
                    broker_target_wave = error.target_wave.as_deref().unwrap_or("none"),
                    broker_message = %error.message,
                    broker_action = %error.action,
                    "vm start node spawn failed"
                );
                Err(format!("broker-error:{}", error.kind))
            }
            Ok((other, received_fds)) => {
                close_received_fds(&received_fds);
                tracing::warn!(
                    node = %node.id.0,
                    broker_response_kind = %broker_response_kind(&other),
                    "vm start node received unexpected broker response"
                );
                Err("broker-protocol".to_owned())
            }
            Err(error) => {
                tracing::warn!(node = %node.id.0, error = ?error, "vm start node dispatch failed");
                Err("broker-dispatch".to_owned())
            }
        }
    }

    fn register_node_pidfd(
        &self,
        vm: &str,
        node: &ProcessNode,
        runner_role: RunnerRole,
        response: &d2b_contracts_broker::broker_wire::SpawnRunnerResponse,
        received_fds: &[RawFd],
    ) -> Result<(), String> {
        let VmStartNodeMode::LongLived(_) = vm_start_node_mode(&node.role) else {
            return Ok(());
        };
        let pidfd = duplicate_received_fd(
            received_fds,
            response.pidfd_index,
            "duplicate SpawnRunner pidfd",
        )
        .map_err(|error| error.message())?;
        let role_id = tracked_role_id(node);
        // Serialize register + snapshot as one unit so a concurrent
        // different-VM op cannot persist a stale snapshot that drops this
        // entry (register A, snapshot A reads {A}, register B, snapshot B
        // writes {A,B}, delayed snapshot A overwrites with {A} - losing B).
        let _mguard = self.state.pidfd_table.mutation_guard();
        self.state
            .pidfd_table
            .register(
                vm.to_owned(),
                role_id.clone(),
                PidfdEntry {
                    pidfd,
                    pid: response.pid,
                    start_time_ticks: response.start_time_ticks,
                },
            )
            .map_err(|error| format!("pidfd-register:{error}"))?;
        if let Err(error) = self.state.pidfd_table.snapshot() {
            let _ = self.state.pidfd_table.deregister(vm, &role_id);
            return Err(format!("pidfd-snapshot:{error}"));
        }
        // The pidfd-table register + snapshot sequence is now complete and
        // consistent, so release the serialization guard BEFORE
        // `write_runner_snapshot` (which writes a separate runner-snapshot
        // file and never touches the pidfd table). Holding it across the
        // failure path below would self-deadlock: `cleanup_vm_start_registration`
        // re-acquires this same non-reentrant guard.
        drop(_mguard);
        if let Err(error) = write_runner_snapshot_with_authorization(
            self.state,
            vm,
            &role_id,
            runner_role,
            response.pid,
            response.start_time_ticks,
            None,
            self.lifecycle_authorization.as_ref(),
        ) {
            cleanup_vm_start_registration(self.state, vm, &role_id);
            return Err(error);
        }
        if matches!(runner_role, RunnerRole::QemuMedia)
            && let Some(console_fd_index) = response.console_fd_index
        {
            let console_fd = duplicate_received_fd(
                received_fds,
                console_fd_index,
                "duplicate qemu-media console fd",
            )
            .map_err(|error| {
                cleanup_vm_start_registration(self.state, vm, &role_id);
                error.message()
            })?;
            let console_stream: UnixStream = console_fd.into();
            self.state
                .console_sessions
                .lock()
                .unwrap()
                .register_session(
                    vm.to_owned(),
                    console_session::create_qemu_session(console_stream),
                );
        }
        Ok(())
    }

    fn boot_qemu_media(
        &self,
        vm: &str,
        node: &ProcessNode,
        timeout: Duration,
    ) -> Result<(), String> {
        match dispatch_broker_request_with_timeout_as(
            self.state,
            BrokerRequest::QemuMediaBoot(BrokerQemuMediaBootRequest {
                vm_id: VmId::new(vm),
                tracing_span_id: None,
            }),
            self.caller_role.clone(),
            timeout,
        ) {
            Ok(BrokerResponse::QemuMediaBoot(response)) => {
                tracing::info!(
                    vm = %vm,
                    node = %node.id.0,
                    role_id = %tracked_role_id(node),
                    media_ref = %response.media_ref.as_str(),
                    slot = %response.slot,
                    qmp_commands = ?response.qmp_commands,
                    "qemu-media boot source attached and runner continued"
                );
                Ok(())
            }
            Ok(BrokerResponse::Error(error)) => {
                tracing::warn!(
                    vm = %vm,
                    node = %node.id.0,
                    broker_kind = %error.kind,
                    broker_operation = %error.operation,
                    broker_message = %error.message,
                    broker_action = %error.action,
                    "qemu-media boot transaction failed"
                );
                Err(format!("broker-error:QemuMediaBoot:{}", error.kind))
            }
            Ok(other) => {
                tracing::warn!(
                    vm = %vm,
                    node = %node.id.0,
                    broker_response_kind = %broker_response_kind(&other),
                    "qemu-media boot transaction returned unexpected response"
                );
                Err("broker-protocol:QemuMediaBoot".to_owned())
            }
            Err(error) => {
                tracing::warn!(
                    vm = %vm,
                    node = %node.id.0,
                    error = ?error,
                    "qemu-media boot transaction dispatch failed"
                );
                Err("broker-dispatch:QemuMediaBoot".to_owned())
            }
        }
    }

    /// State-aware readiness for the Guest session node. Readiness is the
    /// authenticated ComponentSession; no Guest-local Endpoint projection,
    /// feature health RPC, or legacy component-session probe participates.
    async fn wait_for_guest_component_session(
        &self,
        vm: &str,
        node: &ProcessNode,
        budget: d2bd_runtime::supervisor::dag::NodeBudget,
    ) -> Result<(), String> {
        let deadline = Instant::now() + budget.readiness;
        let node_id = node.id.0.clone();
        loop {
            let remaining = deadline.saturating_duration_since(Instant::now());
            if remaining.is_zero() {
                return Err(format!("guest-component-session-not-ready:{node_id}"));
            }
            let attempt = tokio::time::timeout(
                remaining.min(d2bd_runtime::guest_component_session::COMPONENT_SESSION_ATTEMPT_CAP),
                connect_guest_component_session_fresh(self.state, vm),
            )
            .await;
            match attempt {
                Ok(Ok(_session)) => {
                    tracing::info!(
                        vm = %vm,
                        node = %node_id,
                        role_id = %tracked_role_id(node),
                        "Guest ComponentSession authenticated and ready"
                    );
                    return Ok(());
                }
                _ => {
                    invalidate_guest_component_session(self.state, vm).await;
                }
            }
            let delay = d2bd_runtime::guest_component_session::COMPONENT_SESSION_RETRY_BACKOFF
                .min(deadline.saturating_duration_since(Instant::now()));
            if delay.is_zero() {
                return Err(format!("guest-component-session-not-ready:{node_id}"));
            }
            tokio::time::sleep(delay).await;
        }
    }
}

#[async_trait::async_trait]
impl d2bd_runtime::supervisor::dag::NodeRunner for VmStartRunner<'_> {
    async fn spawn_and_wait_ready(
        &self,
        vm: &str,
        node: &ProcessNode,
        readiness: &[ReadinessPredicate],
        budget: d2bd_runtime::supervisor::dag::NodeBudget,
    ) -> Result<(), String> {
        if is_guest_owned_process_node(node) {
            return Ok(());
        }
        if is_durable_wayland_process_node(node) {
            return wait_for_readiness(node, readiness, budget.readiness, None);
        }
        // The authenticated Guest ComponentSession node is readiness-only but
        // needs daemon state (per-VM transport endpoint and peer credentials),
        // so it cannot go through the stateless
        // `wait_for_readiness` path. Intercept it here; this also covers the
        // `spawn_and_check_process_alive` fall-through, which delegates here.
        if node.role == ProcessRole::ComponentSessionHealth {
            return self
                .wait_for_guest_component_session(vm, node, budget)
                .await;
        }
        if node.role == ProcessRole::SecurityKeyFrontend {
            // Security-key relay/frontend ownership belongs to the
            // Provider/device-security-key controller. The legacy daemon
            // accept loop is not allowed to open a blanket hidraw device;
            // this legacy DAG node is readiness-only during the transition.
            return wait_for_readiness(node, readiness, budget.readiness, None);
        }
        match vm_start_node_mode(&node.role) {
            VmStartNodeMode::ReadinessOnly => {
                if node.role == ProcessRole::StoreVirtiofsPreflight {
                    self.sync_store_view(vm)?;
                }
                // ReadinessOnly nodes spawn no long-lived runner, so there
                // is no daemon-held pidfd to observe - no liveness probe.
                wait_for_readiness(node, readiness, budget.readiness, None)
            }
            VmStartNodeMode::OneShot(runner_role) => {
                match self.spawn_runner(vm, node, runner_role, budget.spawn)? {
                    VmRunnerLaunch::Legacy(response) => wait_for_one_shot_exit(
                        response.pid,
                        response.start_time_ticks,
                        budget.readiness,
                    ),
                    VmRunnerLaunch::Provider => {
                        let providers = self
                            .state
                            .provider_runtime
                            .process_providers()
                            .ok_or_else(|| "provider-runtime-unavailable".to_owned())?;
                        block_on_future(providers.wait_for_exit(vm, node, budget.readiness))
                    }
                    VmRunnerLaunch::ControllerOwned => {
                        Err("controller-owned-one-shot-process-invalid".to_owned())
                    }
                }
            }
            VmStartNodeMode::LongLived(runner_role) => {
                let launch = self.spawn_runner(vm, node, runner_role, budget.spawn)?;
                if matches!(launch, VmRunnerLaunch::ControllerOwned) {
                    return wait_for_readiness(node, readiness, budget.readiness, None);
                }
                let provider_liveness;
                let legacy_liveness;
                let liveness: &dyn d2bd_runtime::supervisor::readiness_liveness::LivenessProbe =
                    match &launch {
                        VmRunnerLaunch::Provider => {
                            let providers = self
                                .state
                                .provider_runtime
                                .process_providers()
                                .ok_or_else(|| "provider-runtime-unavailable".to_owned())?;
                            provider_liveness =
                                process_provider_runtime::ProviderLivenessProbe::new(
                                    providers.clone(),
                                    vm,
                                    node,
                                );
                            &provider_liveness
                        }
                        VmRunnerLaunch::Legacy(_) => {
                            legacy_liveness = d2bd_runtime::supervisor::readiness_liveness::PidfdLivenessProbe::new(
                            &self.state.pidfd_table,
                            &self.state.broker_reap_log,
                            vm,
                            tracked_role_id(node),
                        );
                            &legacy_liveness
                        }
                        VmRunnerLaunch::ControllerOwned => unreachable!("handled above"),
                    };
                wait_for_readiness(node, readiness, budget.readiness, Some(liveness))?;
                if node.role == ProcessRole::QemuMediaRunner {
                    self.boot_qemu_media(vm, node, budget.readiness)?;
                }
                tracing::info!(
                    vm = %vm,
                    node = %node.id.0,
                    role_id = %tracked_role_id(node),
                    provider_managed = matches!(launch, VmRunnerLaunch::Provider),
                    "vm start node registered and ready"
                );
                Ok(())
            }
        }
    }

    async fn spawn_and_check_process_alive(
        &self,
        vm: &str,
        node: &ProcessNode,
        budget: d2bd_runtime::supervisor::dag::NodeBudget,
    ) -> Result<(), String> {
        if is_guest_owned_process_node(node) || is_durable_wayland_process_node(node) {
            return Ok(());
        }
        match vm_start_node_mode(&node.role) {
            VmStartNodeMode::LongLived(runner_role) => {
                let launch = self.spawn_runner(vm, node, runner_role, budget.spawn)?;
                tracing::info!(
                    vm = %vm,
                    node = %node.id.0,
                    role_id = %tracked_role_id(node),
                    provider_managed = matches!(launch, VmRunnerLaunch::Provider),
                    "vm start node registered and process-alive"
                );
                Ok(())
            }
            _ => self.spawn_and_wait_ready(vm, node, &[], budget).await,
        }
    }

    async fn probe_api_ready(
        &self,
        vm: &str,
        node: &ProcessNode,
        readiness: &[ReadinessPredicate],
        timeout: Duration,
    ) -> d2bd_runtime::supervisor::dag::ApiReadyState {
        if is_guest_owned_process_node(node) {
            return d2bd_runtime::supervisor::dag::ApiReadyState::Yes;
        }
        if node.role == ProcessRole::CloudHypervisorRunner {
            return d2bd_runtime::supervisor::dag::ApiReadyState::Yes;
        }
        if is_durable_wayland_process_node(node) {
            return match wait_for_readiness(node, readiness, timeout, None) {
                Ok(()) => d2bd_runtime::supervisor::dag::ApiReadyState::Yes,
                Err(error) if error == format!("readiness-timeout:{}", node.id.0) => {
                    d2bd_runtime::supervisor::dag::ApiReadyState::Timeout
                }
                Err(reason) => d2bd_runtime::supervisor::dag::ApiReadyState::Error { reason },
            };
        }
        // The split-readiness api-ready phase observes the already-spawned
        // long-lived runner, so wire in the liveness probe: a runner that
        // dies before the api-ready socket appears surfaces as an Error
        // (runner-exited / runner-reused) instead of a full-budget Timeout.
        let provider_liveness;
        let legacy_liveness;
        let liveness: &dyn d2bd_runtime::supervisor::readiness_liveness::LivenessProbe =
            if process_provider_runtime::ProductionProcessProviders::supports_node(node) {
                let Some(providers) = self.state.provider_runtime.process_providers() else {
                    return d2bd_runtime::supervisor::dag::ApiReadyState::Error {
                        reason: "provider-runtime-unavailable".to_owned(),
                    };
                };
                provider_liveness =
                    process_provider_runtime::ProviderLivenessProbe::new(providers, vm, node);
                &provider_liveness
            } else {
                legacy_liveness =
                    d2bd_runtime::supervisor::readiness_liveness::PidfdLivenessProbe::new(
                        &self.state.pidfd_table,
                        &self.state.broker_reap_log,
                        vm,
                        tracked_role_id(node),
                    );
                &legacy_liveness
            };
        match wait_for_readiness(node, readiness, timeout, Some(liveness)) {
            Ok(()) => d2bd_runtime::supervisor::dag::ApiReadyState::Yes,
            Err(error) if error == format!("readiness-timeout:{}", node.id.0) => {
                d2bd_runtime::supervisor::dag::ApiReadyState::Timeout
            }
            Err(reason) => d2bd_runtime::supervisor::dag::ApiReadyState::Error { reason },
        }
    }
}

fn stop_unregistered_spawned_runner(
    state: &ServerState,
    vm: &str,
    role_id: &str,
    response: &d2b_contracts_broker::broker_wire::SpawnRunnerResponse,
    received_fds: &[RawFd],
    caller_role: BrokerCallerRole,
) {
    let pidfd = duplicate_received_fd(
        received_fds,
        response.pidfd_index,
        "duplicate failed-registration SpawnRunner pidfd",
    )
    .map_err(|error| error.message());
    if let Err(error) = &pidfd {
        tracing::warn!(
            vm = %vm,
            role = %role_id,
            pid = response.pid,
            error = %error,
            "spawn registration failed; could not duplicate pidfd for cleanup"
        );
    }

    signal_unregistered_spawned_runner(
        state,
        vm,
        role_id,
        response,
        pidfd.as_ref().ok(),
        RunnerSignal::Term,
        caller_role.clone(),
    );
    if wait_unregistered_spawned_runner_reaped(state, vm, role_id, Duration::from_secs(2)) {
        deregister_runner_pidfd_via_broker(state, caller_role.clone(), vm, role_id);
        return;
    }

    tracing::warn!(
        vm = %vm,
        role = %role_id,
        pid = response.pid,
        "spawn registration failed; SIGTERM cleanup did not reap runner, escalating"
    );
    signal_unregistered_spawned_runner(
        state,
        vm,
        role_id,
        response,
        pidfd.as_ref().ok(),
        RunnerSignal::Kill,
        caller_role.clone(),
    );
    if wait_unregistered_spawned_runner_reaped(state, vm, role_id, Duration::from_secs(2)) {
        deregister_runner_pidfd_via_broker(state, caller_role, vm, role_id);
    } else {
        tracing::warn!(
            vm = %vm,
            role = %role_id,
            pid = response.pid,
            "spawn registration failed; runner was not observed reaped after SIGKILL, leaving broker pidfd registered"
        );
    }
}

fn signal_unregistered_spawned_runner(
    state: &ServerState,
    vm: &str,
    role_id: &str,
    response: &d2b_contracts_broker::broker_wire::SpawnRunnerResponse,
    pidfd: Option<&OwnedFd>,
    signal: RunnerSignal,
    caller_role: BrokerCallerRole,
) {
    let signal_number = match signal {
        RunnerSignal::Term => libc::SIGTERM,
        RunnerSignal::Kill => libc::SIGKILL,
        RunnerSignal::Quit => libc::SIGQUIT,
    };
    let pidfd_signal = rustix::process::Signal::from_raw(signal_number);
    if let (Some(pidfd), Some(pidfd_signal)) = (pidfd, pidfd_signal) {
        match rustix::process::pidfd_send_signal(pidfd.as_fd(), pidfd_signal) {
            Ok(()) => {
                tracing::warn!(
                    vm = %vm,
                    role = %role_id,
                    pid = response.pid,
                    signal = runner_signal_label(signal),
                    "spawn registration failed; signaled unregistered runner by pidfd"
                );
                return;
            }
            Err(error) => tracing::warn!(
                vm = %vm,
                role = %role_id,
                pid = response.pid,
                signal = runner_signal_label(signal),
                error = %error,
                "spawn registration failed; direct pidfd signal failed, falling back to broker"
            ),
        }
    }

    let request = BrokerRequest::SignalRunner(SignalRunnerRequest {
        vm_id: VmId::new(vm),
        role_id: RoleId::new(role_id),
        signal,
        pid: Some(response.pid),
        expected_start_time_ticks: Some(response.start_time_ticks),
        resource_ref: None,
        resource_uid: None,
        zone_uid: None,
        owner_ref: None,
        provider_ref: None,
        provider_identity: None,
        template_identity: None,
        generation: None,
        runtime_scope: None,
        guest_execution: None,
        tracing_span_id: None,
    });
    match dispatch_broker_request_as(state, request, caller_role) {
        Ok(BrokerResponse::SignalRunner(resp))
            if resp.vm_id.as_str() == vm && resp.role_id.as_str() == role_id && resp.signaled =>
        {
            tracing::warn!(
                vm = %vm,
                role = %role_id,
                pid = response.pid,
                signal = runner_signal_label(signal),
                "spawn registration failed; broker signaled unregistered runner"
            );
        }
        Ok(other) => tracing::warn!(
            vm = %vm,
            role = %role_id,
            pid = response.pid,
            signal = runner_signal_label(signal),
            response = ?other,
            "spawn registration failed; broker cleanup signal returned unexpected response"
        ),
        Err(error) => tracing::warn!(
            vm = %vm,
            role = %role_id,
            pid = response.pid,
            signal = runner_signal_label(signal),
            error = ?error,
            "spawn registration failed; broker cleanup signal failed"
        ),
    }
}

fn wait_unregistered_spawned_runner_reaped(
    state: &ServerState,
    vm: &str,
    role_id: &str,
    timeout: Duration,
) -> bool {
    let deadline = Instant::now() + timeout;
    loop {
        refresh_broker_reap_log(state, "unregistered-spawn-cleanup");
        if state.broker_reap_log.take_for(vm, role_id).is_some() {
            return true;
        }
        if Instant::now() >= deadline {
            return false;
        }
        std::thread::sleep(Duration::from_millis(50));
    }
}

fn write_runner_snapshot(
    state: &ServerState,
    vm: &str,
    role_id: &str,
    role: RunnerRole,
    pid: i32,
    start_time_ticks: u64,
) -> Result<(), String> {
    write_runner_snapshot_with_authorization(
        state,
        vm,
        role_id,
        role,
        pid,
        start_time_ticks,
        None,
        None,
    )
}

#[allow(dead_code)]
fn write_runner_snapshot_owned(
    state: &ServerState,
    vm: &str,
    role_id: &str,
    role: RunnerRole,
    pid: i32,
    start_time_ticks: u64,
    owner_resource_uid: Option<&str>,
) -> Result<(), String> {
    write_runner_snapshot_with_authorization(
        state,
        vm,
        role_id,
        role,
        pid,
        start_time_ticks,
        owner_resource_uid,
        None,
    )
}

pub(crate) fn write_runner_snapshot_with_authorization(
    state: &ServerState,
    vm: &str,
    role_id: &str,
    role: RunnerRole,
    pid: i32,
    start_time_ticks: u64,
    owner_resource_uid: Option<&str>,
    authorization: Option<&provider_effects::LifecycleAuthorization>,
) -> Result<(), String> {
    let store =
        d2bd_runtime::supervisor::state::FilesystemSnapshotStore::new(&state.daemon_state_dir);
    d2bd_runtime::supervisor::state::SnapshotStore::upsert(
        &store,
        &d2bd_runtime::supervisor::state::RunnerSnapshotRecord {
            vm: vm.to_owned(),
            role_id: role_id.to_owned(),
            role,
            owner_resource_uid: owner_resource_uid.map(str::to_owned),
            zone_uid: authorization.map(|value| value.zone_uid().clone()),
            guest_uid: authorization.map(|value| value.guest_uid().clone()),
            guest_generation: authorization.map(|value| value.guest_generation()),
            provider_assignment_generation: authorization
                .map(|value| value.provider_assignment_generation()),
            policy_revision: authorization.map(|value| value.policy_revision()),
            operation_id: authorization.map(|value| value.operation_id().to_owned()),
            pid,
            start_time_ticks,
            snapshotted_at: chrono_like_rfc3339(),
        },
    )
    .map_err(|error| format!("runner-snapshot:{error}"))
}

fn remove_runner_snapshot(state: &ServerState, vm: &str, role_id: &str) {
    let store =
        d2bd_runtime::supervisor::state::FilesystemSnapshotStore::new(&state.daemon_state_dir);
    if let Err(error) = d2bd_runtime::supervisor::state::SnapshotStore::remove(&store, vm, role_id)
    {
        tracing::warn!(vm = %vm, role = %role_id, error = ?error, "failed to remove runner snapshot during cleanup");
    }
}

fn vm_supports_store_sync(resolver: &BundleResolver, vm: &str) -> bool {
    match resolver.manifest.vms.get(vm) {
        Some(entry) => entry.runtime.capabilities.store_sync,
        None => true,
    }
}

/// Reconcile the committed WaylandSession before the legacy VM DAG reaches
/// the GPU edge. The durable display node remains outside DAG spawning; this
/// path only creates and launches its Host Process child through the Resource
/// API and Process Provider.
fn reconcile_display_before_vm_start(
    state: &ServerState,
    vm: &str,
    dag: &d2b_core::processes::VmProcessDag,
) -> Result<(), String> {
    if !dag.nodes.iter().any(is_durable_wayland_process_node) {
        return Ok(());
    }
    let zone = d2bd_runtime::zone_authority::authoritative_zone_for_vm(&state.zone_coordinator, vm)
        .map_err(|_| "display-session-zone-unavailable".to_owned())?;
    let plane = state
        .resource_plane
        .lock()
        .map_err(|_| "display-resource-plane-unavailable".to_owned())?
        .clone()
        .ok_or_else(|| "display-resource-plane-unavailable".to_owned())?;
    let runtime = plane
        .zone(&zone)
        .map_err(|_| "display-resource-runtime-unavailable".to_owned())?;
    let Some((session_ref, session_uid, spec)) =
        block_on_future(runtime.committed_wayland_session_for_vm(vm))
            .map_err(|_| "display-session-unavailable".to_owned())?
    else {
        return Err("display-session-missing".to_owned());
    };
    let result = {
        let mut interactions = block_on_future(state.interaction_runtime.lock());
        let runtime_set = interactions
            .as_mut()
            .ok_or_else(|| "display-interaction-runtime-unavailable".to_owned())?;
        runtime_set
            .reconcile_committed_display_for_vm_start(&zone, vm, &session_ref, &session_uid, &spec)
            .map_err(|error| error.to_string())?
    };
    if result.status.phase == d2b_provider_display_wayland::Phase::Failed {
        return Err("display-session-reconcile-failed".to_owned());
    }
    if result.status.resource.proxy_process_ref.is_none() {
        return Err("display-host-proxy-resource-missing".to_owned());
    }
    block_on_future(runtime.reconcile_process_resources(Arc::new(state.clone())))
        .map_err(|_| "display-host-proxy-process-reconcile-failed".to_owned())?;
    Ok(())
}

fn ensure_vm_runtime_capability(
    state: &ServerState,
    vm: &str,
    capability: RuntimeCapabilityGate,
    verb: &str,
) -> Result<(), TypedError> {
    let manifest: ManifestV04 = load_json(&state.config.artifacts.public_manifest_path)?;
    ensure_manifest_entry_runtime_capability(manifest.vms.get(vm), vm, capability, verb)
}

fn existing_vm_start_response_if_ready(
    state: &ServerState,
    vm: &str,
    runner_role_id: &str,
) -> Option<Value> {
    if let Some(providers) = state.provider_runtime.process_providers() {
        if providers.has_active_role(vm, runner_role_id) || providers.has_active_vm(vm) {
            return Some(applied_response(
                "vm start",
                format!("vm.{vm}: already running; Provider identity is live"),
            ));
        }
        return None;
    }
    if !state.pidfd_table.contains(vm, runner_role_id) {
        return None;
    }

    Some(applied_response(
        "vm start",
        format!("vm.{vm}: already running; {runner_role_id} pidfd is live"),
    ))
}

fn vm_start_primary_runner_role_id(tracked_roles: &[String]) -> &str {
    tracked_roles
        .iter()
        .find(|role_id| {
            role_id.as_str() == VM_RUNNER_ROLE_ID
                || role_id.as_str() == RunnerRole::QemuMedia.as_str()
        })
        .map(String::as_str)
        .unwrap_or(VM_RUNNER_ROLE_ID)
}

fn cleanup_vm_start_registration(state: &ServerState, vm: &str, role_id: &str) {
    let _mguard = state.pidfd_table.mutation_guard();
    let _ = state.pidfd_table.deregister(vm, role_id);
    if let Err(error) = state.pidfd_table.snapshot() {
        tracing::warn!(vm = %vm, role = %role_id, error = ?error, "failed to persist pidfd table cleanup");
    }
    remove_runner_snapshot(state, vm, role_id);
}

fn rollback_failed_vm_start(
    state: &ServerState,
    vm: &str,
    tracked_roles: &[String],
    caller_role: BrokerCallerRole,
) -> Result<(), Value> {
    let tracked: BTreeSet<&str> = tracked_roles.iter().map(String::as_str).collect();
    let mut entries = ordered_vm_stop_entries(state, vm)
        .into_iter()
        .filter(|entry| tracked.contains(entry.role.as_str()))
        .collect::<Vec<_>>();
    if entries.is_empty() {
        return Ok(());
    }
    entries.sort_by(|left, right| {
        vm_stop_role_priority(infer_runner_role_for_vm_stop(&left.role))
            .cmp(&vm_stop_role_priority(infer_runner_role_for_vm_stop(
                &right.role,
            )))
            .then_with(|| left.role.cmp(&right.role))
    });
    for entry in entries {
        tracing::warn!(
            vm = %vm,
            role = %entry.role,
            "vm start failed; rolling back runner spawned during this start attempt",
        );
        stop_vm_pidfd_role(
            state,
            caller_role.clone(),
            "vm start",
            vm,
            &entry.role,
            Duration::from_secs(10),
            Duration::from_secs(5),
        )?;
    }
    let _mguard = state.pidfd_table.mutation_guard();
    if let Err(error) = state.pidfd_table.snapshot() {
        return Err(daemon_failure_response(
            "vm start",
            format!(
                "vm start {vm}: rollback stopped spawned runners but pidfd_table persistence failed ({error})"
            ),
        ));
    }
    Ok(())
}

fn qemu_media_primary_role_id(tracked_roles: &[String]) -> Option<&str> {
    tracked_roles
        .iter()
        .find(|role| role.as_str() == RunnerRole::QemuMedia.as_str())
        .map(String::as_str)
}

fn stale_qemu_media_dependency_roles_from_entries(
    tracked_roles: &[String],
    entries: &[PidfdRegistration],
) -> Vec<String> {
    let Some(primary_role) = qemu_media_primary_role_id(tracked_roles) else {
        return Vec::new();
    };
    if entries.iter().any(|entry| entry.role == primary_role) {
        return Vec::new();
    }

    let tracked: BTreeSet<&str> = tracked_roles.iter().map(String::as_str).collect();
    let mut stale_roles = entries
        .iter()
        .filter(|entry| {
            tracked.contains(entry.role.as_str()) && entry.role.as_str() != primary_role
        })
        .map(|entry| entry.role.clone())
        .collect::<Vec<_>>();
    stale_roles.sort_by(|left, right| {
        vm_stop_role_priority(infer_runner_role_for_vm_stop(left))
            .cmp(&vm_stop_role_priority(infer_runner_role_for_vm_stop(right)))
            .then_with(|| left.cmp(right))
    });
    stale_roles
}

fn cleanup_stale_qemu_media_dependencies_before_start(
    state: &ServerState,
    vm: &str,
    tracked_roles: &[String],
    caller_role: BrokerCallerRole,
) -> Result<usize, Value> {
    let stale_roles = stale_qemu_media_dependency_roles_from_entries(
        tracked_roles,
        &ordered_vm_stop_entries(state, vm),
    );
    for role in &stale_roles {
        tracing::warn!(
            vm = %vm,
            role = %role,
            "qemu-media primary runner is absent; stopping leftover dependency before restart",
        );
        stop_vm_pidfd_role(
            state,
            caller_role.clone(),
            "vm start",
            vm,
            role,
            Duration::from_secs(10),
            Duration::from_secs(5),
        )?;
    }
    if !stale_roles.is_empty() {
        let _mguard = state.pidfd_table.mutation_guard();
        if let Err(error) = state.pidfd_table.snapshot() {
            return Err(daemon_failure_response(
                "vm start",
                format!(
                    "vm start {vm}: stale qemu-media dependency cleanup failed to persist pidfd_table ({error})"
                ),
            ));
        }
    }
    Ok(stale_roles.len())
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct VmStopRoleReport {
    role_id: String,
    required_sigkill: bool,
    shutdown_outcome: Option<VmShutdownOutcome>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum VmShutdownOutcome {
    CleanGuestShutdown,
    CleanVmmCleanup,
    ApiUnavailable,
    TimeoutExceeded,
    ForceRequested,
    Disabled,
    ForcedCleanup,
    CleanupFailed,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
struct ShutdownDegradedReport {
    schema_version: u32,
    markers: Vec<ShutdownDegradedMarker>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
struct ShutdownDegradedMarker {
    vm: String,
    outcome: String,
    severity: String,
    remediation: String,
    elapsed_ms: u64,
}

fn force_shutdown_generation(state: &ServerState, vm: &str) -> u64 {
    let Ok(zone) =
        d2bd_runtime::zone_authority::authoritative_zone_for_vm(&state.zone_coordinator, vm)
    else {
        return 0;
    };
    state
        .zone_coordinator
        .lock()
        .ok()
        .and_then(|coordinator| coordinator.snapshot(&zone).ok())
        .and_then(|snapshot| snapshot.force_shutdown_generation())
        .unwrap_or(0)
}

fn note_force_shutdown_request(state: &ServerState, vm: &str) {
    let Ok(zone) =
        d2bd_runtime::zone_authority::authoritative_zone_for_vm(&state.zone_coordinator, vm)
    else {
        tracing::warn!(
            vm = %vm,
            "force shutdown request ignored because the VM has no authoritative Zone binding",
        );
        return;
    };
    let Ok(mut coordinator) = state.zone_coordinator.lock() else {
        tracing::warn!(vm = %vm, "force shutdown request ignored because Zone state is unavailable");
        return;
    };
    if let Err(error) = coordinator.note_force_shutdown_request(&zone) {
        tracing::warn!(vm = %vm, error = %error, "force shutdown generation did not advance");
    }
}

fn force_shutdown_interrupted(state: &ServerState, vm: &str, baseline: u64) -> bool {
    force_shutdown_generation(state, vm) > baseline
}

impl VmShutdownOutcome {
    fn label(self) -> &'static str {
        match self {
            Self::CleanGuestShutdown => "clean_guest_shutdown",
            Self::CleanVmmCleanup => "clean_vmm_cleanup",
            Self::ApiUnavailable => "api_unavailable",
            Self::TimeoutExceeded => "timeout_exceeded",
            Self::ForceRequested => "force_requested",
            Self::Disabled => "disabled",
            Self::ForcedCleanup => "forced_cleanup",
            Self::CleanupFailed => "cleanup_failed",
        }
    }

    fn audit(self) -> d2bd_runtime::daemon_audit::VmShutdownOutcome {
        match self {
            Self::CleanGuestShutdown => {
                d2bd_runtime::daemon_audit::VmShutdownOutcome::CleanGuestShutdown
            }
            Self::CleanVmmCleanup => d2bd_runtime::daemon_audit::VmShutdownOutcome::CleanVmmCleanup,
            Self::ApiUnavailable => d2bd_runtime::daemon_audit::VmShutdownOutcome::ApiUnavailable,
            Self::TimeoutExceeded => d2bd_runtime::daemon_audit::VmShutdownOutcome::TimeoutExceeded,
            Self::ForceRequested => d2bd_runtime::daemon_audit::VmShutdownOutcome::ForceRequested,
            Self::Disabled => d2bd_runtime::daemon_audit::VmShutdownOutcome::Disabled,
            Self::ForcedCleanup => d2bd_runtime::daemon_audit::VmShutdownOutcome::ForcedCleanup,
            Self::CleanupFailed => d2bd_runtime::daemon_audit::VmShutdownOutcome::CleanupFailed,
        }
    }

    fn degraded_severity(self) -> Option<&'static str> {
        match self {
            Self::CleanGuestShutdown | Self::CleanVmmCleanup | Self::Disabled => None,
            Self::ForceRequested | Self::ApiUnavailable => Some("warn"),
            Self::TimeoutExceeded | Self::ForcedCleanup | Self::CleanupFailed => Some("fail"),
        }
    }

    fn remediation(self) -> &'static str {
        match self {
            Self::TimeoutExceeded => {
                "fix the in-guest shutdown path and retry `d2b vm stop <vm> --apply`, or intentionally bypass with `d2b vm stop <vm> --force --apply`"
            }
            Self::CleanupFailed => {
                "host-side empty-VMM cleanup failed; inspect d2bd logs and retry a focused force stop"
            }
            Self::ForcedCleanup => {
                "forced cleanup was required; verify the VM is stopped and inspect d2bd logs if resources remain"
            }
            Self::ApiUnavailable => {
                "provider shutdown API was unavailable; verify provider socket health before the next stop"
            }
            Self::ForceRequested => "explicit force stop requested by operator",
            Self::Disabled => "graceful shutdown disabled by configuration",
            Self::CleanGuestShutdown | Self::CleanVmmCleanup => "no remediation required",
        }
    }
}

fn provider_audit_label(
    kind: Option<provider_shutdown::ProviderKind>,
) -> d2bd_runtime::daemon_audit::VmShutdownProvider {
    match kind {
        Some(provider_shutdown::ProviderKind::CloudHypervisor) => {
            d2bd_runtime::daemon_audit::VmShutdownProvider::CloudHypervisor
        }
        Some(provider_shutdown::ProviderKind::QemuMedia) => {
            d2bd_runtime::daemon_audit::VmShutdownProvider::QemuMedia
        }
        None => d2bd_runtime::daemon_audit::VmShutdownProvider::Unknown,
    }
}

fn provider_metric_label(kind: Option<provider_shutdown::ProviderKind>) -> &'static str {
    kind.map(provider_shutdown::ProviderKind::as_str)
        .unwrap_or("unknown")
}

fn record_vm_shutdown_metric(
    state: &ServerState,
    provider: Option<provider_shutdown::ProviderKind>,
    outcome: VmShutdownOutcome,
    elapsed: Duration,
) {
    let vmm = provider_metric_label(provider);
    let outcome = outcome.label();
    state.metrics_registry.counter_inc(
        "d2b_daemon_vm_shutdown_total",
        &[("vmm", vmm), ("outcome", outcome)],
    );
    state.metrics_registry.histogram_observe(
        "d2b_daemon_vm_shutdown_duration_seconds",
        &[("vmm", vmm), ("outcome", outcome)],
        elapsed.as_secs_f64(),
    );
}

fn emit_vm_shutdown_intent_audit(
    state: &ServerState,
    vm: &str,
    caller_role: &BrokerCallerRole,
    provider: Option<provider_shutdown::ProviderKind>,
    force_requested: bool,
    timeout_secs: u64,
) -> Result<(), std::io::Error> {
    let peer_uid = broker_caller_uid(caller_role);
    state.daemon_audit.write_event_with_authority(
        &d2bd_runtime::daemon_audit::DaemonEvent::VmShutdownIntent {
            vm: vm.to_owned(),
            peer_uid,
            provider: provider_audit_label(provider),
            force_requested,
            timeout_secs,
        },
        d2bd_runtime::daemon_audit::DaemonAuditAuthority::Authoritative,
    )
}

fn emit_vm_shutdown_outcome_audit(
    state: &ServerState,
    vm: &str,
    caller_role: &BrokerCallerRole,
    provider: Option<provider_shutdown::ProviderKind>,
    outcome: VmShutdownOutcome,
    elapsed: Duration,
) -> Result<(), std::io::Error> {
    let peer_uid = broker_caller_uid(caller_role);
    state.daemon_audit.write_event_with_authority(
        &d2bd_runtime::daemon_audit::DaemonEvent::VmShutdownOutcome {
            vm: vm.to_owned(),
            peer_uid,
            provider: provider_audit_label(provider),
            outcome: outcome.audit(),
            elapsed_ms: elapsed.as_millis() as u64,
        },
        d2bd_runtime::daemon_audit::DaemonAuditAuthority::Authoritative,
    )?;
    persist_vm_shutdown_marker(state, vm, outcome, elapsed);
    Ok(())
}

fn persist_vm_shutdown_marker(
    state: &ServerState,
    vm: &str,
    outcome: VmShutdownOutcome,
    elapsed: Duration,
) {
    let path = shutdown_degraded_report_path(&state.daemon_state_dir);
    let mut report = std::fs::read(&path)
        .ok()
        .and_then(|bytes| serde_json::from_slice::<ShutdownDegradedReport>(&bytes).ok())
        .unwrap_or(ShutdownDegradedReport {
            schema_version: 1,
            markers: Vec::new(),
        });
    report.markers.retain(|marker| marker.vm != vm);
    if let Some(severity) = outcome.degraded_severity() {
        report.markers.push(ShutdownDegradedMarker {
            vm: vm.to_owned(),
            outcome: outcome.label().to_owned(),
            severity: severity.to_owned(),
            remediation: outcome.remediation().replace("<vm>", vm),
            elapsed_ms: elapsed.as_millis() as u64,
        });
    }
    if report.markers.is_empty() {
        match std::fs::remove_file(&path) {
            Ok(()) => {}
            Err(err) if err.kind() == io::ErrorKind::NotFound => {}
            Err(err) => {
                tracing::warn!(error = %err, path = %path.display(), "failed to clear shutdown degraded marker");
            }
        }
        return;
    }
    match serde_json::to_vec_pretty(&report)
        .map_err(io::Error::other)
        .and_then(|json| persist_json_report(&path, &json))
    {
        Ok(()) => {}
        Err(err) => {
            tracing::warn!(error = %err, path = %path.display(), "failed to persist shutdown degraded marker");
        }
    }
}

fn broker_caller_uid(caller_role: &BrokerCallerRole) -> u32 {
    match caller_role {
        BrokerCallerRole::AdminUid { uid }
        | BrokerCallerRole::LauncherUid { uid }
        | BrokerCallerRole::RootUid { uid }
        | BrokerCallerRole::HostShutdownUid { uid } => *uid,
        BrokerCallerRole::NotAuthorized => 0,
    }
}

fn load_vm_stop_role_index(state: &ServerState, vm: &str) -> HashMap<String, RunnerRole> {
    let store =
        d2bd_runtime::supervisor::state::FilesystemSnapshotStore::new(&state.daemon_state_dir);
    match d2bd_runtime::supervisor::state::SnapshotStore::list(&store) {
        Ok(records) => records
            .into_iter()
            .filter(|record| record.vm == vm)
            .map(|record| (record.role_id, record.role))
            .collect(),
        Err(error) => {
            tracing::warn!(vm = %vm, error = ?error, "failed to load runner snapshots for vm stop ordering");
            HashMap::new()
        }
    }
}

fn infer_runner_role_for_vm_stop(role_id: &str) -> Option<RunnerRole> {
    if role_id == RunnerRole::ProviderController.as_str() || role_id.contains("provider-controller")
    {
        Some(RunnerRole::ProviderController)
    } else if role_id == VM_RUNNER_ROLE_ID {
        Some(RunnerRole::CloudHypervisor)
    } else if role_id == RunnerRole::QemuMedia.as_str() || role_id.contains("qemu-media") {
        Some(RunnerRole::QemuMedia)
    } else if role_id == RunnerRole::SwtpmFlush.as_str() {
        Some(RunnerRole::SwtpmFlush)
    } else if role_id == RunnerRole::Swtpm.as_str() || role_id.starts_with("swtpm") {
        Some(RunnerRole::Swtpm)
    } else if role_id == RunnerRole::Virtiofsd.as_str() || role_id.contains("virtiofsd") {
        Some(RunnerRole::Virtiofsd)
    } else if role_id == RunnerRole::Gpu.as_str() || role_id.contains("gpu") {
        Some(RunnerRole::Gpu)
    } else if role_id == RunnerRole::Audio.as_str() || role_id.contains("audio") {
        Some(RunnerRole::Audio)
    } else if role_id == RunnerRole::Video.as_str() || role_id.contains("video") {
        Some(RunnerRole::Video)
    } else if role_id == RunnerRole::WaylandProxy.as_str()
        || role_id.contains("wayland-proxy")
        || role_id.contains("wlproxy")
    {
        Some(RunnerRole::WaylandProxy)
    } else if role_id == RunnerRole::Usbip.as_str() || role_id.contains("usbip") {
        Some(RunnerRole::Usbip)
    } else if role_id == RunnerRole::VsockRelay.as_str() || role_id.contains("vsock") {
        Some(RunnerRole::VsockRelay)
    } else if role_id == RunnerRole::OtelHostBridge.as_str()
        || role_id.contains("otel-host-bridge")
        || role_id.contains("otel_host_bridge")
    {
        Some(RunnerRole::OtelHostBridge)
    } else if role_id == RunnerRole::ActivationNixos.as_str()
        || role_id.contains("activation-nixos")
    {
        Some(RunnerRole::ActivationNixos)
    } else {
        None
    }
}

fn vm_stop_role_priority(role: Option<RunnerRole>) -> u8 {
    match role {
        Some(RunnerRole::ProviderController) => 0,
        Some(RunnerRole::CloudHypervisor) => 0,
        Some(RunnerRole::QemuMedia) => 0,
        Some(RunnerRole::Gpu) => 1,
        Some(RunnerRole::Audio) => 2,
        Some(RunnerRole::Video) => 3,
        // WaylandProxy is the upstream for the GPU runner; stop it after
        // GPU so the GPU runner can close its connection cleanly first.
        Some(RunnerRole::WaylandProxy) => 3,
        Some(RunnerRole::Usbip) => 4,
        Some(RunnerRole::VsockRelay) => 5,
        // OtelHostBridge is observability infrastructure; stop it before
        // swtpm/virtiofsd so trailing OTel spans flush
        // before the per-VM TPM + virtiofs are torn down.
        Some(RunnerRole::OtelHostBridge) => 5,
        Some(RunnerRole::Swtpm) => 6,
        Some(RunnerRole::Virtiofsd) => 7,
        Some(RunnerRole::SwtpmFlush) => 8,
        Some(RunnerRole::ActivationNixos) => 9,
        None => 9,
    }
}

fn ordered_vm_stop_entries(state: &ServerState, vm: &str) -> Vec<PidfdRegistration> {
    let role_index = load_vm_stop_role_index(state, vm);
    let provider_roles = state
        .provider_runtime
        .process_providers()
        .map(|providers| {
            providers
                .active_role_ids(vm)
                .into_iter()
                .collect::<BTreeSet<_>>()
        })
        .unwrap_or_default();
    let mut entries = state
        .pidfd_table
        .list_for_vm(vm)
        .into_iter()
        .filter(|entry| !provider_roles.contains(&entry.role))
        .collect::<Vec<_>>();
    entries.extend(provider_roles.into_iter().map(|role| PidfdRegistration {
        vm: vm.to_owned(),
        role,
        pid: 0,
        start_time_ticks: 0,
    }));
    entries.sort_by(|left, right| {
        let left_role = role_index
            .get(&left.role)
            .copied()
            .or_else(|| infer_runner_role_for_vm_stop(&left.role));
        let right_role = role_index
            .get(&right.role)
            .copied()
            .or_else(|| infer_runner_role_for_vm_stop(&right.role));
        vm_stop_role_priority(left_role)
            .cmp(&vm_stop_role_priority(right_role))
            .then_with(|| left.role.cmp(&right.role))
    });
    entries
}

fn runner_signal_label(signal: RunnerSignal) -> &'static str {
    match signal {
        RunnerSignal::Term => "SIGTERM",
        RunnerSignal::Kill => "SIGKILL",
        RunnerSignal::Quit => "SIGQUIT",
    }
}

fn broker_fallback_failure(
    vm: &str,
    role_id: &str,
    signal: RunnerSignal,
    detail: impl std::fmt::Display,
) -> Value {
    daemon_failure_response(
        "vm stop",
        format!(
            "vm stop {vm}: pidfd_table {} failed for {role_id}; broker fallback failed: {detail}",
            runner_signal_label(signal)
        ),
    )
}

fn signal_via_broker(
    state: &ServerState,
    caller_role: BrokerCallerRole,
    vm: &str,
    role_id: &str,
    signal: RunnerSignal,
) -> Result<(), Value> {
    let registration = state
        .pidfd_table
        .list_for_vm(vm)
        .into_iter()
        .find(|entry| entry.role == role_id);
    let request = BrokerRequest::SignalRunner(SignalRunnerRequest {
        vm_id: VmId::new(vm),
        role_id: RoleId::new(role_id),
        signal,
        pid: registration.as_ref().map(|entry| entry.pid),
        expected_start_time_ticks: registration.as_ref().map(|entry| entry.start_time_ticks),
        resource_ref: None,
        resource_uid: None,
        zone_uid: None,
        owner_ref: None,
        provider_ref: None,
        provider_identity: None,
        template_identity: None,
        generation: None,
        runtime_scope: None,
        guest_execution: None,
        tracing_span_id: None,
    });
    match dispatch_broker_request_as(state, request, caller_role) {
        Ok(BrokerResponse::SignalRunner(resp))
            if resp.vm_id.as_str() == vm && resp.role_id.as_str() == role_id && resp.signaled =>
        {
            Ok(())
        }
        Ok(BrokerResponse::SignalRunner(resp)) => Err(broker_fallback_failure(
            vm,
            role_id,
            signal,
            format!(
                "SignalRunner returned vm={} role={} signaled={}",
                resp.vm_id.as_str(),
                resp.role_id.as_str(),
                resp.signaled
            ),
        )),
        Ok(BrokerResponse::Error(error)) => Err(broker_fallback_failure(
            vm,
            role_id,
            signal,
            format!(
                "SignalRunner rejected by broker: {} ({})",
                error.message, error.kind
            ),
        )),
        Ok(other) => Err(broker_fallback_failure(
            vm,
            role_id,
            signal,
            format!("SignalRunner returned unexpected response: {other:?}"),
        )),
        Err(err) => Err(broker_fallback_failure(
            vm,
            role_id,
            signal,
            format!("{err:?}"),
        )),
    }
}

fn deregister_runner_pidfd_via_broker(
    state: &ServerState,
    caller_role: BrokerCallerRole,
    vm: &str,
    role_id: &str,
) {
    let request = BrokerRequest::DeregisterRunnerPidfd(DeregisterRunnerPidfdRequest {
        vm_id: VmId::new(vm),
        role_id: RoleId::new(role_id),
        pid: state
            .pidfd_table
            .list_for_vm(vm)
            .into_iter()
            .find(|entry| entry.role == role_id)
            .map(|entry| entry.pid),
        expected_start_time_ticks: state
            .pidfd_table
            .list_for_vm(vm)
            .into_iter()
            .find(|entry| entry.role == role_id)
            .map(|entry| entry.start_time_ticks),
        resource_ref: None,
        resource_uid: None,
        zone_uid: None,
        owner_ref: None,
        provider_ref: None,
        provider_identity: None,
        template_identity: None,
        generation: None,
        runtime_scope: None,
        guest_execution: None,
        tracing_span_id: None,
    });
    match dispatch_broker_request_as(state, request, caller_role) {
        Ok(BrokerResponse::DeregisterRunnerPidfd(resp))
            if resp.vm_id.as_str() == vm && resp.role_id.as_str() == role_id =>
        {
            if !resp.removed {
                tracing::warn!(
                    vm = %vm,
                    role = %role_id,
                    removed = false,
                    "broker runner pidfd deregister reported no entry"
                );
            }
        }

        Ok(other) => tracing::warn!(
            vm = %vm,
            role = %role_id,
            response = ?other,
            "broker runner pidfd deregister returned unexpected response"
        ),
        Err(error) => tracing::warn!(
            vm = %vm,
            role = %role_id,
            error = ?error,
            "broker runner pidfd deregister failed"
        ),
    }
}

fn finish_terminated_runner(
    state: &ServerState,
    caller_role: BrokerCallerRole,
    vm: &str,
    role_id: &str,
) {
    let _ = state.pidfd_table.deregister(vm, role_id);
    deregister_runner_pidfd_via_broker(state, caller_role, vm, role_id);
    remove_runner_snapshot(state, vm, role_id);
}

fn cgroup_events_populated_at(path: &Path) -> Result<Option<bool>, std::io::Error> {
    let events = path.join("cgroup.events");
    if !events.exists() {
        return Ok(None);
    }
    let content = fs::read_to_string(events)?;
    for line in content.lines() {
        let mut parts = line.split_whitespace();
        if parts.next() == Some("populated") {
            return Ok(Some(parts.next() != Some("0")));
        }
    }
    Ok(None)
}

fn role_cgroup_path(state: &ServerState, vm: &str, role_id: &str) -> Option<PathBuf> {
    let processes = load_json::<ProcessesJson>(&state.config.artifacts.processes_path).ok()?;
    let process_vm = processes.vms.iter().find(|entry| entry.vm == vm)?;
    let node = process_vm
        .nodes
        .iter()
        .find(|node| node.id.0 == role_id)
        .or_else(|| {
            let wanted = infer_runner_role_for_vm_stop(role_id)?;
            process_vm.nodes.iter().find(|node| {
                matches!(
                    (wanted, &node.role),
                    (
                        RunnerRole::CloudHypervisor,
                        ProcessRole::CloudHypervisorRunner
                    ) | (RunnerRole::QemuMedia, ProcessRole::QemuMediaRunner)
                        | (RunnerRole::Virtiofsd, ProcessRole::Virtiofsd)
                        | (RunnerRole::Swtpm, ProcessRole::Swtpm)
                        | (RunnerRole::Gpu, ProcessRole::Gpu)
                        | (RunnerRole::Audio, ProcessRole::Audio)
                        | (RunnerRole::Video, ProcessRole::Video)
                        | (RunnerRole::WaylandProxy, ProcessRole::WaylandProxy)
                        | (RunnerRole::Usbip, ProcessRole::Usbip)
                        | (RunnerRole::VsockRelay, ProcessRole::VsockRelay)
                        | (RunnerRole::OtelHostBridge, ProcessRole::OtelHostBridge)
                )
            })
        })?;
    let subtree = Path::new(&node.profile.cgroup_placement.subtree);
    Some(if subtree.is_absolute() {
        subtree.to_path_buf()
    } else {
        PathBuf::from("/sys/fs/cgroup").join(subtree)
    })
}

fn dispatch_raw_broker_value_with_timeout(
    state: &ServerState,
    request: Value,
    caller_role: BrokerCallerRole,
    timeout: Duration,
) -> Result<Value, TypedError> {
    let socket_path = broker_socket_path(state);
    let deadline = Instant::now() + timeout;
    let remaining = broker_remaining_before_op(deadline, &socket_path)?;
    let socket = Socket::from(connect_seqpacket_with_timeout(
        &socket_path,
        Some(remaining),
    )?);
    let envelope = json!({
        "request": request,
        "callerRole": caller_role,
        "testPeerUid": Value::Null,
    });
    let remaining = broker_remaining_before_op(deadline, &socket_path)?;
    socket
        .set_write_timeout(Some(remaining))
        .map_err(|err| TypedError::InternalIo {
            context: format!("set raw broker write timeout to {remaining:?}"),
            detail: err.to_string(),
        })?;
    write_json_frame(&socket, &envelope)?;
    let remaining = broker_remaining_before_op(deadline, &socket_path)?;
    socket
        .set_read_timeout(Some(remaining))
        .map_err(|err| TypedError::InternalIo {
            context: format!("set raw broker read timeout to {remaining:?}"),
            detail: err.to_string(),
        })?;
    let response = read_frame(&socket)?;
    serde_json::from_slice(&response).map_err(|err| TypedError::InternalBrokerUnavailable {
        path: socket_path,
        detail: err.to_string(),
    })
}

fn request_cgroup_kill_if_populated(
    state: &ServerState,
    caller_role: BrokerCallerRole,
    vm: &str,
    role_id: &str,
) {
    let request = json!({
        "kind": "CgroupKill",
        "payload": {
            "vmId": vm,
            "roleId": role_id,
            "tracingSpanId": Value::Null,
        }
    });
    match dispatch_raw_broker_value_with_timeout(
        state,
        request,
        caller_role,
        Duration::from_secs(5),
    ) {
        Ok(response) => {
            tracing::info!(vm = %vm, role = %role_id, response = ?response, "broker CgroupKill requested for populated runner leaf")
        }
        Err(err) => {
            tracing::warn!(vm = %vm, role = %role_id, error = ?err, "broker CgroupKill request failed")
        }
    }
}

fn prove_role_cgroup_empty_or_escalate(
    state: &ServerState,
    caller_role: BrokerCallerRole,
    vm: &str,
    role_id: &str,
) -> bool {
    let Some(path) = role_cgroup_path(state, vm, role_id) else {
        return true;
    };
    match cgroup_events_populated_at(&path) {
        Ok(Some(false)) | Ok(None) => true,
        Ok(Some(true)) => {
            request_cgroup_kill_if_populated(state, caller_role, vm, role_id);
            let deadline = Instant::now() + CGROUP_EMPTY_POST_KILL_WAIT;
            while Instant::now() < deadline {
                match cgroup_events_populated_at(&path) {
                    Ok(Some(false)) | Ok(None) => return true,
                    Ok(Some(true)) => std::thread::sleep(Duration::from_millis(100)),
                    Err(err) => {
                        tracing::warn!(vm = %vm, role = %role_id, error = %err, "read cgroup.events failed after CgroupKill");
                        return false;
                    }
                }
            }
            tracing::warn!(vm = %vm, role = %role_id, path = %path.display(), "runner cgroup still populated after bounded CgroupKill wait");
            false
        }
        Err(err) => {
            tracing::warn!(vm = %vm, role = %role_id, error = %err, "read cgroup.events failed");
            false
        }
    }
}

#[derive(Debug, Clone)]
struct QemuBrokerShutdownProvider {
    socket_path: PathBuf,
    caller_role: BrokerCallerRole,
    timeout: Duration,
}

#[async_trait]
impl provider_shutdown::GracefulVmShutdown for QemuBrokerShutdownProvider {
    async fn request_shutdown(
        &self,
        target: &provider_shutdown::ProviderShutdownTarget,
    ) -> provider_shutdown::ProviderRequestOutcome {
        let request = json!({
            "kind": "QemuMediaSystemPowerdown",
            "payload": { "vmId": target.vm, "tracingSpanId": Value::Null }
        });
        match raw_broker_round_trip_async(
            self.socket_path.clone(),
            request,
            self.caller_role.clone(),
            self.timeout,
        )
        .await
        {
            Ok(value)
                if value.get("kind").and_then(Value::as_str)
                    == Some("QemuMediaSystemPowerdown") =>
            {
                provider_shutdown::ProviderRequestOutcome::Requested
            }
            Ok(value) if value.get("kind").and_then(Value::as_str) == Some("Error") => {
                provider_shutdown::ProviderRequestOutcome::Unavailable {
                    reason: "api_unavailable",
                }
            }
            Ok(_) => provider_shutdown::ProviderRequestOutcome::Rejected {
                reason: "api_rejected",
            },
            Err(_) => provider_shutdown::ProviderRequestOutcome::Unavailable {
                reason: "api_unavailable",
            },
        }
    }

    async fn poll_state(
        &self,
        target: &provider_shutdown::ProviderShutdownTarget,
    ) -> provider_shutdown::ProviderGuestState {
        let request = json!({
            "kind": "QemuMediaQueryStatus",
            "payload": {
                "vmId": target.vm,
                "shutdownContext": true,
                "tracingSpanId": Value::Null
            }
        });
        match raw_broker_round_trip_async(
            self.socket_path.clone(),
            request,
            self.caller_role.clone(),
            self.timeout,
        )
        .await
        {
            Ok(value)
                if value.get("kind").and_then(Value::as_str) == Some("QemuMediaQueryStatus") =>
            {
                match value
                    .get("payload")
                    .and_then(|payload| payload.get("status"))
                    .and_then(Value::as_str)
                {
                    Some("shutdown" | "connection-lost-during-shutdown") => {
                        provider_shutdown::ProviderGuestState::GuestStopped
                    }
                    Some("running" | "paused") => provider_shutdown::ProviderGuestState::Running,
                    _ => provider_shutdown::ProviderGuestState::Unknown {
                        reason: "unknown_state",
                    },
                }
            }
            Ok(_) | Err(_) => provider_shutdown::ProviderGuestState::Unknown {
                reason: "api_unavailable",
            },
        }
    }

    async fn request_vmm_exit(
        &self,
        target: &provider_shutdown::ProviderShutdownTarget,
    ) -> provider_shutdown::ProviderVmmExitOutcome {
        let request = json!({
            "kind": "QemuMediaQuit",
            "payload": { "vmId": target.vm, "tracingSpanId": Value::Null }
        });
        match raw_broker_round_trip_async(
            self.socket_path.clone(),
            request,
            self.caller_role.clone(),
            self.timeout,
        )
        .await
        {
            Ok(value) if value.get("kind").and_then(Value::as_str) == Some("QemuMediaQuit") => {
                provider_shutdown::ProviderVmmExitOutcome::Requested
            }
            Ok(_) | Err(_) => provider_shutdown::ProviderVmmExitOutcome::Unavailable {
                reason: "api_unavailable",
            },
        }
    }
}

async fn raw_broker_round_trip_async(
    socket_path: PathBuf,
    request: Value,
    caller_role: BrokerCallerRole,
    timeout: Duration,
) -> Result<Value, TypedError> {
    tokio::task::spawn_blocking(move || {
        dispatch_raw_broker_value_to_socket(&socket_path, request, caller_role, timeout)
    })
    .await
    .map_err(|err| TypedError::InternalIo {
        context: "join raw broker round trip".to_owned(),
        detail: err.to_string(),
    })?
}

fn dispatch_raw_broker_value_to_socket(
    socket_path: &Path,
    request: Value,
    caller_role: BrokerCallerRole,
    timeout: Duration,
) -> Result<Value, TypedError> {
    let deadline = Instant::now() + timeout;
    let remaining = broker_remaining_before_op(deadline, socket_path)?;
    let socket = Socket::from(connect_seqpacket_with_timeout(
        socket_path,
        Some(remaining),
    )?);
    let envelope = json!({
        "request": request,
        "callerRole": caller_role,
        "testPeerUid": Value::Null,
    });
    let remaining = broker_remaining_before_op(deadline, socket_path)?;
    socket
        .set_write_timeout(Some(remaining))
        .map_err(|err| TypedError::InternalIo {
            context: format!("set raw broker write timeout to {remaining:?}"),
            detail: err.to_string(),
        })?;
    write_json_frame(&socket, &envelope)?;
    let remaining = broker_remaining_before_op(deadline, socket_path)?;
    socket
        .set_read_timeout(Some(remaining))
        .map_err(|err| TypedError::InternalIo {
            context: format!("set raw broker read timeout to {remaining:?}"),
            detail: err.to_string(),
        })?;
    let response = read_frame(&socket)?;
    serde_json::from_slice(&response).map_err(|err| TypedError::InternalBrokerUnavailable {
        path: socket_path.to_path_buf(),
        detail: err.to_string(),
    })
}

fn vm_lifecycle_force_requested(request: &public_wire::VmLifecycleRequest) -> bool {
    serde_json::to_value(request)
        .ok()
        .and_then(|value| value.get("force").and_then(Value::as_bool).or(Some(false)))
        .unwrap_or(false)
}

fn graceful_shutdown_timeout_for(state: &ServerState, manifest_entry: &Value) -> Duration {
    let secs = manifest_entry
        .pointer("/lifecycle/gracefulShutdown/timeoutSeconds")
        .and_then(Value::as_u64)
        .unwrap_or(state.config.graceful_shutdown_timeout_seconds)
        .clamp(1, 600);
    Duration::from_secs(secs)
}

fn live_activation_timeout_for(state: &ServerState, vm: &str) -> Duration {
    let secs = manifest_entry_for_vm(state, vm)
        .and_then(|entry| {
            entry
                .pointer("/lifecycle/liveActivation/timeoutSeconds")
                .and_then(Value::as_u64)
        })
        .unwrap_or(state.config.live_activation_timeout_seconds)
        .clamp(1, 3600);
    Duration::from_secs(secs)
}

fn graceful_shutdown_enabled(manifest_entry: &Value) -> bool {
    manifest_entry
        .pointer("/lifecycle/gracefulShutdown/enable")
        .and_then(Value::as_bool)
        .unwrap_or(true)
}

fn provider_shutdown_target_for_role(
    manifest_entry: &Value,
    vm: &str,
    role_id: &str,
) -> Option<provider_shutdown::ProviderShutdownTarget> {
    if role_id == VM_RUNNER_ROLE_ID
        && manifest_entry
            .pointer("/runtime/provider/driver")
            .and_then(Value::as_str)
            == Some("cloud-hypervisor")
    {
        return Some(provider_shutdown::ProviderShutdownTarget {
            vm: vm.to_owned(),
            kind: provider_shutdown::ProviderKind::CloudHypervisor,
            api_socket: manifest_entry
                .get("apiSocket")
                .and_then(Value::as_str)
                .map(PathBuf::from),
        });
    }
    if role_id == RunnerRole::QemuMedia.as_str()
        || (role_id.contains("qemu-media")
            && manifest_entry
                .pointer("/runtime/kind")
                .and_then(Value::as_str)
                == Some("qemu-media"))
    {
        return Some(provider_shutdown::ProviderShutdownTarget {
            vm: vm.to_owned(),
            kind: provider_shutdown::ProviderKind::QemuMedia,
            api_socket: None,
        });
    }
    None
}

fn manifest_entry_for_vm(state: &ServerState, vm: &str) -> Option<Value> {
    load_manifest(&state.config.artifacts.public_manifest_path)
        .ok()
        .and_then(|manifest| manifest.get(vm).cloned())
}

fn required_sidecars_for_graceful_wait(entries: &[PidfdRegistration]) -> Vec<PidfdRegistration> {
    entries
        .iter()
        .filter(|entry| {
            matches!(
                infer_runner_role_for_vm_stop(&entry.role),
                Some(
                    RunnerRole::Virtiofsd
                        | RunnerRole::Swtpm
                        | RunnerRole::Gpu
                        | RunnerRole::Audio
                        | RunnerRole::Video
                        | RunnerRole::WaylandProxy
                        | RunnerRole::VsockRelay
                )
            )
        })
        .cloned()
        .collect()
}

async fn wait_registered_pidfd_exit(
    state: &ServerState,
    vm: &str,
    role_id: &str,
    timeout: Duration,
) -> bool {
    let Some((fd, _, _)) = state.pidfd_table.dup_pidfd_for(vm, role_id) else {
        return true;
    };
    let Ok(async_fd) = async_pidfd(fd) else {
        return false;
    };
    let deadline = Instant::now() + timeout;
    loop {
        let remaining = deadline.saturating_duration_since(Instant::now());
        if remaining.is_zero() {
            return false;
        }
        match tokio::time::timeout(remaining, async_fd.readable()).await {
            Ok(Ok(mut guard)) => {
                if state.pidfd_table.still_alive_same_start_time(vm, role_id) {
                    guard.clear_ready();
                    continue;
                }
                return true;
            }
            Ok(Err(_)) | Err(_) => return false,
        }
    }
}

fn async_pidfd(fd: OwnedFd) -> io::Result<tokio::io::unix::AsyncFd<OwnedFd>> {
    let flags = rustix::fs::fcntl_getfl(&fd)
        .map_err(|err| io::Error::from_raw_os_error(err.raw_os_error()))?;
    if !flags.contains(rustix::fs::OFlags::NONBLOCK) {
        rustix::fs::fcntl_setfl(&fd, flags | rustix::fs::OFlags::NONBLOCK)
            .map_err(|err| io::Error::from_raw_os_error(err.raw_os_error()))?;
    }
    tokio::io::unix::AsyncFd::new(fd)
}

fn sidecar_interrupted(state: &ServerState, sidecars: &[PidfdRegistration]) -> Option<String> {
    sidecars.iter().find_map(|entry| {
        (!state
            .pidfd_table
            .still_alive_same_start_time(&entry.vm, &entry.role))
        .then(|| entry.role.clone())
    })
}

struct ProviderGracefulInputs<'a> {
    provider: &'a dyn provider_shutdown::GracefulVmShutdown,
    target: &'a provider_shutdown::ProviderShutdownTarget,
    role_id: &'a str,
    sidecars: &'a [PidfdRegistration],
    timeout: Duration,
    force_generation_baseline: u64,
    caller_role: BrokerCallerRole,
}

async fn run_provider_graceful_shutdown(
    state: &ServerState,
    input: ProviderGracefulInputs<'_>,
) -> (VmShutdownOutcome, Option<VmStopRoleReport>) {
    let request_outcome = input.provider.request_shutdown(input.target).await;
    if !matches!(
        request_outcome,
        provider_shutdown::ProviderRequestOutcome::Requested
    ) {
        return (VmShutdownOutcome::ApiUnavailable, None);
    }

    let Some((pidfd, _pid, _start_ticks)) = state
        .pidfd_table
        .dup_pidfd_for(&input.target.vm, input.role_id)
    else {
        finish_terminated_runner(
            state,
            input.caller_role.clone(),
            &input.target.vm,
            input.role_id,
        );
        let cgroup_empty = prove_role_cgroup_empty_or_escalate(
            state,
            input.caller_role,
            &input.target.vm,
            input.role_id,
        );
        let outcome = if cgroup_empty {
            VmShutdownOutcome::CleanGuestShutdown
        } else {
            VmShutdownOutcome::CleanupFailed
        };
        return (
            outcome,
            Some(VmStopRoleReport {
                role_id: input.role_id.to_owned(),
                required_sigkill: false,
                shutdown_outcome: Some(outcome),
            }),
        );
    };
    let Ok(async_fd) = async_pidfd(pidfd) else {
        return (VmShutdownOutcome::ApiUnavailable, None);
    };
    let deadline = Instant::now() + input.timeout;
    loop {
        if force_shutdown_interrupted(state, &input.target.vm, input.force_generation_baseline) {
            tracing::warn!(vm = %input.target.vm, "force stop requested during graceful shutdown; forcing cleanup");
            return (VmShutdownOutcome::ForceRequested, None);
        }
        if let Some(role) = sidecar_interrupted(state, input.sidecars) {
            tracing::warn!(vm = %input.target.vm, role = %role, "sidecar exited during graceful shutdown; forcing cleanup");
            return (VmShutdownOutcome::ForcedCleanup, None);
        }
        let remaining = deadline.saturating_duration_since(Instant::now());
        if remaining.is_zero() {
            return (VmShutdownOutcome::TimeoutExceeded, None);
        }
        let tick = PROVIDER_SHUTDOWN_POLL_INTERVAL.min(remaining);
        tokio::select! {
            readable = async_fd.readable() => {
                if let Ok(mut guard) = readable {
                    if state
                        .pidfd_table
                        .still_alive_same_start_time(&input.target.vm, input.role_id)
                    {
                        guard.clear_ready();
                        continue;
                    }
                    finish_terminated_runner(state, input.caller_role.clone(), &input.target.vm, input.role_id);
                    let cgroup_empty = prove_role_cgroup_empty_or_escalate(
                        state,
                        input.caller_role,
                        &input.target.vm,
                        input.role_id,
                    );
                    let outcome = if cgroup_empty {
                        VmShutdownOutcome::CleanGuestShutdown
                    } else {
                        VmShutdownOutcome::CleanupFailed
                    };
                    return (
                        outcome,
                        Some(VmStopRoleReport {
                            role_id: input.role_id.to_owned(),
                            required_sigkill: false,
                            shutdown_outcome: Some(outcome),
                        }),
                    );
                }
                return (VmShutdownOutcome::ApiUnavailable, None);
            }
            _ = tokio::time::sleep(tick) => {}
        }
        match input.provider.poll_state(input.target).await {
            provider_shutdown::ProviderGuestState::GuestStopped => {
                let _ = input.provider.request_vmm_exit(input.target).await;
                if wait_registered_pidfd_exit(
                    state,
                    &input.target.vm,
                    input.role_id,
                    EMPTY_VMM_CLEANUP_GRACE,
                )
                .await
                {
                    finish_terminated_runner(
                        state,
                        input.caller_role.clone(),
                        &input.target.vm,
                        input.role_id,
                    );
                    let cgroup_empty = prove_role_cgroup_empty_or_escalate(
                        state,
                        input.caller_role,
                        &input.target.vm,
                        input.role_id,
                    );
                    let outcome = if cgroup_empty {
                        VmShutdownOutcome::CleanVmmCleanup
                    } else {
                        VmShutdownOutcome::CleanupFailed
                    };
                    return (
                        outcome,
                        Some(VmStopRoleReport {
                            role_id: input.role_id.to_owned(),
                            required_sigkill: false,
                            shutdown_outcome: Some(outcome),
                        }),
                    );
                }
                return (VmShutdownOutcome::ForcedCleanup, None);
            }
            provider_shutdown::ProviderGuestState::Running
            | provider_shutdown::ProviderGuestState::Unknown { .. } => {}
        }
    }
}

struct ProviderStopInputs<'a> {
    caller_role: BrokerCallerRole,
    verb: &'a str,
    vm: &'a str,
    role_id: &'a str,
    stop_entries: &'a [PidfdRegistration],
    term_timeout: Duration,
    kill_timeout: Duration,
    force_requested: bool,
}

fn stop_vmm_runner_with_provider(
    state: &ServerState,
    input: ProviderStopInputs<'_>,
) -> Option<Result<VmStopRoleReport, Value>> {
    if let Some(providers) = state.provider_runtime.process_providers()
        && providers.has_active_role(input.vm, input.role_id)
    {
        return Some(stop_vm_pidfd_role(
            state,
            input.caller_role.clone(),
            input.verb,
            input.vm,
            input.role_id,
            input.term_timeout,
            input.kill_timeout,
        ));
    }
    let manifest_entry = manifest_entry_for_vm(state, input.vm)?;
    let target = provider_shutdown_target_for_role(&manifest_entry, input.vm, input.role_id)?;
    let graceful_timeout = graceful_shutdown_timeout_for(state, &manifest_entry);
    if emit_vm_shutdown_intent_audit(
        state,
        input.vm,
        &input.caller_role,
        Some(target.kind),
        input.force_requested,
        graceful_timeout.as_secs(),
    )
    .is_err()
    {
        return Some(Err(daemon_failure_response(
            input.verb,
            "authoritative VM shutdown intent audit failed".to_owned(),
        )));
    }
    let started = Instant::now();
    if input.force_requested {
        let report = stop_vm_pidfd_role(
            state,
            input.caller_role.clone(),
            input.verb,
            input.vm,
            input.role_id,
            input.term_timeout,
            input.kill_timeout,
        );
        let audit_outcome = report
            .as_ref()
            .ok()
            .and_then(|report| report.shutdown_outcome)
            .unwrap_or(VmShutdownOutcome::ForceRequested);
        record_vm_shutdown_metric(state, Some(target.kind), audit_outcome, started.elapsed());
        if emit_vm_shutdown_outcome_audit(
            state,
            input.vm,
            &input.caller_role,
            Some(target.kind),
            audit_outcome,
            started.elapsed(),
        )
        .is_err()
        {
            return Some(Err(daemon_failure_response(
                input.verb,
                "authoritative VM shutdown outcome audit failed".to_owned(),
            )));
        }
        return Some(report.map(|mut report| {
            if report.shutdown_outcome != Some(VmShutdownOutcome::CleanupFailed) {
                report.shutdown_outcome = Some(VmShutdownOutcome::ForceRequested);
            }
            report
        }));
    }
    if !graceful_shutdown_enabled(&manifest_entry) {
        let report = stop_vm_pidfd_role(
            state,
            input.caller_role.clone(),
            input.verb,
            input.vm,
            input.role_id,
            input.term_timeout,
            input.kill_timeout,
        );
        let audit_outcome = report
            .as_ref()
            .ok()
            .and_then(|report| report.shutdown_outcome)
            .unwrap_or(VmShutdownOutcome::Disabled);
        record_vm_shutdown_metric(state, Some(target.kind), audit_outcome, started.elapsed());
        if emit_vm_shutdown_outcome_audit(
            state,
            input.vm,
            &input.caller_role,
            Some(target.kind),
            audit_outcome,
            started.elapsed(),
        )
        .is_err()
        {
            return Some(Err(daemon_failure_response(
                input.verb,
                "authoritative VM shutdown outcome audit failed".to_owned(),
            )));
        }
        return Some(report.map(|mut report| {
            if report.shutdown_outcome != Some(VmShutdownOutcome::CleanupFailed) {
                report.shutdown_outcome = Some(VmShutdownOutcome::Disabled);
            }
            report
        }));
    }

    let sidecars = required_sidecars_for_graceful_wait(input.stop_entries);
    let force_generation_baseline = force_shutdown_generation(state, input.vm);
    let provider: Box<dyn provider_shutdown::GracefulVmShutdown> = match target.kind {
        provider_shutdown::ProviderKind::CloudHypervisor => {
            Box::new(provider_shutdown::CloudHypervisorShutdown::default())
        }
        provider_shutdown::ProviderKind::QemuMedia => Box::new(QemuBrokerShutdownProvider {
            socket_path: broker_socket_path(state),
            caller_role: input.caller_role.clone(),
            timeout: d2bd_runtime::ch_api::DEFAULT_TIMEOUT,
        }),
    };
    let (outcome, report) = block_on_future(run_provider_graceful_shutdown(
        state,
        ProviderGracefulInputs {
            provider: provider.as_ref(),
            target: &target,
            role_id: input.role_id,
            sidecars: &sidecars,
            timeout: graceful_timeout,
            force_generation_baseline,
            caller_role: input.caller_role.clone(),
        },
    ));
    if let Some(report) = report {
        record_vm_shutdown_metric(state, Some(target.kind), outcome, started.elapsed());
        if emit_vm_shutdown_outcome_audit(
            state,
            input.vm,
            &input.caller_role,
            Some(target.kind),
            outcome,
            started.elapsed(),
        )
        .is_err()
        {
            return Some(Err(daemon_failure_response(
                input.verb,
                "authoritative VM shutdown outcome audit failed".to_owned(),
            )));
        }
        return Some(Ok(report));
    }

    let fallback = stop_vm_pidfd_role(
        state,
        input.caller_role.clone(),
        input.verb,
        input.vm,
        input.role_id,
        input.term_timeout,
        input.kill_timeout,
    );
    let fallback = fallback.map(|mut report| {
        let final_outcome = match report.shutdown_outcome {
            Some(VmShutdownOutcome::CleanupFailed) => VmShutdownOutcome::CleanupFailed,
            _ => outcome,
        };
        report.shutdown_outcome = Some(final_outcome);
        report
    });
    let audit_outcome = fallback
        .as_ref()
        .ok()
        .and_then(|report| report.shutdown_outcome)
        .unwrap_or(outcome);
    record_vm_shutdown_metric(state, Some(target.kind), audit_outcome, started.elapsed());
    if emit_vm_shutdown_outcome_audit(
        state,
        input.vm,
        &input.caller_role,
        Some(target.kind),
        audit_outcome,
        started.elapsed(),
    )
    .is_err()
    {
        return Some(Err(daemon_failure_response(
            input.verb,
            "authoritative VM shutdown outcome audit failed".to_owned(),
        )));
    }
    Some(fallback)
}

fn wait_terminated_with_broker_poll(
    state: &ServerState,
    vm: &str,
    role_id: &str,
    deadline: Instant,
) -> Result<WaitTermination, PidfdTableError> {
    let started = Instant::now();
    let mut poll_count: u32 = 0;
    loop {
        let now = Instant::now();
        if now >= deadline {
            return Ok(WaitTermination::TimedOut);
        }
        let remaining = deadline.saturating_duration_since(now);
        match state.pidfd_table.wait_terminated(vm, role_id, remaining) {
            Ok(WaitTermination::Terminated) => return Ok(WaitTermination::Terminated),
            Ok(WaitTermination::TerminatedByBroker { exit_status }) => {
                return Ok(WaitTermination::TerminatedByBroker { exit_status });
            }
            Ok(WaitTermination::TimedOut) => return Ok(WaitTermination::TimedOut),
            Err(PidfdTableError::WaitFailed {
                errno: Some(libc::ECHILD),
                ..
            }) => {
                if !state.pidfd_table.still_alive_same_start_time(vm, role_id) {
                    return Ok(WaitTermination::Terminated);
                }
                poll_count = poll_count.saturating_add(1);
                let budget = remaining.min(Duration::from_millis(200));
                if let Ok(BrokerResponse::PollChildReaped(resp)) =
                    dispatch_broker_request_with_timeout(
                        state,
                        BrokerRequest::PollChildReaped,
                        budget,
                    )
                {
                    for notification in resp.notifications {
                        state.broker_reap_log.insert(notification);
                    }
                    if let Some(notification) = state.broker_reap_log.take_for(vm, role_id) {
                        let elapsed = started.elapsed();
                        tracing::info!(
                            outcome = "echild-broker-recovered",
                            vm = %vm,
                            role = %role_id,
                            poll_count,
                            elapsed_ms = elapsed.as_millis() as u64,
                            "stop reap recovered via broker reap log"
                        );
                        return Ok(WaitTermination::TerminatedByBroker {
                            exit_status: notification.exit_status,
                        });
                    }
                }
                std::thread::sleep(Duration::from_millis(50));
            }
            Err(error) => return Err(error),
        }
    }
}

fn stop_vm_pidfd_role(
    state: &ServerState,
    caller_role: BrokerCallerRole,
    verb: &str,
    vm: &str,
    role_id: &str,
    term_timeout: Duration,
    kill_timeout: Duration,
) -> Result<VmStopRoleReport, Value> {
    if let Some(providers) = state.provider_runtime.process_providers()
        && providers.has_active_role(vm, role_id)
    {
        let node = providers.node_for_role(vm, role_id).ok_or_else(|| {
            daemon_failure_response(
                verb,
                format!("vm stop {vm}: Provider node missing for {role_id}"),
            )
        })?;
        let required_sigkill =
            match block_on_future(providers.stop_node(vm, &node, term_timeout, kill_timeout)) {
                Ok(required_sigkill) => required_sigkill,
                Err(error) if error == "provider-process-not-found" => {
                    return Err(invalid_request_response(
                        verb,
                        format!("vm '{vm}' has no registered Provider process for {role_id}"),
                    ));
                }
                Err(error) => {
                    return Err(daemon_failure_response(
                        verb,
                        format!("vm stop {vm}: Provider stop failed for {role_id}: {error}"),
                    ));
                }
            };
        let cgroup_empty = prove_role_cgroup_empty_or_escalate(state, caller_role, vm, role_id);
        return Ok(VmStopRoleReport {
            role_id: role_id.to_owned(),
            required_sigkill,
            shutdown_outcome: (!cgroup_empty).then_some(VmShutdownOutcome::CleanupFailed),
        });
    }
    tracing::info!(vm = %vm, role = %role_id, signal = "SIGTERM", "sending pidfd stop signal");
    match state.pidfd_table.signal(vm, role_id, libc::SIGTERM) {
        Ok(()) => {}
        Err(PidfdTableError::SignalFailed {
            errno: Some(libc::ESRCH),
            ..
        }) => {
            tracing::info!(
                vm = %vm,
                role = %role_id,
                signal = "SIGTERM",
                outcome = "already-exited",
                "pidfd signal target was already gone"
            );
        }
        Err(PidfdTableError::SignalFailed {
            errno: Some(libc::EPERM),
            ..
        }) => {
            signal_via_broker(state, caller_role.clone(), vm, role_id, RunnerSignal::Term)?;
            d2bd_runtime::metrics::record_broker_request(
                &state.metrics_registry,
                "SignalRunner",
                "broker-fallback",
            );
            tracing::info!(
                outcome = "broker-fallback",
                broker_signaled = true,
                vm = %vm,
                role = %role_id,
                signal = "SIGTERM",
                "pidfd signal EPERM recovered through broker"
            );
        }
        Err(PidfdTableError::NotFound { .. }) => {
            return Err(invalid_request_response(
                verb,
                format!("vm '{}' has no registered {} pidfd", vm, role_id),
            ));
        }
        Err(error) => {
            tracing::warn!(vm = %vm, role = %role_id, error = ?error, "SIGTERM failed");
            return Err(daemon_failure_response(
                verb,
                format!("vm stop {vm}: pidfd_table SIGTERM failed for {role_id}"),
            ));
        }
    }

    refresh_broker_reap_log(state, "before-sigterm-wait");
    match wait_terminated_with_broker_poll(state, vm, role_id, Instant::now() + term_timeout) {
        Ok(WaitTermination::Terminated) | Ok(WaitTermination::TerminatedByBroker { .. }) => {
            tracing::info!(
                vm = %vm,
                role = %role_id,
                signal = "SIGTERM",
                timeout_ms = term_timeout.as_millis(),
                outcome = "terminated",
                "role terminated after SIGTERM"
            );
            finish_terminated_runner(state, caller_role.clone(), vm, role_id);
            let cgroup_empty =
                prove_role_cgroup_empty_or_escalate(state, caller_role.clone(), vm, role_id);
            return Ok(VmStopRoleReport {
                role_id: role_id.to_owned(),
                required_sigkill: false,
                shutdown_outcome: (!cgroup_empty).then_some(VmShutdownOutcome::CleanupFailed),
            });
        }
        Ok(WaitTermination::TimedOut) => {
            tracing::warn!(
                vm = %vm,
                role = %role_id,
                signal = "SIGTERM",
                timeout_ms = term_timeout.as_millis(),
                "SIGTERM wait timed out; escalating to SIGKILL"
            );
        }
        Err(PidfdTableError::NotFound { .. }) => {
            return Err(invalid_request_response(
                verb,
                format!("vm '{}' has no registered {} pidfd", vm, role_id),
            ));
        }
        Err(error) => {
            tracing::warn!(vm = %vm, role = %role_id, error = ?error, "wait after SIGTERM failed");
            return Err(daemon_failure_response(
                verb,
                format!("vm stop {vm}: wait after SIGTERM failed for {role_id}"),
            ));
        }
    }

    tracing::info!(vm = %vm, role = %role_id, signal = "SIGKILL", "sending pidfd kill signal");
    match state.pidfd_table.signal(vm, role_id, libc::SIGKILL) {
        Ok(()) => {}
        Err(PidfdTableError::SignalFailed {
            errno: Some(libc::ESRCH),
            ..
        }) => {
            tracing::info!(
                vm = %vm,
                role = %role_id,
                signal = "SIGKILL",
                outcome = "already-exited",
                "pidfd kill target was already gone"
            );
        }
        Err(PidfdTableError::SignalFailed {
            errno: Some(libc::EPERM),
            ..
        }) => {
            signal_via_broker(state, caller_role.clone(), vm, role_id, RunnerSignal::Kill)?;
            d2bd_runtime::metrics::record_broker_request(
                &state.metrics_registry,
                "SignalRunner",
                "broker-fallback",
            );
            tracing::info!(
                outcome = "broker-fallback",
                broker_signaled = true,
                vm = %vm,
                role = %role_id,
                signal = "SIGKILL",
                "pidfd signal EPERM recovered through broker"
            );
        }
        Err(PidfdTableError::NotFound { .. }) => {
            return Err(invalid_request_response(
                verb,
                format!("vm '{}' has no registered {} pidfd", vm, role_id),
            ));
        }
        Err(error) => {
            tracing::warn!(vm = %vm, role = %role_id, error = ?error, "SIGKILL failed");
            return Err(daemon_failure_response(
                verb,
                format!("vm stop {vm}: pidfd_table SIGKILL failed for {role_id}"),
            ));
        }
    }

    refresh_broker_reap_log(state, "before-sigkill-wait");
    match wait_terminated_with_broker_poll(state, vm, role_id, Instant::now() + kill_timeout) {
        Ok(WaitTermination::Terminated) | Ok(WaitTermination::TerminatedByBroker { .. }) => {
            tracing::info!(
                vm = %vm,
                role = %role_id,
                signal = "SIGKILL",
                timeout_ms = kill_timeout.as_millis(),
                outcome = "terminated",
                "role terminated after SIGKILL"
            );
            finish_terminated_runner(state, caller_role.clone(), vm, role_id);
            let cgroup_empty = prove_role_cgroup_empty_or_escalate(state, caller_role, vm, role_id);
            Ok(VmStopRoleReport {
                role_id: role_id.to_owned(),
                required_sigkill: true,
                shutdown_outcome: (!cgroup_empty).then_some(VmShutdownOutcome::CleanupFailed),
            })
        }
        Ok(WaitTermination::TimedOut) => Err(daemon_failure_response(
            verb,
            format!("vm stop {vm}: timed out waiting for {role_id} after SIGKILL"),
        )),
        Err(PidfdTableError::NotFound { .. }) => Err(invalid_request_response(
            verb,
            format!("vm '{}' has no registered {} pidfd", vm, role_id),
        )),
        Err(error) => {
            tracing::warn!(vm = %vm, role = %role_id, error = ?error, "wait after SIGKILL failed");
            Err(daemon_failure_response(
                verb,
                format!("vm stop {vm}: wait after SIGKILL failed for {role_id}"),
            ))
        }
    }
}

fn vm_start_success_summary(report: &d2bd_runtime::supervisor::dag::DagRunReport) -> String {
    let ready_nodes = report
        .history
        .iter()
        .filter_map(|entry| match &entry.outcome {
            d2bd_runtime::supervisor::dag::NodeOutcome::Ready => Some(entry.node_id.0.as_str()),
            _ => None,
        })
        .collect::<Vec<_>>();
    format!(
        "vm start {}: supervisor DAG ready ({} nodes: {}); registered in pidfd_table",
        report.vm,
        ready_nodes.len(),
        ready_nodes.join(" -> ")
    )
}

fn vm_start_failure_response(report: &d2bd_runtime::supervisor::dag::DagRunReport) -> Value {
    let summary = report
        .history
        .iter()
        .find_map(|entry| match &entry.outcome {
            d2bd_runtime::supervisor::dag::NodeOutcome::Failed { .. } => {
                Some(format!("SpawnRunner failed at {}", entry.node_id.0))
            }
            _ => None,
        })
        .unwrap_or_else(|| "SpawnRunner failed".to_owned());
    broker_failure_response(
        "vm start",
        summary,
        "Supervisor DAG aborted before every readiness deadline passed. Admin: inspect `journalctl -u d2bd` for the per-node supervisor audit.".to_owned(),
        None,
    )
}

fn log_vm_start_report(report: &d2bd_runtime::supervisor::dag::DagRunReport) {
    for entry in &report.history {
        match &entry.outcome {
            d2bd_runtime::supervisor::dag::NodeOutcome::Ready => tracing::info!(
                vm = %report.vm,
                node = %entry.node_id.0,
                outcome = "ready",
                "vm start DAG node completed"
            ),
            d2bd_runtime::supervisor::dag::NodeOutcome::Failed { reason } => tracing::warn!(
                vm = %report.vm,
                node = %entry.node_id.0,
                outcome = "failed",
                reason = %reason,
                "vm start DAG node failed"
            ),
            d2bd_runtime::supervisor::dag::NodeOutcome::Skipped { predecessor } => tracing::warn!(
                vm = %report.vm,
                node = %entry.node_id.0,
                outcome = "skipped",
                predecessor = %predecessor.0,
                "vm start DAG node skipped after predecessor failure"
            ),
        }
    }
}

/// Log the planned host-prep DAG so `journalctl -u d2bd.service`
/// and the autostart-history
/// records carry the canonical step set per VM. Runs on every VM
/// start regardless of whether `D2B_HOST_PREP_DAG_EXECUTE` is
/// set.
fn log_host_prep_dag(vm: &str, steps: &[d2b_host::host_prep_dag::HostPrepStep]) {
    tracing::info!(
        vm = %vm,
        step_count = steps.len(),
        "host-prep DAG resolved"
    );
    for step in steps {
        tracing::info!(
            vm = %vm,
            step_id = %step.id,
            kind = step.kind.as_str(),
            broker_op = step.kind.broker_op_name(),
            depends_on = ?step.depends_on.iter().map(|d| d.as_str()).collect::<Vec<_>>(),
            "host-prep DAG step"
        );
    }
}

/// Extract a role id from the DAG step's bundle_ref, falling back to a
/// step-default. The runner intent id
/// shape `runner:vm:<vm>:role:<role>` lets us derive the role
/// mechanically; if the step did not carry a bundle_op_id we use
/// the default (`ch` for tap/vhost-net).
fn host_prep_role_id_from_bundle_ref(
    bundle_ref: &d2b_host::host_prep_dag::BundleStepRef,
    default_role: &str,
) -> RoleId {
    let role = bundle_ref
        .bundle_op_id
        .as_ref()
        .and_then(|id| id.as_str().rsplit_once(":role:").map(|(_, r)| r.to_owned()))
        .unwrap_or_else(|| default_role.to_owned());
    RoleId::new(role)
}

/// Dispatch a broker request for one host-prep DAG step where the broker
/// may return a typed response
/// (e.g. `CreatePersistentTap`, `SetBridgePortFlags`) rather than
/// the canonical `Ack`. Treats any non-`Error` response as success
/// and surfaces `Error` responses through the same launcher-side
/// redaction path used by `dispatch_broker_ack_request`. Any fd
/// the broker attaches via SCM_RIGHTS is silently discarded by the
/// kernel because `dispatch_broker_request` does not allocate an
/// ancillary buffer.
fn dispatch_broker_host_prep_step(
    state: &ServerState,
    verb: &str,
    op_name: &str,
    request: BrokerRequest,
    caller_role: BrokerCallerRole,
) -> Result<(), Value> {
    match dispatch_broker_request_as(state, request, caller_role) {
        Ok(BrokerResponse::Error(error)) => {
            tracing::warn!(
                broker_kind = %error.kind,
                broker_operation = %error.operation,
                broker_target_wave = error.target_wave.as_deref().unwrap_or("none"),
                broker_message = %error.message,
                broker_action = %error.action,
                "broker live op failed"
            );
            let (summary, remediation) = redact_broker_error_for_launcher(
                op_name,
                error.target_wave.as_deref(),
                &error.kind,
            );
            Err(broker_failure_response(
                verb,
                summary,
                remediation,
                error.target_wave,
            ))
        }
        Ok(_) => Ok(()),
        Err(error) => {
            tracing::warn!(op_name = op_name, error = ?error, "broker dispatch failed");
            let (summary, remediation) = redact_broker_dispatch_failure_for_launcher(op_name);
            Err(broker_failure_response(verb, summary, remediation, None))
        }
    }
}

/// Execute the host-prep DAG by dispatching the corresponding broker op
/// for each step in topo order. On step failure surfaces the broker
/// envelope; the operator sees the step id, the broker op kind, and the
/// broker error string (the typed `HostPrepStepFailed` shape lives in
/// `d2b_host::host_prep_dag`). Gated by
/// `D2B_HOST_PREP_DAG_EXECUTE` until the broker handlers land.
fn execute_host_prep_dag(
    state: &ServerState,
    vm: &str,
    steps: &[d2b_host::host_prep_dag::HostPrepStep],
    caller_role: BrokerCallerRole,
) -> Result<(), Value> {
    use d2b_host::host_prep_dag::HostPrepStepKind;
    const VERB: &str = "vm start";
    // Resolve the per-VM state directory once (used by daemon-native
    // step handlers that need filesystem context, e.g. the
    // ssh-host-key preflight). Missing manifest entries are tolerated
    // here: the broker-dispatching path simply proceeds, and
    // daemon-native handlers gracefully no-op.
    let per_vm_state_dir: Option<PathBuf> = load_bundle_resolver(state)
        .ok()
        .and_then(|r| r.manifest.vms.get(vm).map(|m| PathBuf::from(&m.state_dir)));
    let network_tap_context = load_bundle_resolver(state)
        .ok()
        .and_then(|resolver| network_tap_context_for_vm(state, &resolver, vm));
    for step in steps {
        let op_name = step.kind.broker_op_name();
        let request = match step.kind {
            HostPrepStepKind::ApplyNftablesRules => {
                let nft_ref = step
                    .bundle_ref
                    .bundle_op_id
                    .clone()
                    .unwrap_or_else(|| BundleOpId::new(intent_id_nft_host()));
                let scope_id = step
                    .bundle_ref
                    .scope_id
                    .clone()
                    .unwrap_or_else(|| ScopeId::new("host"));
                if scope_id.as_str().starts_with("env:") {
                    tracing::warn!(
                        vm = %vm,
                        step_id = %step.id,
                        op_kind = op_name,
                        "host-prep env firewall application refused: Network admission context is required"
                    );
                    continue;
                }
                BrokerRequest::ApplyNftables(BrokerApplyNftablesRequest {
                    bundle_nft_intent_ref: nft_ref,
                    scope_id,
                    desired_hash: None,
                    destroy: false,
                    tracing_span_id: None,
                })
            }
            HostPrepStepKind::SeedDnsmasqLease => {
                tracing::warn!(
                    vm = %vm,
                    step_id = %step.id,
                    op_kind = op_name,
                    "host-prep DHCP seeding refused: Network admission context is required"
                );
                continue;
            }
            HostPrepStepKind::BindMountFromHardlinkFarm => {
                BrokerRequest::BindMountFromHardlinkFarm(
                    d2b_contracts_broker::broker_wire::BindMountFromHardlinkFarmRequest {
                        vm_id: step.bundle_ref.vm_id.clone(),
                        bundle_store_view_intent_ref: step.bundle_ref.bundle_op_id.clone(),
                        tracing_span_id: None,
                    },
                )
            }
            HostPrepStepKind::OwnershipMatrixCheck => BrokerRequest::OwnershipMatrixCheck(
                d2b_contracts_broker::broker_wire::OwnershipMatrixCheckRequest {
                    vm_id: step.bundle_ref.vm_id.clone(),
                    tracing_span_id: None,
                },
            ),
            HostPrepStepKind::SshHostKeyPreflight => {
                // Run the daemon-native posture check instead of dispatching
                // the broker stub. The broker variant remains in the
                // wire enum as a typed placeholder; the live handler
                // lives daemon-side because the check is a pure
                // filesystem stat against a state subtree the daemon
                // already has `CAP_DAC_READ_SEARCH` for.
                let keys_dir = match per_vm_state_dir.as_ref() {
                    Some(d) => d.join("sshd-host-keys"),
                    None => {
                        tracing::warn!(
                            vm = %vm,
                            step_id = %step.id,
                            "ssh-host-key-preflight: no manifest entry resolvable; skipping",
                        );
                        continue;
                    }
                };
                if !keys_dir.exists() {
                    tracing::warn!(
                        vm = %vm,
                        step_id = %step.id,
                        outcome = "skipped-keys-dir-absent",
                        "ssh-host-key-preflight: keys directory absent; skipping (will be materialized on first run)",
                    );
                    continue;
                }
                if let Err(drift) =
                    d2bd_runtime::ssh_host_key_preflight::check_sshd_host_keys(vm, &keys_dir)
                {
                    let path = drift.path().to_path_buf();
                    let drift_reason = drift.reason();
                    tracing::warn!(
                        vm = %vm,
                        step_id = %step.id,
                        outcome = "ssh-host-key-drift",
                        drift_kind = ?drift_reason,
                        "host-prep DAG step failed: ssh-host-key drift (path in typed envelope + audit log)",
                    );
                    return Err(TypedError::SshdHostKeyDrift {
                        vm: vm.to_owned(),
                        path,
                        drift: drift_reason,
                    }
                    .to_envelope_value());
                }
                continue;
            }
            // Live broker dispatch for the step kinds that previously
            // skipped-with-log. Each arm composes an existing broker op.
            HostPrepStepKind::BringUpTapInterface => {
                let Some(context) = network_tap_context.as_ref() else {
                    tracing::warn!(
                        vm = %vm,
                        step_id = %step.id,
                        op_kind = op_name,
                        "host-prep TAP creation refused: Network admission context is required"
                    );
                    return Err(broker_failure_response(
                        VERB,
                        "Network admission context is required for TAP creation".to_owned(),
                        "Refresh the committed Network and attachment state before retrying VM start."
                            .to_owned(),
                        None,
                    ));
                };
                let role_id = host_prep_role_id_from_bundle_ref(&step.bundle_ref, "ch");
                let provenance = NetworkProvenance::new(
                    context.zone_uid.clone(),
                    context.network_uid.clone(),
                    context.network_generation,
                    context.attachment_generation,
                    context.bundle_generation.clone(),
                );
                let tap_identity = match resolve_tap_identity(
                    &provenance,
                    &step.bundle_ref.vm_id,
                    role_id.as_str(),
                    &context.attachment_id,
                ) {
                    Ok(identity) => identity,
                    Err(error) => {
                        tracing::warn!(
                            vm = %vm,
                            step_id = %step.id,
                            op_kind = op_name,
                            error = error.code(),
                            "host-prep TAP identity resolution refused"
                        );
                        return Err(broker_failure_response(
                            VERB,
                            "Network TAP identity resolution was refused".to_owned(),
                            "Refresh the committed Network admission before retrying VM start."
                                .to_owned(),
                            None,
                        ));
                    }
                };
                let req = BrokerRequest::CreatePersistentTap(
                    d2b_contracts_broker::broker_wire::CreatePersistentTapRequest {
                        role_id: role_id.clone(),
                        vm_id: step.bundle_ref.vm_id.clone(),
                        bundle_tap_intent_ref: tap_identity.intent_ref,
                        attachment_id: context.attachment_id.clone(),
                        network_generation: context.network_generation,
                        attachment_generation: context.attachment_generation,
                        zone_uid: context.zone_uid.clone(),
                        network_uid: context.network_uid.clone(),
                        bundle_generation: context.bundle_generation.clone(),
                        admitted_interface_names: context.admitted_interface_names.clone(),
                        tracing_span_id: None,
                    },
                );
                if let Err(response) =
                    dispatch_broker_host_prep_step(state, VERB, op_name, req, caller_role.clone())
                {
                    tracing::warn!(
                        vm = %vm,
                        step_id = %step.id,
                        op_kind = op_name,
                        "host-prep step failed"
                    );
                    return Err(response);
                }
                continue;
            }
            HostPrepStepKind::PreOpenVhostNetFd => {
                // Dispatch OpenVhostNet for role `ch`. The broker returns
                // an SCM_RIGHTS fd
                // alongside an `Ack`; we don't need the fd here
                // (the runner re-requests it at spawn), so the
                // ack-only dispatcher discards it via MSG_CTRUNC.
                let role_id = host_prep_role_id_from_bundle_ref(&step.bundle_ref, "ch");
                let req = BrokerRequest::OpenVhostNet(
                    d2b_contracts_broker::broker_wire::OpenVhostNetRequest {
                        role_id,
                        tracing_span_id: None,
                    },
                );
                if let Err(response) =
                    dispatch_broker_host_prep_step(state, VERB, op_name, req, caller_role.clone())
                {
                    tracing::warn!(
                        vm = %vm,
                        step_id = %step.id,
                        op_kind = op_name,
                        "host-prep DAG step failed"
                    );
                    return Err(response);
                }
                continue;
            }
            HostPrepStepKind::ApplyNmUnmanaged => {
                // Compose ApplyNmUnmanaged against the single host-wide
                // intent row
                // (`nm-unmanaged:host`). The scope_id falls back to
                // the bundle_ref's env scope when the DAG carries
                // one; otherwise "host".
                let scope_id = step
                    .bundle_ref
                    .scope_id
                    .clone()
                    .unwrap_or_else(|| ScopeId::new("host"));
                let req = BrokerRequest::ApplyNmUnmanaged(BrokerApplyNmUnmanagedRequest {
                    bundle_nm_intent_ref: BundleOpId::new(intent_id_nm_unmanaged_host()),
                    scope_id,
                    destroy: false,
                    tracing_span_id: None,
                });
                if let Err(response) =
                    dispatch_broker_ack_request_as(state, VERB, op_name, req, caller_role.clone())
                {
                    tracing::warn!(
                        vm = %vm,
                        step_id = %step.id,
                        op_kind = op_name,
                        "host-prep DAG step failed"
                    );
                    return Err(response);
                }
                continue;
            }
            HostPrepStepKind::ApplySysctl => {
                tracing::warn!(
                    vm = %vm,
                    step_id = %step.id,
                    op_kind = op_name,
                    "host-prep sysctl application refused: Network admission context is required"
                );
                continue;
            }
            HostPrepStepKind::SetBridgePortFlags => {
                tracing::warn!(
                    vm = %vm,
                    step_id = %step.id,
                    op_kind = op_name,
                    "host-prep bridge-port mutation refused: Network admission context is required"
                );
                continue;
            }
            // HostNetRoutePreflight is host-scope and is executed inline
            // by the daemon at startup (and via
            // `d2b host reconcile --network`).
            // It is not dispatched per-VM through this DAG; the arm
            // exists for exhaustiveness only.
            HostPrepStepKind::HostNetRoutePreflight => {
                tracing::info!(
                    vm = %vm,
                    step_id = %step.id,
                    kind = step.kind.as_str(),
                    "host-prep DAG step skipped (host-scope; executed by daemon startup + reconcile path)"
                );
                continue;
            }
        };
        if let Err(response) =
            dispatch_broker_ack_request_as(state, VERB, op_name, request, caller_role.clone())
        {
            tracing::warn!(
                vm = %vm,
                step_id = %step.id,
                op_kind = op_name,
                "host-prep DAG step failed"
            );
            return Err(response);
        }
    }
    Ok(())
}

#[cfg(test)]
fn dispatch_broker_vm_start(
    state: &ServerState,
    request: public_wire::VmLifecycleRequest,
) -> Result<Value, TypedError> {
    if load_bundle_resolver(state).ok().is_some_and(|resolver| {
        resolver
            .usbip_bind_intent_ids()
            .filter_map(|intent_id| resolver.find_usbip_bind_intent(intent_id))
            .any(|intent| intent.vm_name == request.vm)
    }) {
        return dispatch_broker_vm_start_as(
            state,
            request,
            BrokerCallerRole::AdminUid {
                uid: state.daemon_uid,
            },
        );
    }
    dispatch_broker_vm_start_inner(
        state,
        request,
        BrokerCallerRole::AdminUid {
            uid: state.daemon_uid,
        },
        None,
    )
}

fn dispatch_broker_vm_start_as(
    state: &ServerState,
    request: public_wire::VmLifecycleRequest,
    caller_role: BrokerCallerRole,
) -> Result<Value, TypedError> {
    const VERB: &str = "vm start";

    if let Some(response) = mutating_verb_preflight(VERB, &request.flags, Some(request.vm.as_str()))
    {
        return Ok(response);
    }

    let resolver = load_bundle_resolver(state)?;
    if resolver
        .usbip_bind_intent_ids()
        .filter_map(|intent_id| resolver.find_usbip_bind_intent(intent_id))
        .any(|intent| intent.vm_name == request.vm)
    {
        return Err(usbip_guest_import_unavailable(&request.vm, VERB));
    }

    let operation_id = next_provider_lifecycle_operation_id("start", &request);
    let authorization =
        provider_lifecycle_authorization(state, &request.vm, &caller_role, &operation_id)?;
    let effect = DaemonProviderLifecycleEffect {
        state,
        request: request.clone(),
        caller_role: caller_role.clone(),
        term_timeout: VM_STOP_TIMEOUT,
        kill_timeout: VM_STOP_TIMEOUT,
        operation: provider_effects::GuestLifecycleOperation::Start,
        authorization: authorization.clone(),
    };
    match state.provider_runtime.dispatch_lifecycle(
        &effect.caller_role,
        &request.vm,
        effect.operation,
        operation_id,
        authorization,
        &effect,
    ) {
        Ok(provider_registry::ProviderRuntimeDispatch::Active(
            provider_effects::EffectDispatch::Dispatched(response),
        )) => Ok(response),
        Ok(provider_registry::ProviderRuntimeDispatch::Active(
            provider_effects::EffectDispatch::Duplicate,
        )) => Ok(applied_response(
            VERB,
            format!(
                "vm start {}: duplicate Provider lifecycle request",
                request.vm
            ),
        )),
        Err(error) => Ok(provider_lifecycle_failure_response(
            VERB,
            &request.vm,
            error,
        )),
    }
}

struct DaemonGuestLifecycleEffect<'a> {
    state: &'a ServerState,
    runtime: Arc<resource_runtime::ZoneResourceRuntime>,
    guest: ResourceRef,
    caller_role: BrokerCallerRole,
    force: bool,
    wait_for_ready: bool,
    operation: provider_effects::GuestLifecycleOperation,
    authorization: provider_effects::LifecycleAuthorization,
}

impl DaemonGuestLifecycleEffect<'_> {
    fn verify_identity(&self) -> Result<(), provider_effects::ProviderEffectError> {
        let (zone_uid, guest_uid, guest_generation, provider_generation) =
            block_on_future(self.runtime.guest_lifecycle_identity(&self.guest))
                .map_err(|_| provider_effects::ProviderEffectError::StateUnavailable)?;
        if zone_uid != *self.authorization.zone_uid()
            || guest_uid != *self.authorization.guest_uid()
            || guest_generation != self.authorization.guest_generation()
            || provider_generation != self.authorization.provider_assignment_generation()
            || self.runtime.committed_policy_snapshot().policy_revision
                != self.authorization.policy_revision()
        {
            return Err(provider_effects::ProviderEffectError::IdentityMismatch);
        }
        Ok(())
    }
}

impl provider_effects::ProviderLifecycleEffectPort for DaemonGuestLifecycleEffect<'_> {
    type Output = Value;

    fn actual_state(
        &self,
        _request: &provider_effects::GuestLifecycleRequest,
    ) -> Result<provider_effects::GuestLifecycleState, provider_effects::ProviderEffectError> {
        self.verify_identity()?;
        block_on_future(
            self.runtime
                .cloud_hypervisor_lifecycle_state(Arc::new(self.state.clone()), &self.guest),
        )
        .map_err(|_| provider_effects::ProviderEffectError::StateUnavailable)
    }

    fn apply(
        &self,
        _request: &provider_effects::GuestLifecycleRequest,
    ) -> Result<Self::Output, provider_effects::ProviderEffectError> {
        self.verify_identity()?;
        consume_lifecycle_lease(
            self.state,
            &self.authorization,
            self.operation,
            &self.caller_role,
        )?;
        let _ = self.force;
        block_on_future(self.runtime.apply_cloud_hypervisor_lifecycle(
            Arc::new(self.state.clone()),
            &self.guest,
            self.authorization.guest_uid(),
            self.authorization.guest_generation(),
            self.operation,
        ))
        .map_err(|_| provider_effects::ProviderEffectError::EffectRejected)?;
        if self.wait_for_ready {
            block_on_future(self.runtime.wait_cloud_hypervisor_lifecycle(
                Arc::new(self.state.clone()),
                &self.guest,
                self.authorization.guest_uid(),
                self.authorization.guest_generation(),
                self.operation,
            ))
            .map_err(|_| provider_effects::ProviderEffectError::EffectRejected)?;
        }
        let mut response = applied_response(
            "guest lifecycle",
            format!(
                "{} {}: controller-owned VMM Process lifecycle applied",
                self.guest.to_canonical_string(),
                self.operation.as_str()
            ),
        );
        if !self.wait_for_ready {
            response
                .as_object_mut()
                .expect("mutating response is an object")
                .insert("apiReady".to_owned(), Value::String("pending".to_owned()));
        }
        Ok(response)
    }
}

struct DaemonProviderLifecycleEffect<'a> {
    state: &'a ServerState,
    request: public_wire::VmLifecycleRequest,
    caller_role: BrokerCallerRole,
    term_timeout: Duration,
    kill_timeout: Duration,
    operation: provider_effects::GuestLifecycleOperation,
    authorization: provider_effects::LifecycleAuthorization,
}

impl provider_effects::ProviderLifecycleEffectPort for DaemonProviderLifecycleEffect<'_> {
    type Output = Value;

    fn actual_state(
        &self,
        _request: &provider_effects::GuestLifecycleRequest,
    ) -> Result<provider_effects::GuestLifecycleState, provider_effects::ProviderEffectError> {
        self.state
            .pidfd_table
            .prune_dead_entries()
            .map_err(|_| provider_effects::ProviderEffectError::StateUnavailable)?;
        let manifest_entry = manifest_entry_for_vm(self.state, &self.request.vm)
            .ok_or(provider_effects::ProviderEffectError::StateUnavailable)?;
        let processes = load_json::<ProcessesJson>(&self.state.config.artifacts.processes_path)
            .map_err(|_| provider_effects::ProviderEffectError::StateUnavailable)?;
        let process_vm = processes
            .vms
            .iter()
            .find(|entry| entry.vm == self.request.vm);
        let lifecycle =
            public_vm_lifecycle(self.state, &self.request.vm, &manifest_entry, process_vm);
        let lifecycle_state = lifecycle
            .get("state")
            .and_then(Value::as_str)
            .ok_or(provider_effects::ProviderEffectError::StateUnavailable)?;
        match lifecycle_state {
            "Running" => Ok(provider_effects::GuestLifecycleState::Started),
            "Stopped" => Ok(provider_effects::GuestLifecycleState::Stopped),
            _ => Err(provider_effects::ProviderEffectError::StateUnavailable),
        }
    }

    fn apply(
        &self,
        _request: &provider_effects::GuestLifecycleRequest,
    ) -> Result<Self::Output, provider_effects::ProviderEffectError> {
        consume_lifecycle_lease(
            self.state,
            &self.authorization,
            self.operation,
            &self.caller_role,
        )?;
        let result = match self.operation {
            provider_effects::GuestLifecycleOperation::Start => dispatch_broker_vm_start_inner(
                self.state,
                self.request.clone(),
                self.caller_role.clone(),
                Some(&self.authorization),
            ),
            provider_effects::GuestLifecycleOperation::Stop => {
                dispatch_broker_vm_stop_with_timeout_as_inner(
                    self.state,
                    self.request.clone(),
                    self.caller_role.clone(),
                    self.term_timeout,
                    self.kill_timeout,
                )
            }
            provider_effects::GuestLifecycleOperation::Restart => {
                let stop = dispatch_broker_vm_stop_with_timeout_as_inner(
                    self.state,
                    self.request.clone(),
                    self.caller_role.clone(),
                    self.term_timeout,
                    self.kill_timeout,
                );
                match stop {
                    Ok(response) if response_outcome(&response) == Some("applied") => {
                        dispatch_broker_vm_start_inner(
                            self.state,
                            self.request.clone(),
                            self.caller_role.clone(),
                            Some(&self.authorization),
                        )
                    }
                    Ok(response) => Ok(response),
                    Err(error) => Err(error),
                }
            }
        };
        match result {
            Ok(response) if response_outcome(&response) == Some("applied") => Ok(response),
            Ok(_) | Err(_) => Err(provider_effects::ProviderEffectError::EffectRejected),
        }
    }
}

pub(crate) fn consume_lifecycle_lease(
    state: &ServerState,
    authorization: &provider_effects::LifecycleAuthorization,
    operation: provider_effects::GuestLifecycleOperation,
    caller_role: &BrokerCallerRole,
) -> Result<(), provider_effects::ProviderEffectError> {
    let operation = match operation {
        provider_effects::GuestLifecycleOperation::Start => {
            d2b_contracts_broker::broker_wire::LifecycleLeaseOperation::Start
        }
        provider_effects::GuestLifecycleOperation::Stop => {
            d2b_contracts_broker::broker_wire::LifecycleLeaseOperation::Stop
        }
        provider_effects::GuestLifecycleOperation::Restart => {
            d2b_contracts_broker::broker_wire::LifecycleLeaseOperation::Restart
        }
    };
    let response = dispatch_broker_request_as(
        state,
        BrokerRequest::ConsumeLifecycleLease(
            d2b_contracts_broker::broker_wire::ConsumeLifecycleLeaseRequest {
                zone_uid: authorization.zone_uid().clone(),
                guest_uid: authorization.guest_uid().clone(),
                guest_generation: authorization.guest_generation().get(),
                provider_assignment_generation: authorization
                    .provider_assignment_generation()
                    .get(),
                policy_revision: authorization.policy_revision(),
                operation_id: authorization.operation_id().to_owned(),
                operation,
                stop_only: authorization.is_stop_only(),
            },
        ),
        caller_role.clone(),
    )
    .map_err(|_| provider_effects::ProviderEffectError::EffectRejected)?;
    match response {
        BrokerResponse::ConsumeLifecycleLease(response) if response.consumed => Ok(()),
        _ => Err(provider_effects::ProviderEffectError::EffectRejected),
    }
}

fn next_provider_lifecycle_operation_id(
    operation: &str,
    request: &public_wire::VmLifecycleRequest,
) -> String {
    let fingerprint = format!(
        "force={};no_wait_api={};dry_run={};apply={};json={}",
        request.force,
        request.no_wait_api,
        request.flags.dry_run,
        request.flags.apply,
        request.flags.json
    );
    provider_registry::next_lifecycle_operation_id(operation, &request.vm, &fingerprint)
}

fn provider_lifecycle_authorization(
    state: &ServerState,
    guest: &str,
    caller_role: &BrokerCallerRole,
    operation_id: &str,
) -> Result<provider_effects::LifecycleAuthorization, TypedError> {
    let target =
        ResourceRef::parse(&format!("Guest/{guest}")).map_err(|_| TypedError::InternalConfig {
            detail: "Guest lifecycle target is invalid".to_owned(),
        })?;
    let zone =
        d2bd_runtime::zone_authority::authoritative_zone_for_vm(&state.zone_coordinator, guest)
            .map_err(|_| TypedError::InternalConfig {
                detail: "Guest lifecycle Zone identity is unavailable".to_owned(),
            })?;
    let plane = state
        .resource_plane
        .lock()
        .map_err(|_| TypedError::InternalConfig {
            detail: "Guest lifecycle resource plane is unavailable".to_owned(),
        })?
        .clone();
    let runtime = plane.as_ref().and_then(|plane| plane.zone(&zone).ok());
    let Some(runtime) = runtime else {
        #[cfg(test)]
        {
            if matches!(caller_role, BrokerCallerRole::HostShutdownUid { .. }) {
                return provider_effects::LifecycleAuthorization::host_shutdown(
                    ResourceUid::parse("11111111-1111-4111-8111-111111111111").expect("Zone UID"),
                    target,
                    ResourceUid::parse("22222222-2222-4222-8222-222222222222").expect("Guest UID"),
                    ResourceGeneration::new(1).expect("Guest generation"),
                    ResourceGeneration::new(1).expect("Provider assignment generation"),
                    1,
                    operation_id.to_owned(),
                )
                .map_err(|_| TypedError::InternalConfig {
                    detail: "Host shutdown lifecycle lease is invalid".to_owned(),
                });
            }
            return Ok(provider_effects::LifecycleAuthorization::for_test(
                "11111111-1111-4111-8111-111111111111",
                "22222222-2222-4222-8222-222222222222",
                1,
                1,
                1,
                operation_id,
            ));
        }
        #[cfg(not(test))]
        {
            return Err(TypedError::InternalConfig {
                detail: "Guest lifecycle resource runtime is unavailable".to_owned(),
            });
        }
    };
    if matches!(caller_role, BrokerCallerRole::RootUid { .. }) {
        let admission =
            block_on_future(runtime.admit_internal_guest_lifecycle(target.clone(), operation_id))
                .map_err(|_| TypedError::InternalConfig {
                detail: "internal Guest lifecycle authorization is unavailable".to_owned(),
            })?;
        return provider_effects::LifecycleAuthorization::from_lease(
            admission.lease,
            target,
            admission.guest_uid,
            admission.guest_generation,
            admission.provider_assignment_generation,
        )
        .map_err(|_| TypedError::InternalConfig {
            detail: "internal Guest lifecycle authorization lease is invalid".to_owned(),
        });
    }
    let (zone_uid, guest_uid, guest_generation, provider_generation) =
        block_on_future(runtime.guest_lifecycle_identity(&target)).map_err(|_| {
            TypedError::InternalConfig {
                detail: "Guest lifecycle identity is unavailable".to_owned(),
            }
        })?;
    if matches!(caller_role, BrokerCallerRole::HostShutdownUid { .. }) {
        return provider_effects::LifecycleAuthorization::host_shutdown(
            zone_uid,
            target,
            guest_uid,
            guest_generation,
            provider_generation,
            runtime.committed_policy_snapshot().policy_revision,
            operation_id.to_owned(),
        )
        .map_err(|_| TypedError::InternalConfig {
            detail: "Host shutdown lifecycle lease is invalid".to_owned(),
        });
    }
    let admission = block_on_future(runtime.admit_guest_lifecycle(
        broker_caller_uid(caller_role),
        target,
        operation_id,
    ))
    .map_err(|_| TypedError::InternalConfig {
        detail: "Guest lifecycle authorization is unavailable".to_owned(),
    })?;
    provider_effects::LifecycleAuthorization::from_lease(
        admission.lease,
        ResourceRef::parse(&format!("Guest/{guest}")).map_err(|_| TypedError::InternalConfig {
            detail: "Guest lifecycle target is invalid".to_owned(),
        })?,
        admission.guest_uid,
        admission.guest_generation,
        admission.provider_assignment_generation,
    )
    .map_err(|_| TypedError::InternalConfig {
        detail: "Guest lifecycle authorization lease is invalid".to_owned(),
    })
}

fn provider_lifecycle_failure_response(
    verb: &str,
    guest: &str,
    error: provider_effects::ProviderEffectError,
) -> Value {
    let remediation = match error {
        provider_effects::ProviderEffectError::MutationPending => {
            "Retry after the in-progress Provider lifecycle request completes.".to_owned()
        }
        provider_effects::ProviderEffectError::StateUnavailable => {
            "Retry after d2bd lifecycle state becomes available.".to_owned()
        }
        _ => "Admin: rebuild the trusted Provider catalog and retry the lifecycle operation."
            .to_owned(),
    };
    broker_failure_response(
        verb,
        format!(
            "Provider lifecycle dispatch for {guest} refused ({})",
            error.code()
        ),
        remediation,
        None,
    )
}

fn dispatch_broker_vm_start_inner(
    state: &ServerState,
    request: public_wire::VmLifecycleRequest,
    caller_role: BrokerCallerRole,
    lifecycle_authorization: Option<&provider_effects::LifecycleAuthorization>,
) -> Result<Value, TypedError> {
    const VERB: &str = "vm start";

    let resolver = load_bundle_resolver(state)?;

    // Build the host-prep DAG for this VM and (optionally) execute it
    // before driving the per-VM process DAG. The DAG is logged
    // unconditionally so operators and gates can observe the planned step
    // set; actual broker dispatch is gated on
    // `D2B_HOST_PREP_DAG_EXECUTE=1`. All step kinds dispatch a real
    // broker op (or a daemon-native check) - `OwnershipMatrixCheck` and
    // `SshHostKeyPreflight` still cover the two stubs that intentionally
    // remain typed-Unimplemented at the broker layer pending sibling
    // handlers.
    let host_prep_steps =
        d2b_host::host_prep_dag::build_host_prep_dag(request.vm.as_str(), &resolver);
    log_host_prep_dag(&request.vm, &host_prep_steps);
    if std::env::var("D2B_HOST_PREP_DAG_EXECUTE")
        .map(|v| v == "1")
        .unwrap_or(false)
        && let Err(response) =
            execute_host_prep_dag(state, &request.vm, &host_prep_steps, caller_role.clone())
    {
        return Ok(response);
    }

    let dag = resolver
        .processes
        .vms
        .iter()
        .find(|dag| dag.vm == request.vm)
        .ok_or_else(|| TypedError::InternalIo {
            context: format!("load process DAG for {}", request.vm),
            detail: "VM not present in processes.json".to_owned(),
        })?;

    let runner = VmStartRunner {
        state,
        resolver: &resolver,
        caller_role: caller_role.clone(),
        lifecycle_authorization: lifecycle_authorization.cloned(),
        workload_identity: dag.workload_identity.clone(),
        network_tap_context: network_tap_context_for_vm(state, &resolver, request.vm.as_str()),
    };

    // StoreSync owns the guest-served live marker
    // (`store-view/live/.d2b-marker-<vm>`) and postures it as
    // `d2bd:users 0644`. Run it before ownership preflight so stale
    // markers from older broker/activation paths are repaired before the
    // fail-closed matrix check. The process DAG still contains the
    // StoreVirtiofsPreflight readiness node; that second StoreSync call is
    // idempotent and keeps the DAG contract explicit.
    if vm_supports_store_sync(&resolver, &request.vm)
        && let Err(error) = runner.sync_store_view(&request.vm)
    {
        tracing::warn!(
            vm = %request.vm,
            error = %error,
            "vm start: pre-ownership StoreSync failed"
        );
        return Ok(daemon_failure_response(
            VERB,
            format!(
                "vm start {}: store-view sync failed before ownership preflight",
                request.vm
            ),
        ));
    }

    // Refuse VM start if any per-VM state subdirectory has drifted from
    // the typed ownership matrix
    // declared in nixos-modules/options-ownership-matrix.nix. Missing
    // subdirectories surface as warn-only (state is materialized
    // lazily); owner/group/mode drift on existing paths fails closed.
    if let Some(manifest_entry) = resolver.manifest.vms.get(&request.vm)
        && vm_requires_nixos_state_preflights(manifest_entry)
    {
        let state_dir = std::path::PathBuf::from(&manifest_entry.state_dir);
        if let d2bd_runtime::ownership_preflight::OwnershipPreflightOutcome::Drift(drift) =
            d2bd_runtime::ownership_preflight::preflight(&request.vm, &state_dir)
        {
            let path = drift[0].path().to_path_buf();
            let drift_reason =
                d2bd_runtime::ownership_preflight::render_drift_message(&request.vm, &drift);
            tracing::warn!(
                vm = %request.vm,
                path = %path.display(),
                drift_count = drift.len(),
                "vm start refused: ownership-matrix drift",
            );
            return Ok(TypedError::OwnershipMatrixDrift {
                vm: request.vm.clone(),
                path,
                drift_reason,
            }
            .to_envelope_value());
        }

        // Refuse VM start if the per-VM sshd host keys directory or any
        // `ssh_host_*_key`
        // leaf has drifted from the canonical posture (regular file,
        // root:root, 0o0400; no symlinks). The directory's own
        // ownership/mode are enforced by the ownership-matrix
        // preflight above; this preflight is fail-closed once the
        // directory exists.
        let keys_dir = state_dir.join("sshd-host-keys");
        if keys_dir.exists() {
            if let Err(drift) =
                d2bd_runtime::ssh_host_key_preflight::check_sshd_host_keys(&request.vm, &keys_dir)
            {
                let path = drift.path().to_path_buf();
                let drift_reason = drift.reason();
                tracing::warn!(
                    vm = %request.vm,
                    path = %path.display(),
                    "vm start refused: sshd-host-key drift",
                );
                return Ok(TypedError::SshdHostKeyDrift {
                    vm: request.vm.clone(),
                    path,
                    drift: drift_reason,
                }
                .to_envelope_value());
            }
        } else {
            tracing::warn!(
                vm = %request.vm,
                path = %keys_dir.display(),
                "ssh-host-key-preflight: keys directory absent; skipping (will be materialized on first run)",
            );
        }
    }

    let tracked_roles = dag
        .nodes
        .iter()
        .filter(|node| !is_guest_owned_process_node(node))
        .filter(|node| !is_durable_wayland_process_node(node))
        .filter_map(|node| match vm_start_node_mode(&node.role) {
            VmStartNodeMode::LongLived(_) => Some(tracked_role_id(node)),
            _ => None,
        })
        .collect::<Vec<_>>();
    let _vm_start_lock = acquire_vm_start_lock(state, &request.vm)?;
    if let Err(error) = reconcile_display_before_vm_start(state, &request.vm, dag) {
        tracing::warn!(
            vm = %request.vm,
            error = %error,
            "vm start: committed display reconciliation failed before DAG execution",
        );
        return Ok(daemon_failure_response(
            VERB,
            format!(
                "vm start {}: committed WaylandSession display reconciliation failed ({error})",
                request.vm
            ),
        ));
    }
    // v1.1.1fu14 B3 + B7: prune entries whose backing process
    // has died (or whose PID has been reused) BEFORE checking
    // for existing registrations. This handles the
    // operator-observed pattern where a daemon crash leaves a
    // pidfd-table.json with entries pointing at PIDs that were
    // since killed; without pruning, the daemon refuses every
    // subsequent vm start with "already has a registered
    // supervisor pidfd" even though no process exists.
    match state.pidfd_table.prune_dead_entries() {
        Ok(n) if n > 0 => {
            tracing::info!(
                vm = %request.vm,
                dropped = n,
                "vm start: pruned stale pidfd-table entries before duplicate check",
            );
        }
        Ok(_) => {}
        Err(err) => {
            tracing::warn!(
                vm = %request.vm,
                error = ?err,
                "vm start: pidfd-table prune failed; proceeding with stale entries",
            );
        }
    }
    match cleanup_stale_qemu_media_dependencies_before_start(
        state,
        &request.vm,
        &tracked_roles,
        caller_role.clone(),
    ) {
        Ok(n) if n > 0 => {
            tracing::info!(
                vm = %request.vm,
                stopped = n,
                "vm start: stopped stale qemu-media dependency runners before duplicate check",
            );
        }
        Ok(_) => {}
        Err(response) => return Ok(response),
    }
    if let Some(existing_role_id) = tracked_roles
        .iter()
        .find(|role_id| state.pidfd_table.contains(&request.vm, role_id))
    {
        let runner_role_id = vm_start_primary_runner_role_id(&tracked_roles);
        if let Some(response) =
            existing_vm_start_response_if_ready(state, &request.vm, runner_role_id)
        {
            let mut response = response;
            if usbip_start_reconciles_synchronously(&request) {
                if let Some(usb_report) = reconcile_usbip_after_vm_start_until_converged(
                    state,
                    &resolver,
                    &request.vm,
                    caller_role.clone(),
                    USBIP_STRICT_RECONCILE_TIMEOUT,
                    USBIP_STRICT_RECONCILE_BACKOFF,
                ) {
                    if usb_report.fatal() {
                        let summary = usbip_lifecycle_report_summary("start", &usb_report)
                            .unwrap_or_else(|| {
                                format!(
                                    "USBIP reconciliation for already-running VM '{}' failed before device exposure",
                                    request.vm
                                )
                            });
                        let fatal = usb_report.first_fatal_reason();
                        return Ok(broker_failure_response(
                            VERB,
                            summary,
                            fatal
                                .map(|reason| reason.remediation.clone())
                                .unwrap_or_else(|| {
                                    format!(
                                        "Fix USBIP policy or host-session claim state for VM '{}', then retry `d2b vm start {} --apply`.",
                                        request.vm, request.vm
                                    )
                                }),
                            None,
                        ));
                    }
                    if let Some(usb_summary) = usbip_lifecycle_report_summary("start", &usb_report)
                    {
                        append_response_summary(&mut response, &usb_summary);
                    }
                }
            } else {
                let scheduled = spawn_usbip_reconcile_after_vm_start(
                    state,
                    &resolver,
                    &request.vm,
                    runner_role_id,
                    caller_role.clone(),
                );
                match scheduled {
                    UsbipBackgroundReconcileSpawn::Spawned => append_response_summary(
                        &mut response,
                        "USBIP reconciliation scheduled in background",
                    ),
                    UsbipBackgroundReconcileSpawn::AlreadyRunning => append_response_summary(
                        &mut response,
                        "USBIP background reconciliation already running",
                    ),
                    UsbipBackgroundReconcileSpawn::NoClaims => {}
                }
            }
            return Ok(response);
        }
        return Ok(invalid_request_response(
            VERB,
            format!(
                "vm '{}' already has a registered supervisor pidfd ({})",
                request.vm, existing_role_id
            ),
        ));
    }

    let api_timeout = Duration::from_secs(
        std::env::var("D2B_API_TIMEOUT_SECONDS")
            .ok()
            .and_then(|value| value.parse::<u64>().ok())
            .unwrap_or(d2bd_runtime::supervisor::dag::DEFAULT_API_TIMEOUT_SECONDS),
    );
    let readiness_timeout = Duration::from_secs(
        std::env::var("D2B_READINESS_TIMEOUT_SECONDS")
            .ok()
            .and_then(|value| value.parse::<u64>().ok())
            .unwrap_or(api_timeout.as_secs().max(300)),
    );
    let split_mode = if request.no_wait_api {
        d2bd_runtime::supervisor::dag::SplitReadinessMode::NoWaitApi
    } else {
        d2bd_runtime::supervisor::dag::SplitReadinessMode::Strict
    };
    let budget = d2bd_runtime::supervisor::dag::NodeBudget {
        readiness: readiness_timeout,
        ..d2bd_runtime::supervisor::dag::NodeBudget::default()
    };
    let dag_start = Instant::now();
    let report = match block_on_future(
        d2bd_runtime::supervisor::dag::DagExecutor::with_budget(runner, budget).run_split(
            dag,
            split_mode,
            api_timeout,
        ),
    ) {
        Ok(report) => report,
        Err(error) => {
            tracing::warn!(vm = %request.vm, error = ?error, "vm start DAG validation failed");
            return Ok(daemon_failure_response(
                VERB,
                format!(
                    "vm start {}: daemon could not validate the process DAG",
                    request.vm
                ),
            ));
        }
    };
    log_vm_start_report(&report);
    // Persist the api-ready state for `d2b vm status`.
    if let Some(ref api_ready_state) = report.api_ready {
        let api_ready_value = serde_json::to_value(api_ready_state).unwrap_or_default();
        if let Err(err) = d2bd_runtime::daemon_audit::write_vm_api_ready_state(
            &state.daemon_state_dir,
            &request.vm,
            api_ready_value,
        ) {
            tracing::warn!(
                vm = %request.vm,
                error = %err,
                "vm start: failed to persist api-ready state (non-fatal)",
            );
        }
    }
    if matches!(
        split_mode,
        d2bd_runtime::supervisor::dag::SplitReadinessMode::Strict
    ) && matches!(
        report.api_ready,
        Some(d2bd_runtime::supervisor::dag::ApiReadyState::Timeout)
    ) {
        tracing::warn!(
            vm = %request.vm,
            "vm start: api-ready timeout (api-ready phase did not converge within {} seconds)",
            api_timeout.as_secs()
        );
        // Emit audit-log entry on api-ready timeout.
        if let Err(err) = state.daemon_audit.write_event(
            &d2bd_runtime::daemon_audit::DaemonEvent::ApiReadyTimeout {
                vm: request.vm.clone(),
                runner: VM_RUNNER_ROLE_ID.to_owned(),
                elapsed_secs: api_timeout.as_secs(),
                mode: "strict".to_owned(),
            },
        ) {
            tracing::warn!(
                vm = %request.vm,
                error = %err,
                "vm start: failed to write ApiReadyTimeout audit event (non-fatal)",
            );
        }
        if let Err(response) =
            rollback_failed_vm_start(state, &request.vm, &tracked_roles, caller_role.clone())
        {
            return Ok(response);
        }
        return Ok(api_ready_timeout_response(
            VERB,
            format!("vm.{}: process-alive: ok; api-ready: timeout", request.vm),
        ));
    }
    if report.overall_ok {
        let mut usb_lifecycle_summary = None;
        // Structured degraded annotation for the OtelHostBridge readiness
        // gate: set to the typed-error envelope when the gate times out in
        // non-strict mode so the success response carries machine-readable
        // evidence without requiring log parsing.
        let mut otel_degraded: Option<serde_json::Value> = None;
        if !request.no_wait_api {
            // When the VM that just came up is the observability VM AND
            // observability is
            // enabled in the trusted bundle, block on the
            // OtelHostBridge readiness gate before declaring success.
            // On timeout we fall back to degraded mode (the VM stays
            // up; the response carries a degraded-mode annotation).
            // Strict-mode operators can flip the env var to convert
            // the timeout into a typed `otel-host-bridge-readiness-timeout`
            // refusal envelope (exit code 65). See
            // `docs/reference/otel-host-bridge-readiness.md`.
            let obs_meta = &resolver.manifest.observability;
            if obs_meta.enabled && obs_meta.vm_name == request.vm {
                let cfg =
                    d2bd_runtime::otel_host_bridge_readiness::ReadinessWaitConfig::for_dispatch();
                let source = d2bd_runtime::otel_host_bridge_readiness::PidfdAndSocketProbeSource {
                    pidfd_table: &state.pidfd_table,
                    vm: request.vm.as_str(),
                    runner_role_id: d2b_contracts_broker::broker_wire::RunnerRole::OtelHostBridge
                        .as_str(),
                    vsock_host_socket: std::path::PathBuf::from(
                        obs_meta.obs_vsock_host_socket.as_str(),
                    ),
                    exit_marker: None,
                };
                let outcome =
                    d2bd_runtime::otel_host_bridge_readiness::await_otel_host_bridge_readiness(
                        request.vm.as_str(),
                        &source,
                        &cfg,
                        std::thread::sleep,
                        std::time::Instant::now(),
                    );
                if let d2bd_runtime::otel_host_bridge_readiness::ReadinessWaitOutcome::DegradedTimeout {
                    vm,
                    elapsed_ms,
                    reason,
                } = &outcome
                {
                    if cfg.strict {
                        return Ok(TypedError::OtelHostBridgeReadinessTimeout {
                            vm: vm.clone(),
                            elapsed_ms: *elapsed_ms,
                        }
                        .to_envelope_value());
                    }
                    tracing::warn!(
                        vm = %vm,
                        elapsed_ms,
                        reason = %reason,
                        "vm start succeeded in degraded-mode: otel-host-bridge readiness gate did not close",
                    );
                    otel_degraded = Some(
                        TypedError::OtelHostBridgeReadinessTimeout {
                            vm: vm.clone(),
                            elapsed_ms: *elapsed_ms,
                        }
                        .to_envelope_value(),
                    );
                }
            }
            // Post-readiness trigger. Once the per-VM DAG reports
            // overall_ok the guest is up, so it is safe to pin the host
            // pubkey into `/var/lib/d2b/known_hosts.d2b` via the
            // broker for the retained SSH-compat path. Failures here are
            // warn-only - matching the legacy
            // `d2b-known-hosts-refresh@<vm>.service` behaviour, which
            // left the old pin in place rather than failing the VM start.
            let outcome = d2bd_runtime::known_hosts_refresh::refresh_known_hosts(
                &request.vm,
                &resolver.manifest,
                &DaemonRotateKnownHostBroker { state },
            );
            match &outcome {
                d2bd_runtime::known_hosts_refresh::RefreshOutcome::Skipped { vm, reason } => {
                    tracing::info!(
                        vm = %vm,
                        reason = reason.as_str(),
                        "known-hosts refresh skipped",
                    )
                }
                d2bd_runtime::known_hosts_refresh::RefreshOutcome::Rotated { vm, response } => {
                    tracing::info!(
                        vm = %vm,
                        static_ip = %response.static_ip,
                        known_hosts_path = %response.known_hosts_path,
                        rewrote = response.removed,
                        "known-hosts refresh applied",
                    )
                }
                d2bd_runtime::known_hosts_refresh::RefreshOutcome::Failed { vm, detail } => {
                    tracing::warn!(
                        vm = %vm,
                        detail = %detail,
                        "known-hosts refresh failed (non-fatal, retained prior pin)",
                    )
                }
            }
            if usbip_start_reconciles_synchronously(&request)
                && let Some(usb_report) = reconcile_usbip_after_vm_start_until_converged(
                    state,
                    &resolver,
                    &request.vm,
                    caller_role.clone(),
                    USBIP_STRICT_RECONCILE_TIMEOUT,
                    USBIP_STRICT_RECONCILE_BACKOFF,
                )
            {
                if usb_report.fatal() {
                    let fatal = usb_report.first_fatal_reason();
                    let summary = usbip_lifecycle_report_summary("start", &usb_report)
                        .unwrap_or_else(|| {
                            format!(
                                "USBIP reconciliation for VM '{}' failed before device exposure",
                                request.vm
                            )
                        });
                    if let Err(response) = rollback_failed_vm_start(
                        state,
                        &request.vm,
                        &tracked_roles,
                        caller_role.clone(),
                    ) {
                        return Ok(response);
                    }
                    return Ok(broker_failure_response(
                        VERB,
                        summary,
                        fatal
                            .map(|reason| reason.remediation.clone())
                            .unwrap_or_else(|| {
                                format!(
                                    "Fix USBIP policy or host-session claim state for VM '{}', then retry `d2b vm start {} --apply`.",
                                    request.vm, request.vm
                                )
                            }),
                        None,
                    ));
                }
                usb_lifecycle_summary = usbip_lifecycle_report_summary("start", &usb_report);
            }
        }
        let mut summary = if request.no_wait_api {
            format!("vm.{}: process-alive: ok; api-ready: pending", request.vm)
        } else {
            vm_start_success_summary(&report)
        };
        if let Some(usb_summary) = usb_lifecycle_summary {
            summary.push_str("; ");
            summary.push_str(&usb_summary);
        } else if !usbip_start_reconciles_synchronously(&request) {
            match spawn_usbip_reconcile_after_vm_start(
                state,
                &resolver,
                &request.vm,
                vm_start_primary_runner_role_id(&tracked_roles),
                caller_role.clone(),
            ) {
                UsbipBackgroundReconcileSpawn::Spawned => {
                    summary.push_str("; USBIP reconciliation scheduled in background");
                }
                UsbipBackgroundReconcileSpawn::AlreadyRunning => {
                    summary.push_str("; USBIP background reconciliation already running");
                }
                UsbipBackgroundReconcileSpawn::NoClaims => {}
            }
        }
        let mut response = applied_response(VERB, summary);
        if request.no_wait_api {
            response.as_object_mut().unwrap().insert(
                "apiReady".to_owned(),
                serde_json::Value::String("pending".to_owned()),
            );
        }
        if let Some(degraded) = otel_degraded {
            response
                .as_object_mut()
                .unwrap()
                .insert("degraded".to_owned(), degraded);
        }
        return Ok(response);
    }
    // Detect the runner-exited / runner-reused fast-fail BEFORE rollback
    // tears the runner down, so we can peek the buffered broker exit
    // status and emit a bounded audit event + an actionable, swtpm-aware
    // failure envelope (broker-error exit contract, not exit 1).
    let runner_exit = detect_runner_exit_failure(&report, dag);
    let runner_exit_response = runner_exit.map(|(role_id, reason_kind)| {
        let exit_status = state
            .broker_reap_log
            .peek_for(&request.vm, &role_id)
            .map(|notif| notif.exit_status);
        let elapsed_ms = u64::try_from(dag_start.elapsed().as_millis()).unwrap_or(u64::MAX);
        emit_vm_start_runner_exited_audit(
            state,
            &request.vm,
            &role_id,
            reason_kind,
            exit_status.as_ref(),
            elapsed_ms,
        );
        vm_start_runner_exited_response(&request.vm, &role_id, reason_kind, exit_status.as_ref())
    });
    if let Err(response) =
        rollback_failed_vm_start(state, &request.vm, &tracked_roles, caller_role.clone())
    {
        return Ok(response);
    }
    if let Some(response) = runner_exit_response {
        return Ok(response);
    }
    Ok(vm_start_failure_response(&report))
}

/// Scan the DAG run report for the first node that fast-failed because
/// its spawned runner exited (or its PID was reused) before readiness.
/// Returns the runner's tracked `role_id` and the closed reason kind.
fn detect_runner_exit_failure(
    report: &d2bd_runtime::supervisor::dag::DagRunReport,
    dag: &d2b_core::processes::VmProcessDag,
) -> Option<(String, d2bd_runtime::daemon_audit::VmStartRunnerExitReason)> {
    for entry in &report.history {
        let d2bd_runtime::supervisor::dag::NodeOutcome::Failed { reason } = &entry.outcome else {
            continue;
        };
        let (reason_kind, marker) = if reason.contains("runner-exited:") {
            (
                d2bd_runtime::daemon_audit::VmStartRunnerExitReason::RunnerExited,
                "runner-exited:",
            )
        } else if reason.contains("runner-reused:") {
            (
                d2bd_runtime::daemon_audit::VmStartRunnerExitReason::RunnerReused,
                "runner-reused:",
            )
        } else {
            continue;
        };
        let node_id = reason.rsplit(marker).next().unwrap_or("").trim();
        let role_id = dag
            .nodes
            .iter()
            .find(|node| node.id.0 == node_id)
            .map(tracked_role_id)
            .unwrap_or_else(|| node_id.to_owned());
        return Some((role_id, reason_kind));
    }
    None
}

/// Bounded, closed-vocabulary cause phrase for a runner exit. Carries no
/// path, pid, or free-form node-reason text.
fn bounded_runner_exit_cause(
    reason_kind: d2bd_runtime::daemon_audit::VmStartRunnerExitReason,
    status: Option<&d2b_contracts_broker::broker_wire::ChildExitStatus>,
) -> String {
    use d2b_contracts_broker::broker_wire::ChildExitKind;
    if matches!(
        reason_kind,
        d2bd_runtime::daemon_audit::VmStartRunnerExitReason::RunnerReused
    ) {
        return "PID reused by another process".to_owned();
    }
    match status {
        Some(status) => match status.kind {
            ChildExitKind::Exited => match status.code {
                Some(code) => format!("exit code {code}"),
                None => "exited".to_owned(),
            },
            ChildExitKind::Signaled => match status.signal {
                Some(signal) => format!("terminated by signal {signal}"),
                None => "terminated by signal".to_owned(),
            },
            ChildExitKind::Killed => match status.signal {
                Some(signal) => format!("killed by signal {signal}"),
                None => "killed".to_owned(),
            },
        },
        None => "exited before readiness".to_owned(),
    }
}

/// Build the actionable, swtpm-aware failure envelope for a runner-exited
/// fast-fail. Maps to the broker-error outcome (the broker-error exit
/// contract), NOT exit 1.
fn vm_start_runner_exited_response(
    vm: &str,
    role_id: &str,
    reason_kind: d2bd_runtime::daemon_audit::VmStartRunnerExitReason,
    status: Option<&d2b_contracts_broker::broker_wire::ChildExitStatus>,
) -> Value {
    let cause = bounded_runner_exit_cause(reason_kind, status);
    let verb_word = match reason_kind {
        d2bd_runtime::daemon_audit::VmStartRunnerExitReason::RunnerExited => "exited",
        d2bd_runtime::daemon_audit::VmStartRunnerExitReason::RunnerReused => {
            "was replaced (PID reused)"
        }
    };
    let summary =
        format!("vm start {vm}: runner '{role_id}' {verb_word} before readiness ({cause})");
    let remediation = format!(
        "The '{role_id}' runner {verb_word} before its readiness signal fired ({cause}). \
         If this is the swtpm (per-VM TPM) runner, the TPM state must not be wiped: \
         clearing /var/lib/d2b/vms/{vm}/swtpm looks like device tampering to your \
         identity provider and forces re-enrollment. Admin: inspect \
         `journalctl -u d2bd` and `journalctl -u d2b-broker` for the \
         swtpm exit detail before retrying `d2b vm up {vm}`."
    );
    broker_failure_response("vm start", summary, remediation, None)
}

/// Emit the bounded `VmStartRunnerExited` daemon audit event. Best-effort:
/// an audit write failure is logged but never aborts the vm-start path.
fn emit_vm_start_runner_exited_audit(
    state: &ServerState,
    vm: &str,
    role_id: &str,
    reason_kind: d2bd_runtime::daemon_audit::VmStartRunnerExitReason,
    status: Option<&d2b_contracts_broker::broker_wire::ChildExitStatus>,
    elapsed_ms: u64,
) {
    use d2b_contracts_broker::broker_wire::ChildExitKind;
    let exit_kind = status.map(|status| match status.kind {
        ChildExitKind::Exited => d2bd_runtime::daemon_audit::RunnerExitKind::Exited,
        ChildExitKind::Signaled => d2bd_runtime::daemon_audit::RunnerExitKind::Signaled,
        ChildExitKind::Killed => d2bd_runtime::daemon_audit::RunnerExitKind::Killed,
    });
    let event = d2bd_runtime::daemon_audit::DaemonEvent::VmStartRunnerExited {
        vm: vm.to_owned(),
        role_id: role_id.to_owned(),
        reason_kind,
        exit_kind,
        exit_code: status.and_then(|status| status.code),
        exit_signal: status.and_then(|status| status.signal),
        elapsed_ms,
    };
    if let Err(error) = state.daemon_audit.write_event(&event) {
        tracing::warn!(
            vm = %vm,
            role_id = %role_id,
            error = %error,
            "vm start: failed to write VmStartRunnerExited audit event (non-fatal)",
        );
    }
}

/// Production implementation of
/// [`d2bd_runtime::known_hosts_refresh::RotateKnownHostBroker`] used by the
/// post-readiness hook in `dispatch_broker_vm_start`. Tests use a
/// fake recorder (see the module's `#[cfg(test)]` block).
struct DaemonRotateKnownHostBroker<'a> {
    state: &'a ServerState,
}

impl d2bd_runtime::known_hosts_refresh::RotateKnownHostBroker for DaemonRotateKnownHostBroker<'_> {
    fn rotate(
        &self,
        request: d2b_contracts_broker::broker_wire::RunRotateKnownHostRequest,
    ) -> Result<d2b_contracts_broker::broker_wire::RunRotateKnownHostResponse, TypedError> {
        match dispatch_broker_request(self.state, BrokerRequest::RunRotateKnownHost(request))? {
            BrokerResponse::RunRotateKnownHost(response) => Ok(response),
            BrokerResponse::Error(error) => Err(TypedError::InternalBrokerUnavailable {
                path: broker_socket_path(self.state),
                detail: format!(
                    "RunRotateKnownHost broker error: kind={} message={}",
                    error.kind, error.message
                ),
            }),
            other => Err(TypedError::InternalBrokerUnavailable {
                path: broker_socket_path(self.state),
                detail: format!(
                    "RunRotateKnownHost: unexpected broker response kind {}",
                    broker_response_kind(&other)
                ),
            }),
        }
    }
}

#[cfg(test)]
fn dispatch_broker_vm_stop(
    state: &ServerState,
    request: public_wire::VmLifecycleRequest,
) -> Result<Value, TypedError> {
    dispatch_broker_vm_stop_with_timeout_as_inner(
        state,
        request,
        BrokerCallerRole::LauncherUid { uid: 0 },
        VM_STOP_TIMEOUT,
        VM_STOP_TIMEOUT,
    )
}

fn dispatch_broker_vm_stop_as(
    state: &ServerState,
    request: public_wire::VmLifecycleRequest,
    caller_role: BrokerCallerRole,
) -> Result<Value, TypedError> {
    dispatch_broker_vm_stop_with_timeout_as(
        state,
        request,
        caller_role,
        VM_STOP_TIMEOUT,
        VM_STOP_TIMEOUT,
    )
}

#[cfg(test)]
fn dispatch_broker_vm_stop_with_timeout(
    state: &ServerState,
    request: public_wire::VmLifecycleRequest,
    term_timeout: Duration,
    kill_timeout: Duration,
) -> Result<Value, TypedError> {
    dispatch_broker_vm_stop_with_timeout_as_inner(
        state,
        request,
        BrokerCallerRole::LauncherUid { uid: 0 },
        term_timeout,
        kill_timeout,
    )
}

fn dispatch_broker_vm_stop_with_timeout_as(
    state: &ServerState,
    request: public_wire::VmLifecycleRequest,
    caller_role: BrokerCallerRole,
    term_timeout: Duration,
    kill_timeout: Duration,
) -> Result<Value, TypedError> {
    const VERB: &str = "vm stop";

    if let Some(response) = mutating_verb_preflight(VERB, &request.flags, Some(request.vm.as_str()))
    {
        return Ok(response);
    }

    // The state-persistence support binary intentionally exercises pidfd
    // cleanup without requiring a host Provider bundle or live resource
    // plane. Production builds keep the fail-closed Provider path below.
    #[cfg(feature = "test-support")]
    if state.provider_runtime.process_providers().is_none() {
        return dispatch_broker_vm_stop_with_timeout_as_inner(
            state,
            request,
            caller_role,
            term_timeout,
            kill_timeout,
        );
    }

    let operation_id = next_provider_lifecycle_operation_id("stop", &request);
    let authorization =
        provider_lifecycle_authorization(state, &request.vm, &caller_role, &operation_id)?;
    let effect = DaemonProviderLifecycleEffect {
        state,
        request: request.clone(),
        caller_role: caller_role.clone(),
        term_timeout,
        kill_timeout,
        operation: provider_effects::GuestLifecycleOperation::Stop,
        authorization: authorization.clone(),
    };
    match state.provider_runtime.dispatch_lifecycle(
        &caller_role,
        &request.vm,
        effect.operation,
        operation_id,
        authorization,
        &effect,
    ) {
        Ok(provider_registry::ProviderRuntimeDispatch::Active(
            provider_effects::EffectDispatch::Dispatched(response),
        )) => Ok(response),
        Ok(provider_registry::ProviderRuntimeDispatch::Active(
            provider_effects::EffectDispatch::Duplicate,
        )) => Ok(applied_response(
            VERB,
            format!(
                "vm stop {}: duplicate Provider lifecycle request",
                request.vm
            ),
        )),
        Err(error) => Ok(provider_lifecycle_failure_response(
            VERB,
            &request.vm,
            error,
        )),
    }
}

fn dispatch_broker_vm_stop_with_timeout_as_inner(
    state: &ServerState,
    request: public_wire::VmLifecycleRequest,
    caller_role: BrokerCallerRole,
    term_timeout: Duration,
    kill_timeout: Duration,
) -> Result<Value, TypedError> {
    const VERB: &str = "vm stop";

    let stop_entries = ordered_vm_stop_entries(state, &request.vm);
    if stop_entries.is_empty() {
        return Ok(invalid_request_response(
            VERB,
            format!("vm '{}' has no registered pidfd_table entries", request.vm),
        ));
    }

    let usb_lifecycle_summary = match load_bundle_resolver(state) {
        Ok(resolver) => {
            cleanup_usbip_before_vm_stop(state, &resolver, &request.vm, caller_role.clone())
                .and_then(|report| usbip_lifecycle_report_summary("stop", &report))
        }
        Err(error) => match probe_usbip_claim_locks_for_vm_without_bundle(state, &request.vm) {
            UsbipClaimLockProbe::None => {
                tracing::warn!(
                    vm = %request.vm,
                    error = ?error,
                    "vm stop: USBIP carrier cleanup skipped because bundle resolver could not load and no host-session claim locks matched the VM"
                );
                None
            }
            UsbipClaimLockProbe::Present => {
                tracing::warn!(
                    vm = %request.vm,
                    error = ?error,
                    "vm stop: USBIP carrier cleanup degraded because bundle resolver could not load while a host-session claim lock matched the VM"
                );
                Some(format!(
                    "USBIP cleanup degraded: could not load trusted bundle; host-session claims were left unchanged ({error:?})"
                ))
            }
            UsbipClaimLockProbe::Unknown(detail) => {
                tracing::warn!(
                    vm = %request.vm,
                    error = ?error,
                    detail = %detail,
                    "vm stop: USBIP carrier cleanup degraded because bundle resolver and host-session claim lock probing failed"
                );
                Some(format!(
                    "USBIP cleanup degraded: could not load trusted bundle or inspect host-session claims; claims may be left unchanged ({error:?}; {detail})"
                ))
            }
        },
    };

    let mut drained_roles = Vec::with_capacity(stop_entries.len());
    let mut sigkill_roles = Vec::new();
    let mut shutdown_outcomes = Vec::new();
    let force_requested = vm_lifecycle_force_requested(&request);
    for entry in &stop_entries {
        let provider_report = stop_vmm_runner_with_provider(
            state,
            ProviderStopInputs {
                caller_role: caller_role.clone(),
                verb: VERB,
                vm: &request.vm,
                role_id: &entry.role,
                stop_entries: &stop_entries,
                term_timeout,
                kill_timeout,
                force_requested,
            },
        );
        let report = match provider_report.unwrap_or_else(|| {
            stop_vm_pidfd_role(
                state,
                caller_role.clone(),
                VERB,
                &request.vm,
                &entry.role,
                term_timeout,
                kill_timeout,
            )
        }) {
            Ok(report) => report,
            Err(response) => {
                state.security_key_sessions.lock().stop_vm(&request.vm);
                return Ok(response);
            }
        };
        drained_roles.push(report.role_id.clone());
        if let Some(outcome) = report.shutdown_outcome {
            shutdown_outcomes.push((report.role_id.clone(), outcome));
        }
        if report.required_sigkill {
            sigkill_roles.push(report.role_id);
        }
    }

    state.security_key_sessions.lock().stop_vm(&request.vm);

    let _mguard = state.pidfd_table.mutation_guard();
    if let Err(error) = state.pidfd_table.snapshot() {
        tracing::warn!(vm = %request.vm, error = ?error, "pidfd_table snapshot failed after draining sidecars");
        return Ok(daemon_failure_response(
            VERB,
            format!(
                "vm stop {}: drained roles but pidfd_table persistence failed ({})",
                request.vm,
                drained_roles.join(", ")
            ),
        ));
    }

    let entry_word = if drained_roles.len() == 1 {
        "entry"
    } else {
        "entries"
    };
    let mut summary = format!(
        "vm stop {}: drained {} pidfd_table {} in reverse DAG order",
        request.vm,
        drained_roles.len(),
        entry_word
    );
    if !sigkill_roles.is_empty() {
        summary.push_str(&format!(
            " after SIGTERM timeout on {}",
            sigkill_roles.join(", ")
        ));
    }
    if !shutdown_outcomes.is_empty() {
        let labels = shutdown_outcomes
            .iter()
            .map(|(role, outcome)| format!("{role}:{}", outcome.label()))
            .collect::<Vec<_>>()
            .join(", ");
        summary.push_str(&format!("; provider shutdown outcomes: {labels}"));
    }
    if let Some(usb_summary) = usb_lifecycle_summary {
        summary.push_str("; ");
        summary.push_str(&usb_summary);
    }
    summary.push_str(&format!(" ({})", drained_roles.join(", ")));
    state
        .console_sessions
        .lock()
        .unwrap()
        .remove_session(&request.vm);
    Ok(applied_response(VERB, summary))
}

#[cfg(test)]
fn dispatch_broker_vm_restart(
    state: &ServerState,
    request: public_wire::VmLifecycleRequest,
) -> Result<Value, TypedError> {
    let stop_response = dispatch_broker_vm_stop_with_timeout_as_inner(
        state,
        request.clone(),
        BrokerCallerRole::LauncherUid { uid: 0 },
        VM_STOP_TIMEOUT,
        VM_STOP_TIMEOUT,
    )?;
    if response_outcome(&stop_response) != Some("applied") {
        return Ok(retarget_mutating_response(&stop_response, "vm restart"));
    }
    let start_response = dispatch_broker_vm_start_inner(
        state,
        request.clone(),
        BrokerCallerRole::LauncherUid { uid: 0 },
        None,
    )?;
    if response_outcome(&start_response) != Some("applied") {
        return Ok(retarget_mutating_response(&start_response, "vm restart"));
    }
    Ok(applied_response(
        "vm restart",
        format!(
            "vm restart {}: {}; {}",
            request.vm,
            response_summary(&stop_response).unwrap_or("stop applied"),
            response_summary(&start_response).unwrap_or("start applied"),
        ),
    ))
}

fn dispatch_broker_vm_restart_as(
    state: &ServerState,
    request: public_wire::VmLifecycleRequest,
    caller_role: BrokerCallerRole,
) -> Result<Value, TypedError> {
    const VERB: &str = "vm restart";

    if let Some(response) = mutating_verb_preflight(VERB, &request.flags, Some(request.vm.as_str()))
    {
        return Ok(response);
    }

    let stop_response = dispatch_broker_vm_stop_as(state, request.clone(), caller_role.clone())?;
    if response_outcome(&stop_response) != Some("applied") {
        return Ok(retarget_mutating_response(&stop_response, VERB));
    }
    let start_response = dispatch_broker_vm_start_as(state, request.clone(), caller_role)?;
    if response_outcome(&start_response) != Some("applied") {
        return Ok(retarget_mutating_response(&start_response, VERB));
    }
    Ok(applied_response(
        VERB,
        format!(
            "vm restart {}: {}; {}",
            request.vm,
            response_summary(&stop_response).unwrap_or("stop applied"),
            response_summary(&start_response).unwrap_or("start applied"),
        ),
    ))
}

