#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "kebab-case")]
enum HostActivationMarkerState {
    Pending,
    Indeterminate,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
struct HostActivationPendingMarker {
    schema_version: u32,
    vm: String,
    mode: String,
    generation_number: Option<u64>,
    activation_id: String,
    switch_script_basename: String,
    switch_script_sha256: String,
    state: HostActivationMarkerState,
    created_unix_secs: u64,
    updated_unix_secs: u64,
}

struct ActivationLockGuard {
    coordinator: Arc<Mutex<ZoneCoordinator>>,
    zone: ZoneId,
}

impl ActivationLockGuard {
    fn zone(&self) -> &ZoneId {
        &self.zone
    }
}

impl Drop for ActivationLockGuard {
    fn drop(&mut self) {
        if let Ok(mut coordinator) = self.coordinator.lock() {
            let _ = coordinator.finish_activation(&self.zone);
        }
    }
}

fn try_acquire_activation_lock(
    state: &ServerState,
    vm: &str,
) -> Result<ActivationLockGuard, Value> {
    let zone = match d2bd_runtime::zone_authority::authoritative_zone_for_vm(
        &state.zone_coordinator,
        vm,
    ) {
        Ok(zone) => zone,
        Err(_) => {
            return Err(invalid_request_response_with_summary(
                "activation",
                format!("activation target vm '{vm}' has no authoritative Zone"),
                "reconcile the trusted bundle's VM-to-Zone index, then retry activation".to_owned(),
            ));
        }
    };
    let coordinator = Arc::clone(&state.zone_coordinator);
    let acquired = match coordinator.lock() {
        Ok(mut coordinator) => coordinator.begin_activation(&zone),
        Err(_) => Err(CoordinatorError::ZoneNotRegistered),
    };
    match acquired {
        Ok(()) => {}
        Err(CoordinatorError::ActivationInFlight) => {
            return Err(invalid_request_response_with_summary(
                "activation",
                format!("activation already in progress for vm '{vm}'"),
                format!(
                    "wait for the existing activation on vm '{vm}' to finish, then retry the command; status/list will report activation-pending if recovery is needed"
                ),
            ));
        }
        Err(_) => {
            return Err(invalid_request_response_with_summary(
                "activation",
                format!("activation target vm '{vm}' has unavailable Zone state"),
                "retry after the Zone coordinator becomes ready".to_owned(),
            ));
        }
    }
    Ok(ActivationLockGuard { coordinator, zone })
}

fn stage_configuration_ordinal(
    state: &ServerState,
    zone: &ZoneId,
    ordinal: u64,
) -> Result<(), CoordinatorError> {
    state
        .zone_coordinator
        .lock()
        .map_err(|_| CoordinatorError::ZoneNotRegistered)?
        .stage_configuration_ordinal(zone, ordinal)
}

fn activation_marker_dir(state: &ServerState) -> PathBuf {
    state.daemon_state_dir.join("activations")
}

fn activation_marker_path(state: &ServerState, vm: &str) -> PathBuf {
    activation_marker_dir(state).join(format!("{vm}.json"))
}

fn read_activation_marker(state: &ServerState, vm: &str) -> Option<HostActivationPendingMarker> {
    let path = activation_marker_path(state, vm);
    let bytes = fs::read(path).ok()?;
    serde_json::from_slice(&bytes).ok()
}

fn refresh_activation_marker_metrics_on_startup(state: &ServerState) {
    let dir = activation_marker_dir(state);
    let Ok(entries) = fs::read_dir(&dir) else {
        return;
    };
    for entry in entries.flatten() {
        let Ok(bytes) = fs::read(entry.path()) else {
            continue;
        };
        let Ok(marker) = serde_json::from_slice::<HostActivationPendingMarker>(&bytes) else {
            continue;
        };
        tracing::warn!(
            vm = %marker.vm,
            mode = %marker.mode,
            activation_id = %marker.activation_id,
            state = ?marker.state,
            "startup observed unresolved activation marker; VM status/list will report degraded activation-pending"
        );
        record_activation_degraded_metric(state, true);
    }
}

fn restore_configuration_staging_on_startup(state: &ServerState) {
    let dir = activation_marker_dir(state);
    let Ok(entries) = fs::read_dir(&dir) else {
        return;
    };
    for entry in entries.flatten() {
        let Ok(bytes) = fs::read(entry.path()) else {
            continue;
        };
        let Ok(marker) = serde_json::from_slice::<HostActivationPendingMarker>(&bytes) else {
            continue;
        };
        let Some(ordinal) = marker.generation_number else {
            continue;
        };
        let Ok(zone) = d2bd_runtime::zone_authority::authoritative_zone_for_vm(
            &state.zone_coordinator,
            &marker.vm,
        ) else {
            tracing::warn!(
                vm = %marker.vm,
                "activation marker could not be adopted because its VM has no authoritative Zone",
            );
            continue;
        };
        if let Err(error) = stage_configuration_ordinal(state, &zone, ordinal) {
            tracing::warn!(
                vm = %marker.vm,
                error = %error,
                "activation marker configuration staging was quarantined",
            );
        }
    }
}

fn activation_marker_reason(marker: &HostActivationPendingMarker) -> &'static str {
    match marker.state {
        HostActivationMarkerState::Pending => "activation-pending",
        HostActivationMarkerState::Indeterminate => "activation-indeterminate",
    }
}

fn activation_marker_remediation(vm: &str, marker: &HostActivationPendingMarker) -> String {
    match marker.state {
        HostActivationMarkerState::Pending => format!(
            "activation for vm '{vm}' was in progress when the daemon last observed it; retry the same activation or inspect `journalctl -u d2bd` before forcing recovery"
        ),
        HostActivationMarkerState::Indeterminate => format!(
            "activation for vm '{vm}' reached an indeterminate state; start the VM if needed, then retry status/recovery for activation {} or run a fresh switch after confirming the guest generation",
            marker.activation_id
        ),
    }
}

fn record_activation_degraded_metric(state: &ServerState, pending: bool) {
    state.metrics_registry.gauge_set(
        "d2b_daemon_vm_degraded",
        &[("reason", "activation-pending")],
        if pending { 1.0 } else { 0.0 },
    );
}

fn record_activation_phase_metric(
    state: &ServerState,
    phase: &'static str,
    mode: BrokerActivationMode,
    status: &'static str,
    elapsed: Duration,
) {
    state.metrics_registry.histogram_observe(
        "d2b_daemon_activation_phase_duration_seconds",
        &[
            ("phase", phase),
            ("mode", activation_mode_label(mode)),
            ("status", status),
        ],
        elapsed.as_secs_f64(),
    );
}

fn activation_mode_label(mode: BrokerActivationMode) -> &'static str {
    match mode {
        BrokerActivationMode::Switch => "switch",
        BrokerActivationMode::Boot => "boot",
        BrokerActivationMode::Test => "test",
        BrokerActivationMode::Rollback => "rollback",
    }
}

fn dispatch_broker_activation(
    state: &ServerState,
    request: public_wire::ActivationRequest,
    verb: &'static str,
    mode: BrokerActivationMode,
    caller_role: BrokerCallerRole,
) -> Result<Value, TypedError> {
    if let Some(response) = mutating_verb_preflight(verb, &request.flags, Some(request.vm.as_str()))
    {
        return Ok(response);
    }

    if mode == BrokerActivationMode::Boot {
        ensure_vm_runtime_capability(state, &request.vm, RuntimeCapabilityGate::ConfigSync, verb)?;
        return dispatch_broker_activation_metadata_only(
            state,
            request,
            verb,
            mode,
            caller_role,
            None,
        );
    }

    dispatch_live_guest_activation_resource(
        state,
        request,
        verb,
        mode,
        broker_caller_uid(&caller_role),
    )
}

fn dispatch_live_guest_activation_resource(
    state: &ServerState,
    request: public_wire::ActivationRequest,
    verb: &'static str,
    mode: BrokerActivationMode,
    peer_uid: u32,
) -> Result<Value, TypedError> {
    if mode != BrokerActivationMode::Rollback && request.to_generation.is_some() {
        return Ok(invalid_request_response_with_summary(
            verb,
            "a target generation is valid only for rollback".to_owned(),
            "omit --to-generation for switch, test, and boot activation".to_owned(),
        ));
    }
    let guard = match try_acquire_activation_lock(state, &request.vm) {
        Ok(guard) => guard,
        Err(frame) => return Ok(frame),
    };
    let zone = guard.zone().clone();
    let resolver = load_bundle_resolver(state)?;
    let plane = state
        .resource_plane
        .lock()
        .map_err(|_| TypedError::InternalConfig {
            detail: "resource plane unavailable".to_owned(),
        })?
        .clone()
        .ok_or_else(|| TypedError::InternalConfig {
            detail: "resource plane unavailable".to_owned(),
        })?;
    let runtime = plane.zone(&zone).map_err(|_| TypedError::InternalConfig {
        detail: "activation Zone runtime unavailable".to_owned(),
    })?;
    let guest_ref_text = format!("Guest/{}", request.vm);
    let guest_ref =
        ResourceRef::parse(&guest_ref_text).map_err(|_| TypedError::InternalConfig {
            detail: "activation Guest reference invalid".to_owned(),
        })?;
    let guest_ref_canonical = guest_ref.to_canonical_string();
    let get_guest = json!({
        "zoneRef": format!("Zone/{}", zone.as_str()),
        "service": "d2b.resource.v3",
        "method": "Get",
        "resourceRef": guest_ref_canonical,
    });
    let guest = block_on_future(runtime.dispatch_public_cli_request(&get_guest, peer_uid))
        .map_err(|_| TypedError::InternalConfig {
            detail: "activation Guest resource unavailable".to_owned(),
        })?;
    if guest.get("kind").is_some() {
        return Err(TypedError::InternalConfig {
            detail: "activation Guest resource unavailable".to_owned(),
        });
    }
    let (ordinal, artifact) = if mode == BrokerActivationMode::Rollback {
        let target_ordinal = request
            .to_generation
            .ok_or_else(|| TypedError::InternalConfig {
                detail: "rollback target generation unavailable".to_owned(),
            })?;
        let list = json!({
            "zoneRef": format!("Zone/{}", zone.as_str()),
            "service": "d2b.resource.v3",
            "method": "List",
            "resourceType": NIXOS_GENERATION_RESOURCE_TYPE,
            "executionRef": guest_ref.to_canonical_string(),
            "limit": 256,
        });
        let resources = block_on_future(runtime.dispatch_public_cli_request(&list, peer_uid))
            .map_err(|_| TypedError::InternalConfig {
                detail: "rollback generations unavailable".to_owned(),
            })?;
        let artifact = resources
            .get("resources")
            .and_then(Value::as_array)
            .into_iter()
            .flatten()
            .find(|resource| {
                resource
                    .get("spec")
                    .and_then(|spec| spec.get("executionRef"))
                    .and_then(Value::as_str)
                    == Some(guest_ref_canonical.as_str())
                    && resource
                        .pointer("/metadata/name")
                        .and_then(Value::as_str)
                        .and_then(|name| name.rsplit('-').next())
                        .and_then(|value| value.parse::<u64>().ok())
                        == Some(target_ordinal)
            })
            .and_then(|resource| {
                resource
                    .pointer("/spec/systemArtifactId")
                    .and_then(Value::as_str)
            })
            .ok_or_else(|| TypedError::InternalConfig {
                detail: "rollback target generation is not retained".to_owned(),
            })?;
        (target_ordinal, artifact.to_owned())
    } else {
        let activation = resolver
            .find_activation_intent(&intent_id_activation(&request.vm))
            .ok_or_else(|| TypedError::InternalConfig {
                detail: "activation intent unavailable".to_owned(),
            })?;
        let ordinal = activation
            .generation_number
            .filter(|generation| *generation > 0)
            .ok_or_else(|| TypedError::InternalConfig {
                detail: "activation generation unavailable".to_owned(),
            })?;
        let artifact = guest
            .pointer("/spec/systemArtifactId")
            .and_then(Value::as_str)
            .ok_or_else(|| TypedError::InternalConfig {
                detail: "activation system artifact unavailable".to_owned(),
            })?;
        (ordinal, artifact.to_owned())
    };
    let generation_name = activation_generation_name(&request.vm, ordinal, mode);
    let generation_ref = format!("{NIXOS_GENERATION_RESOURCE_TYPE}/{generation_name}");
    let spec = json!({
        "providerRef": "Provider/activation-nixos",
        "executionRef": guest_ref_canonical,
        "systemArtifactId": artifact,
        "activationMode": resource_activation_mode_label(mode),
    });
    let create = json!({
        "zoneRef": format!("Zone/{}", zone.as_str()),
        "service": "d2b.resource.v3",
        "method": "Create",
        "resourceType": NIXOS_GENERATION_RESOURCE_TYPE,
        "resourceName": generation_name,
        "spec": spec,
        "waitForReconcile": false,
    });
    let created =
        block_on_future(runtime.dispatch_public_cli_request(&create, peer_uid)).map_err(|_| {
            TypedError::InternalConfig {
                detail: "activation resource create failed".to_owned(),
            }
        })?;
    if created
        .get("kind")
        .and_then(Value::as_str)
        .is_some_and(|kind| kind != "resource-already-exists")
    {
        return Err(TypedError::InternalConfig {
            detail: "activation resource create refused".to_owned(),
        });
    }
    let deadline = Instant::now() + live_activation_timeout_for(state, &request.vm);
    loop {
        if Instant::now() >= deadline {
            return Ok(broker_failure_response(
                verb,
                format!("activation resource for vm '{}' timed out", request.vm),
                format!(
                    "retry `d2b {verb} {} --apply` after the Guest session recovers",
                    request.vm
                ),
                None,
            ));
        }
        let get = json!({
            "zoneRef": format!("Zone/{}", zone.as_str()),
            "service": "d2b.resource.v3",
            "method": "Get",
            "resourceRef": generation_ref,
        });
        let current = block_on_future(runtime.dispatch_public_cli_request(&get, peer_uid))
            .map_err(|_| TypedError::InternalConfig {
                detail: "activation resource status unavailable".to_owned(),
            })?;
        let current_spec = current.get("spec");
        if current_spec.and_then(|spec| spec.get("executionRef")) != spec.get("executionRef")
            || current_spec.and_then(|spec| spec.get("systemArtifactId"))
                != spec.get("systemArtifactId")
            || current_spec.and_then(|spec| spec.get("activationMode"))
                != spec.get("activationMode")
        {
            return Ok(invalid_request_response_with_summary(
                verb,
                format!(
                    "activation resource '{}' is bound to a different immutable target",
                    generation_ref
                ),
                "inspect the existing NixosGeneration resource and retry with its committed activation mode"
                    .to_owned(),
            ));
        }
        match current.pointer("/status/phase").and_then(Value::as_str) {
            Some("Ready") | Some("Succeeded") => {
                return Ok(applied_response(
                    verb,
                    format!(
                        "d2b {verb} --apply reconciled activation resource for vm '{}' through the Resource API",
                        request.vm
                    ),
                ));
            }
            Some("Failed") | Some("Degraded") => {
                return Ok(broker_failure_response(
                    verb,
                    format!("activation resource for vm '{}' failed", request.vm),
                    "inspect the typed activation resource status before retrying".to_owned(),
                    None,
                ));
            }
            _ => std::thread::sleep(Duration::from_millis(250)),
        }
    }
}

fn activation_generation_name(vm: &str, ordinal: u64, mode: BrokerActivationMode) -> String {
    let suffix = match mode {
        BrokerActivationMode::Switch => "gen",
        BrokerActivationMode::Boot => "boot",
        BrokerActivationMode::Test => "test",
        BrokerActivationMode::Rollback => "rollback",
    };
    let readable = format!("{vm}--{suffix}-{ordinal}");
    if ResourceName::parse(readable.clone()).is_ok() {
        return readable;
    }
    let mut digest = Sha256::new();
    digest.update(b"d2b-activation-generation-v1");
    digest.update([0]);
    digest.update(vm.as_bytes());
    digest.update([0]);
    digest.update(suffix.as_bytes());
    digest.update(ordinal.to_be_bytes());
    let suffix = digest
        .finalize()
        .iter()
        .take(12)
        .map(|byte| format!("{byte:02x}"))
        .collect::<String>();
    format!("activation-gen-{suffix}")
}

const fn resource_activation_mode_label(mode: BrokerActivationMode) -> &'static str {
    match mode {
        BrokerActivationMode::Switch => "switch",
        BrokerActivationMode::Boot => "boot",
        BrokerActivationMode::Test => "test",
        BrokerActivationMode::Rollback => "switch",
    }
}

fn dispatch_run_activation_phase(
    state: &ServerState,
    request: &public_wire::ActivationRequest,
    verb: &'static str,
    mode: BrokerActivationMode,
    phase: BrokerActivationPhase,
    caller_role: BrokerCallerRole,
    system_artifact_id: Option<d2b_contracts_resource::v3::ArtifactId>,
) -> Result<d2b_contracts_broker::broker_wire::RunActivationResponse, Value> {
    const OP_NAME: &str = "RunActivation";
    let started = Instant::now();
    let result = dispatch_broker_request_as(
        state,
        BrokerRequest::RunActivation(BrokerRunActivationRequest {
            bundle_activation_intent_ref: BundleOpId::new(intent_id_activation(&request.vm)),
            mode,
            phase,
            vm: request.vm.clone(),
            system_artifact_id,
            tracing_span_id: None,
        }),
        caller_role,
    );
    let metric_phase = match phase {
        BrokerActivationPhase::Prepare => "prepare",
        BrokerActivationPhase::Commit => "commit",
        BrokerActivationPhase::MetadataOnly => "metadata-only",
    };
    match result {
        Ok(BrokerResponse::RunActivation(response)) => {
            record_activation_phase_metric(state, metric_phase, mode, "success", started.elapsed());
            Ok(response)
        }
        Ok(BrokerResponse::Error(error)) => {
            record_activation_phase_metric(
                state,
                metric_phase,
                mode,
                "broker-error",
                started.elapsed(),
            );
            tracing::warn!(
                broker_kind = %error.kind,
                broker_operation = %error.operation,
                broker_target_wave = error.target_wave.as_deref().unwrap_or("none"),
                broker_message = %error.message,
                broker_action = %error.action,
                "broker live op failed"
            );
            let (summary, remediation) = redact_broker_error_for_launcher(
                OP_NAME,
                error.target_wave.as_deref(),
                &error.kind,
            );
            Err(broker_failure_response(
                verb,
                summary,
                remediation,
                error.target_wave,
            ))
        }
        Ok(other) => {
            record_activation_phase_metric(
                state,
                metric_phase,
                mode,
                "protocol-error",
                started.elapsed(),
            );
            tracing::warn!(
                op_name = OP_NAME,
                broker_response_kind = %broker_response_kind(&other),
                "broker returned unexpected response kind"
            );
            let (summary, remediation) =
                redact_broker_error_for_launcher(OP_NAME, None, "Broker.Protocol");
            Err(broker_failure_response(verb, summary, remediation, None))
        }
        Err(error) => {
            record_activation_phase_metric(
                state,
                metric_phase,
                mode,
                "dispatch-error",
                started.elapsed(),
            );
            tracing::warn!(op_name = OP_NAME, error = ?error, "broker dispatch failed");
            let (summary, remediation) = redact_broker_dispatch_failure_for_launcher(OP_NAME);
            Err(broker_failure_response(verb, summary, remediation, None))
        }
    }
}

fn dispatch_broker_activation_metadata_only(
    state: &ServerState,
    request: public_wire::ActivationRequest,
    verb: &'static str,
    mode: BrokerActivationMode,
    caller_role: BrokerCallerRole,
    system_artifact_id: Option<d2b_contracts_resource::v3::ArtifactId>,
) -> Result<Value, TypedError> {
    let response = match dispatch_run_activation_phase(
        state,
        &request,
        verb,
        mode,
        BrokerActivationPhase::MetadataOnly,
        caller_role,
        system_artifact_id,
    ) {
        Ok(response) => response,
        Err(frame) => return Ok(frame),
    };
    let generation_suffix = response
        .generation_number
        .map(|generation| format!(", generationNumber={generation}"))
        .unwrap_or_default();
    Ok(applied_response(
        verb,
        format!(
            "d2b {verb} --apply staged VM activation metadata only \
             (vm={}, mode={}, summary={}{})",
            response.vm,
            activation_mode_label(response.mode),
            response.summary,
            generation_suffix,
        ),
    ))
}

