struct PublicRequestArtifacts {
    manifest: serde_json::Map<String, Value>,
    host: Option<HostJson>,
    processes: ProcessesJson,
    resolver: Option<BundleResolver>,
    /// Workload target index built from realm controllers config.
    /// `None` when no realm controllers config exists (pre-realm hosts).
    workload_index: Option<d2bd_runtime::workload_target_index::WorkloadTargetIndex>,
}

fn public_artifact_fingerprint(
    state: &ServerState,
) -> Result<d2bd_runtime::public_read_model::PublicArtifactFingerprint, TypedError> {
    d2bd_runtime::public_read_model::public_artifact_fingerprint(
        &state.config.artifacts,
        state.pidfd_table.generation(),
    )
}

fn load_public_request_artifacts(
    state: &ServerState,
    include_usb_status: bool,
    include_closure_metadata: bool,
) -> Result<PublicRequestArtifacts, TypedError> {
    let manifest = load_manifest(&state.config.artifacts.public_manifest_path)?;
    let host = load_json::<HostJson>(&state.config.artifacts.host_path).ok();
    let processes = load_json::<ProcessesJson>(&state.config.artifacts.processes_path)?;
    let qemu_media_declared = host
        .as_ref()
        .and_then(|host| host.qemu_media.as_ref())
        .is_some();
    let resolver = match public_request_resolver_load(
        qemu_media_declared,
        include_usb_status,
        include_closure_metadata,
    ) {
        PublicResolverLoad::NotNeeded => None,
        PublicResolverLoad::Optional => load_bundle_resolver(state).ok(),
        PublicResolverLoad::Required => Some(load_bundle_resolver(state)?),
    };
    if qemu_media_declared {
        let resolver = resolver
            .as_ref()
            .expect("qemu-media declared requires bundle resolver");
        refresh_qemu_media_registry_index_if_needed(state, resolver)?;
    }
    let workload_index = load_realm_controllers_config(&state.config.realm_controllers_config_path)
        .ok()
        .flatten()
        .map(|loaded| {
            d2bd_runtime::workload_target_index::WorkloadTargetIndex::build_from_controllers(
                &loaded.config,
            )
        });
    Ok(PublicRequestArtifacts {
        manifest,
        host,
        processes,
        resolver,
        workload_index,
    })
}

fn dispatch_list(
    state: &ServerState,
    request: public_wire::ListRequest,
) -> Result<Value, TypedError> {
    let cacheable = request.vm.is_none() && request.env.is_none();
    if cacheable
        && let Some(cached) = state
            .public_status_read_model
            .load_list(state.pidfd_table.generation())
    {
        return Ok(cached);
    }
    let before = cacheable
        .then(|| public_artifact_fingerprint(state).ok())
        .flatten();
    let frame = build_public_list(state, request)?;
    if cacheable {
        return Ok(publish_public_frame_if_stable(
            state,
            PublicReadModelKind::List,
            before,
            frame,
            "list",
        ));
    }
    Ok(frame)
}

fn build_public_list(
    state: &ServerState,
    request: public_wire::ListRequest,
) -> Result<Value, TypedError> {
    let PublicRequestArtifacts {
        manifest,
        host,
        processes,
        resolver,
        workload_index,
    } = load_public_request_artifacts(state, false, true)?;
    let closure_resolver = resolver.as_ref();

    // Resolve the `vm` filter through the workload index so callers can
    // use a canonical target (`vm.realm.d2b`) or unambiguous workload id.
    let resolved_vm_filter =
        resolve_vm_filter_target(request.vm.as_deref(), workload_index.as_ref(), &manifest)
            .map_err(typed_error_from_resolution_error)?;

    let vms = std::thread::scope(|scope| {
        let workers = manifest
            .iter()
            .filter(|(name, _)| !name.starts_with('_'))
            .filter(|(name, _)| {
                resolved_vm_filter
                    .as_ref()
                    .map(|vm| vm == *name)
                    .unwrap_or(true)
            })
            .filter(|(_, value)| {
                request
                    .env
                    .as_ref()
                    .map(|env| value.get("env").and_then(Value::as_str) == Some(env.as_str()))
                    .unwrap_or(true)
            })
            .map(|(name, value)| {
                let process_vm = processes.vms.iter().find(|entry| entry.vm == *name);
                let host = host.as_ref();
                let declared_guest_closure_out_path = closure_resolver
                    .and_then(|resolver| resolver.find_guest_closure_out_path(name))
                    .map(str::to_owned);
                let workload_identity_json = workload_index
                    .as_ref()
                    .and_then(|idx| idx.identity_for_vm(name))
                    .and_then(|id| serde_json::to_value(id).ok());
                scope.spawn(move || {
                    let lifecycle = public_vm_lifecycle(state, name, value, process_vm);
                    let guest_closure_out_path = public_guest_closure_out_path(
                        value,
                        &lifecycle,
                        declared_guest_closure_out_path,
                    );
                    let runtime_kind = public_runtime_kind(value);
                    let services = d2bd_runtime::public_projection::public_service_states(
                        &state.pidfd_table,
                        name,
                        value,
                        process_vm,
                    );
                    let service_capabilities = public_service_capabilities(&services);
                    let mut entry = json!({
                        "name": name,
                        "vm": name,
                        "env": value.get("env").cloned().unwrap_or(Value::Null),
                        "staticIp": value.get("staticIp").cloned().unwrap_or(Value::Null),
                        "isNetVm": value.get("isNetVm").cloned().unwrap_or(Value::Bool(false)),
                        "sshUser": value.get("sshUser").cloned().unwrap_or(Value::Null),
                        "graphics": value.get("graphics").cloned().unwrap_or(Value::Bool(false)),
                        "tpm": value.get("tpm").cloned().unwrap_or(Value::Bool(false)),
                        "usbip": value.get("usbipYubikey").cloned().unwrap_or(Value::Bool(false)),
                        "lifecycle": lifecycle,
                        "guestClosureOutPath": guest_closure_out_path,
                        "runtime": public_runtime_summary(&lifecycle, value),
                        "autostart": public_autostart_posture(value),
                        "runtimeCapabilities": public_runtime_capabilities(value),
                        "serviceCapabilities": service_capabilities,
                        "unsupportedCapabilities": public_unsupported_capabilities(value),
                        "qemuMedia": public_qemu_media_status(
                            state,
                            name,
                            runtime_kind.as_deref(),
                            host,
                            process_vm,
                            &services,
                        ),
                        "services": services,
                    });
                    if let Some(identity) = workload_identity_json {
                        entry
                            .as_object_mut()
                            .expect("list entry is a JSON object")
                            .insert("workloadIdentity".to_owned(), identity);
                    }
                    entry
                })
            })
            .collect::<Vec<_>>();
        workers
            .into_iter()
            .map(|worker| worker.join().expect("public list worker panicked"))
            .collect::<Vec<_>>()
    });
    Ok(d2bd_runtime::wire::list_response(vms))
}

#[allow(dead_code)]
fn dispatch_status(
    state: &ServerState,
    request: public_wire::StatusRequest,
) -> Result<Value, TypedError> {
    dispatch_status_as(state, BrokerCallerRole::NotAuthorized, request)
}

fn dispatch_status_as(
    state: &ServerState,
    caller_role: BrokerCallerRole,
    request: public_wire::StatusRequest,
) -> Result<Value, TypedError> {
    let cacheable = request.vm.is_none() && !request.check_bridges;
    if cacheable
        && let Some(cached) = state
            .public_status_read_model
            .load_status(state.pidfd_table.generation())
    {
        return Ok(cached);
    }
    let before = cacheable
        .then(|| public_artifact_fingerprint(state).ok())
        .flatten();
    let frame = build_public_status(state, caller_role, request)?;
    if cacheable {
        return Ok(publish_public_frame_if_stable(
            state,
            PublicReadModelKind::Status,
            before,
            frame,
            "status",
        ));
    }
    Ok(frame)
}

fn publish_public_frame_if_stable(
    state: &ServerState,
    kind: PublicReadModelKind,
    before: Option<PublicArtifactFingerprint>,
    frame: Value,
    kind_name: &'static str,
) -> Value {
    state.public_status_read_model.publish_if_unchanged(
        kind,
        before,
        public_artifact_fingerprint(state).ok(),
        frame,
        kind_name,
    )
}

fn build_public_status(
    state: &ServerState,
    _caller_role: BrokerCallerRole,
    request: public_wire::StatusRequest,
) -> Result<Value, TypedError> {
    let PublicRequestArtifacts {
        manifest,
        host,
        processes,
        resolver,
        workload_index,
    } = load_public_request_artifacts(state, true, false)?;

    // Resolve the `vm` filter through the workload index.
    let resolved_vm_filter =
        resolve_vm_filter_target(request.vm.as_deref(), workload_index.as_ref(), &manifest)
            .map_err(typed_error_from_resolution_error)?;

    let statuses = std::thread::scope(|scope| {
        let workers = manifest
            .iter()
            .filter(|(name, _)| !name.starts_with('_'))
            .filter(|(name, _)| resolved_vm_filter.as_ref().map(|vm| vm == *name).unwrap_or(true))
            .map(|(name, manifest_entry)| {
                let process_vm = processes.vms.iter().find(|entry| entry.vm == *name);
                let host = host.as_ref();
                let usb_resolver = resolver.as_ref();
                let workload_identity_json = workload_index
                    .as_ref()
                    .and_then(|idx| idx.identity_for_vm(name))
                    .and_then(|id| serde_json::to_value(id).ok());
                scope.spawn(move || {
                    let lifecycle = public_vm_lifecycle(state, name, manifest_entry, process_vm);
                    let runtime_kind = public_runtime_kind(manifest_entry);
                    let services = d2bd_runtime::public_projection::public_service_states(
                        &state.pidfd_table,
                        name,
                        manifest_entry,
                        process_vm,
                    );
                    let service_capabilities = public_service_capabilities(&services);
                    let mut entry = json!({
                        "vm": name,
                        "name": name,
                        "env": manifest_entry.get("env").cloned().unwrap_or(Value::Null),
                        "staticIp": manifest_entry.get("staticIp").cloned().unwrap_or(Value::Null),
                        "sshUser": manifest_entry.get("sshUser").cloned().unwrap_or(Value::Null),
                        "graphics": manifest_entry.get("graphics").cloned().unwrap_or(Value::Bool(false)),
                        "tpm": manifest_entry.get("tpm").cloned().unwrap_or(Value::Bool(false)),
                        "usbip": manifest_entry.get("usbipYubikey").cloned().unwrap_or(Value::Bool(false)),
                        "isNetVm": manifest_entry.get("isNetVm").cloned().unwrap_or(Value::Bool(false)),
                        "lifecycle": lifecycle,
                        "runtime": public_runtime_summary(&lifecycle, manifest_entry),
                        "autostart": public_autostart_posture(manifest_entry),
                        "runtimeCapabilities": public_runtime_capabilities(manifest_entry),
                        "serviceCapabilities": service_capabilities,
                        "unsupportedCapabilities": public_unsupported_capabilities(manifest_entry),
                        "qemuMedia": public_qemu_media_status(
                            state,
                            name,
                            runtime_kind.as_deref(),
                            host,
                            process_vm,
                            &services,
                        ),
                        "usb": usb_resolver
                            .and_then(|resolver| {
                                public_usb_status_for_vm(
                                    resolver,
                                    name,
                                )
                            }),
                        "services": services,
                        "bridgeChecks": [],
                    });
                    if let Some(identity) = workload_identity_json {
                        entry
                            .as_object_mut()
                            .expect("status entry is a JSON object")
                            .insert("workloadIdentity".to_owned(), identity);
                    }
                    entry
                })
            })
            .collect::<Vec<_>>();
        workers
            .into_iter()
            .map(|worker| worker.join().expect("public status worker panicked"))
            .collect::<Vec<_>>()
    });

    Ok(d2bd_runtime::wire::status_response(
        json!({ "entries": statuses }),
    ))
}

/// Resolve an optional `vm` filter string from a list/status request through
/// the workload target index before applying it to the manifest.
///
/// Returns the resolved legacy VM name (or `None` if no filter was supplied).
/// Errors when the target is a canonical target that is not in the index, or
/// when a workload-id alias is ambiguous.
fn typed_error_from_resolution_error(
    err: d2bd_runtime::workload_target_index::TargetResolutionError,
) -> TypedError {
    match err {
        d2bd_runtime::workload_target_index::TargetResolutionError::NotFound { target } => {
            TypedError::WorkloadTargetNotFound { target }
        }
        d2bd_runtime::workload_target_index::TargetResolutionError::AliasConflict {
            workload_id,
            candidates,
        } => TypedError::WorkloadAliasConflict {
            workload_id: workload_id.clone(),
            detail: format!("matches workloads [{}]", candidates.join(", ")),
        },
    }
}

fn public_vm_lifecycle(
    state: &ServerState,
    vm: &str,
    manifest_entry: &Value,
    process_vm: Option<&d2b_core::processes::VmProcessDag>,
) -> Value {
    let live_roles = state
        .pidfd_table
        .list_for_vm(vm)
        .into_iter()
        .filter(|registration| {
            state
                .pidfd_table
                .still_alive_same_start_time(vm, &registration.role)
        })
        .map(|registration| registration.role)
        .collect::<Vec<_>>();

    let runner_role = public_vm_runner_role_id(process_vm, manifest_entry);
    let primary_alive = live_roles.iter().any(|role| role == &runner_role);
    let guest_stopped =
        primary_alive && provider_guest_stopped_for_status(state, vm, manifest_entry, &runner_role);
    let lifecycle_state = if guest_stopped {
        "Failed"
    } else if primary_alive {
        "Running"
    } else if live_roles.is_empty() {
        "Stopped"
    } else {
        "Starting"
    };

    let running = lifecycle_state == "Running";
    let activation_marker = read_activation_marker(state, vm);
    if let Some(marker) = activation_marker.as_ref() {
        record_activation_degraded_metric(state, true);
        tracing::warn!(
            vm = %vm,
            mode = %marker.mode,
            activation_id = %marker.activation_id,
            state = ?marker.state,
            "status/list observed unresolved activation marker"
        );
    } else {
        record_activation_degraded_metric(state, false);
    }
    let degraded_reasons = activation_marker
        .as_ref()
        .map(|marker| {
            vec![json!({
                "reason": activation_marker_reason(marker),
                "remediation": activation_marker_remediation(vm, marker),
            })]
        })
        .unwrap_or_default();

    json!({
        "degraded": !degraded_reasons.is_empty(),
        "degradedReasons": degraded_reasons,
        "pendingRestart": running && public_pending_restart(manifest_entry),
        "state": lifecycle_state,
    })
}

fn provider_guest_stopped_for_status(
    state: &ServerState,
    vm: &str,
    manifest_entry: &Value,
    runner_role: &str,
) -> bool {
    let Some(target) = provider_shutdown_target_for_role(manifest_entry, vm, runner_role) else {
        return false;
    };
    match target.kind {
        provider_shutdown::ProviderKind::CloudHypervisor => {
            let Some(socket) = target.api_socket.as_deref() else {
                return false;
            };
            d2bd_runtime::ch_api::blocking_get_json(
                socket,
                "/api/v1/vm.info",
                PUBLIC_STATUS_PROVIDER_PROBE_TIMEOUT,
            )
            .ok()
            .and_then(|body| d2bd_runtime::ch_api::parse_vm_info(&body).ok())
            .and_then(|info| info.state)
            .is_some_and(|state| matches!(state.as_str(), "Created" | "Shutdown"))
        }
        provider_shutdown::ProviderKind::QemuMedia => {
            let request = json!({
                "kind": "QemuMediaQueryStatus",
                "payload": {
                    "vmId": vm,
                    "shutdownContext": true,
                    "tracingSpanId": Value::Null
                }
            });
            dispatch_raw_broker_value_with_timeout(
                state,
                request,
                BrokerCallerRole::RootUid {
                    uid: state.daemon_uid,
                },
                PUBLIC_STATUS_PROVIDER_PROBE_TIMEOUT,
            )
            .ok()
            .and_then(|value| {
                (value.get("kind").and_then(Value::as_str) == Some("QemuMediaQueryStatus"))
                    .then_some(value)
            })
            .and_then(|value| {
                value
                    .get("payload")
                    .and_then(|payload| payload.get("status"))
                    .and_then(Value::as_str)
                    .map(str::to_owned)
            })
            .is_some_and(|status| {
                matches!(
                    status.as_str(),
                    "shutdown" | "connection-lost-during-shutdown"
                )
            })
        }
    }
}

fn public_qemu_media_status(
    state: &ServerState,
    vm: &str,
    runtime_kind: Option<&str>,
    host: Option<&HostJson>,
    process_vm: Option<&d2b_core::processes::VmProcessDag>,
    services: &Value,
) -> Option<Value> {
    if runtime_kind != Some("qemu-media") {
        return None;
    }
    let runner = process_vm.and_then(|entry| {
        entry
            .nodes
            .iter()
            .find(|node| node.role == ProcessRole::QemuMediaRunner)
    });
    let qmp_socket = runner.and_then(qemu_media_qmp_socket);
    let state_text = services
        .get("qemuMedia")
        .and_then(Value::as_str)
        .map(str::to_owned)
        .unwrap_or_else(|| {
            d2bd_runtime::public_projection::public_pidfd_role_state(
                &state.pidfd_table,
                vm,
                RunnerRole::QemuMedia.as_str(),
            )
        });
    let qemu_media_host = host.and_then(|host| host.qemu_media.as_ref());
    let media = qemu_media_host
        .map(|contract| {
            contract
                .sources
                .iter()
                .filter(|source| source.vm == vm)
                .map(|source| qemu_media_source_status(contract.registry_dir.as_str(), source))
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();
    let qmp_readiness = qmp_socket.as_deref().map(|path| {
        if qemu_media_unix_socket_listening(path) {
            "ready".to_owned()
        } else if state_text == "running" {
            "pending".to_owned()
        } else {
            "not-started".to_owned()
        }
    });
    let pre_cont_progress = match qmp_readiness.as_deref() {
        Some("ready") if state_text == "running" => "paused-before-cont",
        Some("pending") if state_text == "running" => "waiting-for-qmp",
        _ => "not-started",
    };
    Some(json!({
        "firmwareMode": "none",
        "runner": {
            "state": state_text,
            "role": RunnerRole::QemuMedia.as_str(),
            "preContProgress": pre_cont_progress,
            "qmpReadiness": qmp_readiness,
        },
        "media": media,
    }))
}

fn qemu_media_source_status(registry_dir: &str, source: &QemuMediaSourceIntent) -> Value {
    let (state, remediation) = qemu_media_registry_state(registry_dir, source);
    let status = json!({
        "mediaRef": source.media_ref,
        "slot": source.slot,
        "sourceKind": serde_kebab_string(&source.source_kind),
        "format": serde_kebab_string(&source.format),
        "readOnly": source.read_only,
        "registry": {
            "state": state,
            "remediation": remediation,
        },
    });
    status
}

fn qemu_media_registry_state(
    _registry_dir: &str,
    source: &QemuMediaSourceIntent,
) -> (String, Option<String>) {
    if serde_kebab_string(&source.source_kind) != "physical-usb" {
        return ("direct-config".to_owned(), None);
    }
    let records = qemu_media_probe_registry_records();
    let Some(record) = records
        .iter()
        .find(|record| record.vm == source.vm && record.media_ref == source.media_ref)
    else {
        return (
            "missing".to_owned(),
            Some(format!(
                "declare the boot-drive physical USB source for vm `{}` in config, then run `d2b usb probe` to verify the runtime selector for `{}` before starting or attaching this media",
                source.vm, source.media_ref
            )),
        );
    };
    let expected_kind = serde_kebab_string(&source.source_kind);
    let expected_format = serde_kebab_string(&source.format);
    if record.vm == source.vm
        && record.media_ref == source.media_ref
        && record.source_kind == expected_kind
        && record.format == expected_format
        && record.read_only == source.read_only
    {
        ("present".to_owned(), None)
    } else {
        (
            "stale".to_owned(),
            Some(
                "registry entry does not match the current declaration; update qemu-media config if needed, then run `d2b usb probe`"
                    .to_owned(),
            ),
        )
    }
}

