    fn normalize_verb(verb: &str) -> String {
        verb.chars()
            .filter(|ch| ch.is_ascii_alphanumeric())
            .flat_map(|ch| ch.to_lowercase())
            .collect()
    }

    fn expected_mutating_response_verb(verb: &str) -> &str {
        match verb {
            "usbipBind" => "usb attach",
            "usbipUnbind" => "usb detach",
            other => other,
        }
    }

