    #[test]
    fn host_shutdown_peer_is_allowed_vm_stop_only() {
        let state =
            test_state_with_broker_socket(unreachable_broker_socket_path("host-shutdown-vmstop"));
        let peer = host_shutdown_peer();
        let (_, vm_stop_request) = destructive_mutating_requests()
            .into_iter()
            .find(|(verb, _)| *verb == "vmStop")
            .expect("vmStop must be in destructive_mutating_requests");
        // vmStop must succeed for HostShutdown.
        let response = dispatch_request(&state, &peer, vm_stop_request)
            .unwrap_or_else(|err| panic!("HostShutdown vmStop unexpectedly denied: {err:?}"));
        assert_eq!(
            response.get("type").and_then(serde_json::Value::as_str),
            Some("mutatingVerbResponse"),
            "HostShutdown vmStop must return mutatingVerbResponse"
        );
    }

    #[test]
    fn host_shutdown_peer_denied_all_non_vmstop_admin_verbs() {
        let state =
            test_state_with_broker_socket(unreachable_broker_socket_path("host-shutdown-denied"));
        let peer = host_shutdown_peer();
        let denied_verbs: Vec<(&str, d2bd_runtime::wire::Request)> =
            destructive_mutating_requests()
                .into_iter()
                .filter(|(verb, _)| *verb != "vmStop")
                .collect();
        assert!(
            !denied_verbs.is_empty(),
            "at least one non-vmStop admin verb must exist to deny"
        );
        for (verb, request) in denied_verbs {
            let err = dispatch_request(&state, &peer, request)
                .expect_err(&format!("HostShutdown must not be allowed {verb}"));
            assert!(
                matches!(
                    err,
                    d2bd_runtime::typed_error::TypedError::AuthzNotAdmin { .. }
                ),
                "HostShutdown denial of {verb} must be AuthzNotAdmin, got {err:?}"
            );
        }
    }

    #[test]
    fn host_shutdown_peer_is_denied_for_read_only_requests() {
        let state =
            test_state_with_broker_socket(unreachable_broker_socket_path("host-shutdown-read"));
        let peer = host_shutdown_peer();
        let requests = [
            (
                "list",
                d2bd_runtime::wire::Request::List(public_wire::ListRequest {
                    env: None,
                    vm: None,
                }),
            ),
            (
                "status",
                d2bd_runtime::wire::Request::Status(public_wire::StatusRequest {
                    check_bridges: false,
                    vm: None,
                }),
            ),
            ("authStatus", d2bd_runtime::wire::Request::AuthStatus),
        ];
        for (expected_verb, request) in requests {
            let err = dispatch_request(&state, &peer, request)
                .expect_err("HostShutdown must not bypass its vmStop-only boundary");
            assert!(
                matches!(err, TypedError::AuthzNotAdmin { .. }),
                "HostShutdown denial of {expected_verb} must preserve AuthzNotAdmin: {err:?}"
            );
        }
    }

    #[test]
    fn vm_start_sidecar_roles_use_long_lived_runner_modes() {
        let cases = [
            (ProcessRole::Gpu, RunnerRole::Gpu),
            (ProcessRole::Audio, RunnerRole::Audio),
            (ProcessRole::Video, RunnerRole::Video),
            (ProcessRole::QemuMediaRunner, RunnerRole::QemuMedia),
            (ProcessRole::VsockRelay, RunnerRole::VsockRelay),
            (ProcessRole::Usbip, RunnerRole::Usbip),
            (ProcessRole::WaylandProxy, RunnerRole::WaylandProxy),
        ];
        for (role, expected_runner_role) in cases {
            match vm_start_node_mode(&role) {
                VmStartNodeMode::LongLived(actual) => assert_eq!(actual, expected_runner_role),
                other => panic!("expected LongLived for {role:?}, got {other:?}"),
            }
        }
    }

