    #[test]
    fn graphics_vm_start_refuses_without_resource_backed_display_reconciliation() {
        use d2b_core::processes::{
            NodeId, ProcessExecutionDomain, ProcessRole, VmProcessDag, VmProcessInvariants,
        };

        let state = test_state_with_broker_socket(unreachable_broker_socket_path(
            "vm-start-display-resource-missing",
        ));
        let mut node = readiness_test_node();
        node.id = NodeId("wayland-proxy".to_owned());
        node.role = ProcessRole::WaylandProxy;
        node.execution_ref = Some("Host/host-system".to_owned());
        node.execution_domain = Some(ProcessExecutionDomain::System);
        node.binary_path = Some("/nix/store/d2b-wayland-proxy/bin/d2b-wayland-proxy".to_owned());
        node.argv = vec![
            "d2b-vm-a-wlproxy".to_owned(),
            "--provider-kind".to_owned(),
            "local-vm".to_owned(),
        ];
        let dag = VmProcessDag {
            workload_identity: None,
            vm: "vm-a".to_owned(),
            nodes: vec![node],
            edges: Vec::new(),
            invariants: VmProcessInvariants {
                per_vm_audit_pipeline: true,
                swtpm_pre_start_flush: false,
                tpm_ownership_migration_without_running_vm_mutation: false,
                usbip_gating: false,
            },
        };

        assert_eq!(
            reconcile_display_before_vm_start(&state, "vm-a", &dag),
            Err("display-resource-plane-unavailable".to_owned()),
            "graphics start must fail closed before the display socket wait"
        );
        assert!(
            !state
                .pidfd_table
                .contains("vm-a", RunnerRole::WaylandProxy.as_str()),
            "missing committed display state must not fall back to direct DAG spawning"
        );
    }

    #[test]
    #[cfg_attr(
        not(test_root),
        ignore = "P2fu1 software-r2 (longstanding pre-existing): same root/owner requirement as vm_start_broker_unreachable_returns_broker_error."
    )]
    fn vm_start_registers_pidfd_table_entry_from_broker_fd() {
        use d2b_contracts::types::{RoleId, VmId};
        use d2b_contracts_broker::broker_wire::{BrokerRequest, RunnerRole};

        let socket_path = unreachable_broker_socket_path("vm-start-registers");
        if let Some(parent) = socket_path.parent() {
            fs::create_dir_all(parent).expect("create broker socket parent");
        }
        fs::remove_file(&socket_path).ok();

        let listener = socket(
            AddressFamily::Unix,
            SockType::SeqPacket,
            SockFlag::SOCK_CLOEXEC,
            None,
        )
        .expect("create broker listener");
        let address = UnixAddr::new(&socket_path).expect("broker socket address");
        bind(listener.as_raw_fd(), &address).expect("bind broker listener");
        listen(&listener, Backlog::new(1).expect("listener backlog"))
            .expect("listen on broker socket");

        let daemon_state_dir = test_daemon_state_dir("vm-start-registers");
        let artifacts = write_minimal_vm_start_bundle_artifacts(&daemon_state_dir);
        let broker_reap_log = BrokerReapLog::new();
        let state = ServerState {
            config: DaemonConfig {
                broker_socket_path: socket_path.clone(),
                artifacts,
                ..DaemonConfig::default()
            },
            daemon_uid: 0,
            daemon_audit: Arc::new(d2bd_runtime::daemon_audit::DaemonAuditLog::no_op()),
            daemon_state_dir: daemon_state_dir.clone(),
            pidfd_table: Arc::new(
                PidfdTable::new(daemon_state_dir.join("pidfd-table.json"))
                    .with_broker_reap_log(Arc::clone(&broker_reap_log)),
            ),
            broker_reap_log,
            metrics_registry: Arc::new(d2bd_runtime::metrics::Registry::new()),
            exec_sessions: Arc::new(crate::exec_session::SessionTable::new(
                crate::exec_session::ExecSessionCaps::default(),
            )),
            console_sessions: Arc::new(Mutex::new(
                crate::console_session::ConsoleSessionTable::default(),
            )),
            conn_semaphore: d2bd_runtime::concurrency::ConnSemaphore::new(8),
            op_locks: d2bd_runtime::concurrency::OpLockManager::new(),
            public_status_read_model: Arc::new(
                d2bd_runtime::public_read_model::PublicStatusReadModel::new(),
            ),
            provider_runtime: Arc::new(crate::provider_registry::ProviderRuntime::new()),
            resource_plane: Arc::new(Mutex::new(None)),
            interaction_runtime: Arc::new(tokio::sync::Mutex::new(None)),
            interaction_listeners: Arc::new(Mutex::new(None)),
            typed_shell_session_targets: d2bd_runtime::typed_shell_targets::new_cache(),
            zone_coordinator: d2bd_runtime::zone_authority::new_coordinator(),
            config_staging: Arc::new(Mutex::new(Default::default())),
            guest_component_sessions: Arc::new(tokio::sync::Mutex::new(HashMap::new())),
            guest_component_session_locks: Arc::new(tokio::sync::Mutex::new(HashMap::new())),
            security_key_sessions: Arc::new(parking_lot::Mutex::new(
                crate::security_key::SkSessionTable::default(),
            )),
            unsafe_local_helpers: Arc::new(d2bd_runtime::unsafe_local_helper::HelperRegistry::new(
                0,
                [],
            )),
        };
        let server_socket_path = socket_path.clone();
        let broker = thread::spawn(move || {
            let accepted_fd =
                accept4(listener.as_raw_fd(), SockFlag::SOCK_CLOEXEC).expect("accept broker peer");
            let frame = read_test_frame(accepted_fd).expect("read broker request frame");
            let envelope: BrokerRequestEnvelope =
                serde_json::from_slice(&frame).expect("decode broker request frame");
            match envelope.request {
                BrokerRequest::SpawnRunner(request) => {
                    assert_eq!(request.vm_id.as_str(), "vm-a");
                    assert_eq!(request.role_id.as_str(), VM_RUNNER_ROLE_ID);
                    assert_eq!(request.role, RunnerRole::CloudHypervisor);
                }
                other => panic!("unexpected broker request: {other:?}"),
            }

            let child = ChildGuard::new(
                Command::new("sleep")
                    .arg("600")
                    .spawn()
                    .expect("spawn child for broker reply"),
            );
            let pidfd = open_child_pidfd(child.child());
            write_test_json_frame_with_fds(
                accepted_fd,
                &BrokerResponse::SpawnRunner(SpawnRunnerResponse {
                    vm_id: VmId::new("vm-a"),
                    role_id: RoleId::new(VM_RUNNER_ROLE_ID),
                    role: RunnerRole::CloudHypervisor,
                    resource_ref: None,
                    resource_uid: None,
                    zone_uid: None,
                    owner_ref: None,
                    runtime_scope: None,
                    execution_ref: None,
                    execution_domain: None,
                    user_ref: None,
                    guest_execution: None,
                    provider_identity: None,
                    template_identity: None,
                    generation: None,
                    bundle_content_identity: None,
                    pid: child.child().id() as i32,
                    start_time_ticks: read_child_start_time(child.child()),
                    pidfd_index: 0,
                    controller_bootstrap_fd_index: None,
                    console_fd_index: None,
                }),
                &[pidfd.as_raw_fd()],
            )
            .expect("write spawn response with pidfd");
            close(accepted_fd).expect("close broker peer");
            fs::remove_file(&server_socket_path).ok();
            child
        });

        let response = dispatch_broker_vm_start(
            &state,
            VmLifecycleRequest {
                vm: "vm-a".to_owned(),
                flags: MutationFlags {
                    apply: true,
                    ..MutationFlags::default()
                },
                force: false,
                no_wait_api: false,
            },
        )
        .expect("vm start response");

        assert_eq!(
            response.get("outcome").and_then(serde_json::Value::as_str),
            Some("applied")
        );
        assert!(
            response
                .get("summary")
                .and_then(serde_json::Value::as_str)
                .unwrap_or_default()
                .contains("registered in pidfd_table")
        );
        assert!(state.pidfd_table.contains("vm-a", VM_RUNNER_ROLE_ID));

        let child = broker.join().expect("join broker thread");
        state
            .pidfd_table
            .signal("vm-a", VM_RUNNER_ROLE_ID, libc::SIGKILL)
            .expect("cleanup signal");
        assert!(matches!(
            state
                .pidfd_table
                .wait_terminated("vm-a", VM_RUNNER_ROLE_ID, std::time::Duration::from_secs(5))
                .expect("cleanup wait"),
            WaitTermination::Terminated | WaitTermination::TerminatedByBroker { .. }
        ));
        state.pidfd_table.snapshot().expect("cleanup snapshot");
        let status = child.wait();
        assert!(!status.success());
    }

    #[test]
    #[ignore = "flaky on shared hosts; Unix socket reuse races"]
    fn vm_start_drives_supervisor_dag_in_topo_order() {
        use d2b_contracts::types::{RoleId, VmId};
        use d2b_contracts_broker::broker_wire::{BrokerRequest, RunnerRole};

        let daemon_state_dir = test_daemon_state_dir("vm-start-dag");
        let socket_path = unreachable_broker_socket_path("vm-start-dag");
        if let Some(parent) = socket_path.parent() {
            fs::create_dir_all(parent).expect("create broker socket parent");
        }
        fs::remove_file(&socket_path).ok();

        let store_marker = daemon_state_dir.join("store-marker");
        fs::write(&store_marker, b"ok").expect("write store marker");
        let short_socket_dir = std::env::var_os("CARGO_MANIFEST_DIR")
            .map(PathBuf::from)
            .or_else(|| std::env::current_dir().ok())
            .expect("resolve test socket root")
            .join("target");
        fs::create_dir_all(&short_socket_dir).expect("create short socket dir");
        let socket_id = NEXT_TEST_ID.fetch_add(1, Ordering::Relaxed);
        let share_ro_socket = short_socket_dir.join(format!("vm-start-ro-{socket_id}.sock"));
        let share_meta_socket = short_socket_dir.join(format!("vm-start-meta-{socket_id}.sock"));
        let api_socket = short_socket_dir.join(format!("vm-start-api-{socket_id}.sock"));
        fs::remove_file(&share_ro_socket).ok();
        fs::remove_file(&share_meta_socket).ok();
        fs::remove_file(&api_socket).ok();
        let artifacts = write_custom_vm_start_bundle_artifacts(
            &daemon_state_dir,
            &api_socket,
            json!({
                "schemaVersion": "v2",
                "vms": [
                    {
                        "vm": "vm-a",
                        "nodes": [
                            {
                                "id": "host-reconcile",
                                "role": "host-reconcile",
                                "unit": null,
                                "profile": minimal_role_profile("vm-vm-a-host-reconcile", "d2b.slice/vm-a/host-reconcile"),
                                "readiness": [
                                    { "kind": "component-specific", "value": "host ready" }
                                ]
                            },
                            {
                                "id": "store-virtiofs-preflight",
                                "role": "store-virtiofs-preflight",
                                "unit": null,
                                "profile": minimal_role_profile("vm-vm-a-store-virtiofs-preflight", "d2b.slice/vm-a/store-virtiofs-preflight"),
                                "readiness": [
                                    { "kind": "command", "value": ["test", "-e", store_marker.display().to_string()] }
                                ]
                            },
                            {
                                "id": "virtiofsd-ro-store",
                                "role": "virtiofsd",
                                "unit": null,
                                "profile": minimal_role_profile("vm-vm-a-virtiofsd-ro-store", "d2b.slice/vm-a/virtiofsd-ro-store"),
                                "readiness": [
                                    { "kind": "unix-socket-exists", "value": share_ro_socket.display().to_string() }
                                ]
                            },
                            {
                                "id": "virtiofsd-d2b-meta",
                                "role": "virtiofsd",
                                "unit": null,
                                "profile": minimal_role_profile("vm-vm-a-virtiofsd-d2b-meta", "d2b.slice/vm-a/virtiofsd-d2b-meta"),
                                "readiness": [
                                    { "kind": "unix-socket-exists", "value": share_meta_socket.display().to_string() }
                                ]
                            },
                            {
                                "id": "cloud-hypervisor",
                                "role": "cloud-hypervisor-runner",
                                "unit": null,
                                "profile": minimal_role_profile("vm-vm-a-cloud-hypervisor", "d2b.slice/vm-a/cloud-hypervisor"),
                                "readiness": [
                                    { "kind": "api-socket-info", "value": api_socket.display().to_string() }
                                ]
                            },
                            {
                                "id": "component-session-health",
                                "role": "component-session-health",
                                "unit": null,
                                "profile": minimal_role_profile("vm-vm-a-component-session-health", "d2b.slice/vm-a/component-session-health"),
                                "readiness": [
                                    { "kind": "component-specific", "value": "component-session healthy" }
                                ]
                            }
                        ],
                        "edges": [
                            { "from": "host-reconcile", "to": "store-virtiofs-preflight", "reason": "host before store" },
                            { "from": "store-virtiofs-preflight", "to": "virtiofsd-ro-store", "reason": "share one" },
                            { "from": "store-virtiofs-preflight", "to": "virtiofsd-d2b-meta", "reason": "share two" },
                            { "from": "virtiofsd-ro-store", "to": "cloud-hypervisor", "reason": "share one ready" },
                            { "from": "virtiofsd-d2b-meta", "to": "cloud-hypervisor", "reason": "share two ready" },
                            { "from": "cloud-hypervisor", "to": "component-session-health", "reason": "component session after ch" }
                        ],
                        "invariants": {
                            "swtpmPreStartFlush": true,
                            "perVmAuditPipeline": true,
                            "usbipGating": true,
                            "tpmOwnershipMigrationWithoutRunningVmMutation": true
                        }
                    }
                ]
            }),
        );
        let broker_reap_log = BrokerReapLog::new();
        let state = ServerState {
            config: DaemonConfig {
                broker_socket_path: socket_path.clone(),
                artifacts,
                ..DaemonConfig::default()
            },
            daemon_uid: 0,
            daemon_audit: Arc::new(d2bd_runtime::daemon_audit::DaemonAuditLog::no_op()),
            daemon_state_dir: daemon_state_dir.clone(),
            pidfd_table: Arc::new(
                PidfdTable::new(daemon_state_dir.join("pidfd-table.json"))
                    .with_broker_reap_log(Arc::clone(&broker_reap_log)),
            ),
            broker_reap_log,
            metrics_registry: Arc::new(d2bd_runtime::metrics::Registry::new()),
            exec_sessions: Arc::new(crate::exec_session::SessionTable::new(
                crate::exec_session::ExecSessionCaps::default(),
            )),
            console_sessions: Arc::new(Mutex::new(
                crate::console_session::ConsoleSessionTable::default(),
            )),
            conn_semaphore: d2bd_runtime::concurrency::ConnSemaphore::new(8),
            op_locks: d2bd_runtime::concurrency::OpLockManager::new(),
            public_status_read_model: Arc::new(
                d2bd_runtime::public_read_model::PublicStatusReadModel::new(),
            ),
            provider_runtime: Arc::new(crate::provider_registry::ProviderRuntime::new()),
            resource_plane: Arc::new(Mutex::new(None)),
            interaction_runtime: Arc::new(tokio::sync::Mutex::new(None)),
            interaction_listeners: Arc::new(Mutex::new(None)),
            typed_shell_session_targets: d2bd_runtime::typed_shell_targets::new_cache(),
            zone_coordinator: d2bd_runtime::zone_authority::new_coordinator(),
            config_staging: Arc::new(Mutex::new(Default::default())),
            guest_component_sessions: Arc::new(tokio::sync::Mutex::new(HashMap::new())),
            guest_component_session_locks: Arc::new(tokio::sync::Mutex::new(HashMap::new())),
            security_key_sessions: Arc::new(parking_lot::Mutex::new(
                crate::security_key::SkSessionTable::default(),
            )),
            unsafe_local_helpers: Arc::new(d2bd_runtime::unsafe_local_helper::HelperRegistry::new(
                0,
                [],
            )),
        };

        let listener = socket(
            AddressFamily::Unix,
            SockType::SeqPacket,
            SockFlag::SOCK_CLOEXEC,
            None,
        )
        .expect("create broker listener");
        let address = UnixAddr::new(&socket_path).expect("broker socket address");
        bind(listener.as_raw_fd(), &address).expect("bind broker listener");
        listen(&listener, Backlog::new(3).expect("listener backlog"))
            .expect("listen on broker socket");

        let request_order = Arc::new(Mutex::new(Vec::<String>::new()));
        let request_order_thread = Arc::clone(&request_order);
        let server_socket_path = socket_path.clone();
        let share_ro_socket_for_thread = share_ro_socket.clone();
        let share_meta_socket_for_thread = share_meta_socket.clone();
        let api_socket_for_thread = api_socket.clone();
        let broker = thread::spawn(move || {
            let mut children = Vec::new();
            let mut share_listeners = Vec::new();
            for _ in 0..3 {
                let accepted_fd = accept4(listener.as_raw_fd(), SockFlag::SOCK_CLOEXEC)
                    .expect("accept broker peer");
                let frame = read_test_frame(accepted_fd).expect("read broker request frame");
                let envelope: BrokerRequestEnvelope =
                    serde_json::from_slice(&frame).expect("decode broker request frame");
                let request = match envelope.request {
                    BrokerRequest::SpawnRunner(request) => request,
                    other => panic!("unexpected broker request: {other:?}"),
                };
                request_order_thread
                    .lock()
                    .expect("lock request order")
                    .push(request.role_id.as_str().to_owned());
                assert_eq!(request.vm_id.as_str(), "vm-a");
                let expected_runner_role = if request.role_id.as_str() == VM_RUNNER_ROLE_ID {
                    RunnerRole::CloudHypervisor
                } else {
                    RunnerRole::Virtiofsd
                };
                assert_eq!(request.role, expected_runner_role);

                match request.role_id.as_str() {
                    "virtiofsd-ro-store" => {
                        fs::remove_file(&share_ro_socket_for_thread).ok();
                        share_listeners.push(
                            UnixListener::bind(&share_ro_socket_for_thread)
                                .expect("bind ro-store socket"),
                        );
                    }
                    "virtiofsd-d2b-meta" => {
                        fs::remove_file(&share_meta_socket_for_thread).ok();
                        share_listeners.push(
                            UnixListener::bind(&share_meta_socket_for_thread)
                                .expect("bind d2b-meta socket"),
                        );
                    }
                    VM_RUNNER_ROLE_ID => {}
                    other => panic!("unexpected runner role id: {other}"),
                }

                let child = ChildGuard::new(
                    Command::new("sleep")
                        .arg("600")
                        .spawn()
                        .expect("spawn child for broker reply"),
                );
                let pidfd = open_child_pidfd(child.child());
                write_test_json_frame_with_fds(
                    accepted_fd,
                    &BrokerResponse::SpawnRunner(SpawnRunnerResponse {
                        vm_id: VmId::new("vm-a"),
                        role_id: RoleId::new(request.role_id.as_str()),
                        role: expected_runner_role,
                        resource_ref: None,
                        resource_uid: None,
                        zone_uid: None,
                        owner_ref: None,
                        runtime_scope: None,
                        execution_ref: None,
                        execution_domain: None,
                        user_ref: None,
                        guest_execution: None,
                        provider_identity: None,
                        template_identity: None,
                        generation: None,
                        bundle_content_identity: None,
                        pid: child.child().id() as i32,
                        start_time_ticks: read_child_start_time(child.child()),
                        pidfd_index: 0,
                        controller_bootstrap_fd_index: None,
                        console_fd_index: None,
                    }),
                    &[pidfd.as_raw_fd()],
                )
                .expect("write spawn response with pidfd");
                close(accepted_fd).expect("close broker peer");
                if request.role_id.as_str() == VM_RUNNER_ROLE_ID {
                    fs::remove_file(&api_socket_for_thread).ok();
                    let api_listener =
                        UnixListener::bind(&api_socket_for_thread).expect("bind api socket");
                    let (mut stream, _) = api_listener.accept().expect("accept api peer");
                    let mut buffer = [0_u8; 512];
                    let _ = stream.read(&mut buffer);
                    stream
                        .write_all(b"HTTP/1.1 200 OK\r\nContent-Length: 2\r\n\r\n{}")
                        .expect("write api response");
                }
                children.push(child);
            }
            fs::remove_file(&server_socket_path).ok();
            children
        });

        let response = dispatch_broker_vm_start(
            &state,
            VmLifecycleRequest {
                vm: "vm-a".to_owned(),
                flags: MutationFlags {
                    apply: true,
                    ..MutationFlags::default()
                },
                force: false,
                no_wait_api: false,
            },
        )
        .expect("vm start response");

        assert_eq!(
            response.get("outcome").and_then(serde_json::Value::as_str),
            Some("applied")
        );
        assert!(
            response
                .get("summary")
                .and_then(serde_json::Value::as_str)
                .unwrap_or_default()
                .contains("registered in pidfd_table")
        );
        let order = request_order.lock().expect("lock request order").clone();
        assert_eq!(order.len(), 3);
        assert_eq!(order.last().map(String::as_str), Some(VM_RUNNER_ROLE_ID));
        let mut share_roles = order[..2].to_vec();
        share_roles.sort();
        assert_eq!(
            share_roles,
            vec![
                "virtiofsd-d2b-meta".to_owned(),
                "virtiofsd-ro-store".to_owned()
            ]
        );
        assert!(state.pidfd_table.contains("vm-a", "virtiofsd-ro-store"));
        assert!(state.pidfd_table.contains("vm-a", "virtiofsd-d2b-meta"));
        assert!(state.pidfd_table.contains("vm-a", VM_RUNNER_ROLE_ID));

        let children = broker.join().expect("join broker thread");
        for role in [
            "virtiofsd-ro-store",
            "virtiofsd-d2b-meta",
            VM_RUNNER_ROLE_ID,
        ] {
            state
                .pidfd_table
                .signal("vm-a", role, libc::SIGKILL)
                .expect("cleanup signal");
            assert!(matches!(
                state
                    .pidfd_table
                    .wait_terminated("vm-a", role, std::time::Duration::from_secs(5))
                    .expect("cleanup wait"),
                WaitTermination::Terminated | WaitTermination::TerminatedByBroker { .. }
            ));
            let _ = state.pidfd_table.deregister("vm-a", role);
        }
        state.pidfd_table.snapshot().expect("cleanup snapshot");
        for child in children {
            let status = child.wait();
            assert!(!status.success());
        }
        fs::remove_file(&share_ro_socket).ok();
        fs::remove_file(&share_meta_socket).ok();
        fs::remove_file(&api_socket).ok();
    }

    #[test]
    fn startup_adoption_quarantines_without_authoritative_lifecycle_identity() {
        struct FixedProcReader;

        impl ProcReader for FixedProcReader {
            fn proc_starttime(&self, pid: i32) -> Result<Option<u64>, String> {
                match pid {
                    4242 => Ok(Some(55)),
                    _ => Ok(None),
                }
            }
        }

        struct RecordingOpener {
            calls: Mutex<Vec<(String, String, i32, u64)>>,
        }

        impl RecordingOpener {
            fn new() -> Self {
                Self {
                    calls: Mutex::new(Vec::new()),
                }
            }
        }

        impl PidfdOpener for RecordingOpener {
            fn open_pidfd(
                &self,
                vm: &str,
                role_id: &str,
                pid: i32,
                expected_start_time_ticks: u64,
            ) -> Result<std::os::fd::OwnedFd, String> {
                self.calls.lock().expect("lock opener calls").push((
                    vm.to_owned(),
                    role_id.to_owned(),
                    pid,
                    expected_start_time_ticks,
                ));
                let file = File::open("/dev/null").expect("open /dev/null");
                Ok(file.into())
            }
        }

        let daemon_state_dir = test_daemon_state_dir("startup-adoption");
        let store = FilesystemSnapshotStore::new(&daemon_state_dir);
        SnapshotStore::upsert(
            &store,
            &RunnerSnapshotRecord {
                vm: "vm-a".to_owned(),
                role_id: "virtiofsd-ro-store".to_owned(),
                role: RunnerRole::Virtiofsd,
                owner_resource_uid: None,
                zone_uid: Some(
                    ResourceUid::parse("11111111-1111-4111-8111-111111111111").expect("Zone UID"),
                ),
                guest_uid: Some(
                    ResourceUid::parse("22222222-2222-4222-8222-222222222222").expect("Guest UID"),
                ),
                guest_generation: Some(ResourceGeneration::new(1).expect("Guest generation")),
                provider_assignment_generation: Some(
                    ResourceGeneration::new(1).expect("Provider assignment generation"),
                ),
                policy_revision: Some(1),
                operation_id: Some("startup-adoption-operation".to_owned()),
                pid: 4242,
                start_time_ticks: 55,
                snapshotted_at: "2026-05-30T00:00:00Z".to_owned(),
            },
        )
        .expect("write runner snapshot");

        let broker_reap_log = BrokerReapLog::new();
        let state = ServerState {
            config: DaemonConfig::default(),
            daemon_uid: 0,
            daemon_audit: Arc::new(d2bd_runtime::daemon_audit::DaemonAuditLog::no_op()),
            daemon_state_dir: daemon_state_dir.clone(),
            pidfd_table: Arc::new(
                PidfdTable::new(daemon_state_dir.join("pidfd-table.json"))
                    .with_broker_reap_log(Arc::clone(&broker_reap_log)),
            ),
            broker_reap_log,
            metrics_registry: Arc::new(d2bd_runtime::metrics::Registry::new()),
            exec_sessions: Arc::new(crate::exec_session::SessionTable::new(
                crate::exec_session::ExecSessionCaps::default(),
            )),
            console_sessions: Arc::new(Mutex::new(
                crate::console_session::ConsoleSessionTable::default(),
            )),
            conn_semaphore: d2bd_runtime::concurrency::ConnSemaphore::new(8),
            op_locks: d2bd_runtime::concurrency::OpLockManager::new(),
            public_status_read_model: Arc::new(
                d2bd_runtime::public_read_model::PublicStatusReadModel::new(),
            ),
            provider_runtime: Arc::new(crate::provider_registry::ProviderRuntime::new()),
            resource_plane: Arc::new(Mutex::new(None)),
            interaction_runtime: Arc::new(tokio::sync::Mutex::new(None)),
            interaction_listeners: Arc::new(Mutex::new(None)),
            typed_shell_session_targets: d2bd_runtime::typed_shell_targets::new_cache(),
            zone_coordinator: d2bd_runtime::zone_authority::new_coordinator(),
            config_staging: Arc::new(Mutex::new(Default::default())),
            guest_component_sessions: Arc::new(tokio::sync::Mutex::new(HashMap::new())),
            guest_component_session_locks: Arc::new(tokio::sync::Mutex::new(HashMap::new())),
            security_key_sessions: Arc::new(parking_lot::Mutex::new(
                crate::security_key::SkSessionTable::default(),
            )),
            unsafe_local_helpers: Arc::new(d2bd_runtime::unsafe_local_helper::HelperRegistry::new(
                0,
                [],
            )),
        };
        let opener = RecordingOpener::new();
        adopt_orphaned_runners_on_startup_with(&state, &store, &FixedProcReader, &opener)
            .expect("quarantine startup snapshots");

        assert!(
            opener.calls.lock().expect("lock opener calls").is_empty(),
            "without current lifecycle identity, startup must not open pidfds"
        );
        assert!(!state.pidfd_table.contains("vm-a", "virtiofsd-ro-store"));
        assert!(
            SnapshotStore::get(&store, "vm-a", "virtiofsd-ro-store")
                .expect("read quarantined snapshot")
                .is_some(),
            "quarantined snapshots remain available for forensics"
        );
    }

    #[test]
    fn provider_startup_adoption_requires_a_current_lifecycle_snapshot() {
        let snapshot = RunnerSnapshotRecord {
            vm: "vm-a".to_owned(),
            role_id: "ch-runner".to_owned(),
            role: RunnerRole::CloudHypervisor,
            owner_resource_uid: None,
            zone_uid: Some(
                ResourceUid::parse("11111111-1111-4111-8111-111111111111").expect("Zone UID"),
            ),
            guest_uid: Some(
                ResourceUid::parse("22222222-2222-4222-8222-222222222222").expect("Guest UID"),
            ),
            guest_generation: Some(ResourceGeneration::new(1).expect("Guest generation")),
            provider_assignment_generation: Some(
                ResourceGeneration::new(1).expect("Provider generation"),
            ),
            policy_revision: Some(1),
            operation_id: Some("lifecycle-attempt".to_owned()),
            pid: 4242,
            start_time_ticks: 55,
            snapshotted_at: "2026-05-30T00:00:00Z".to_owned(),
        };
        assert!(!runner_snapshot_is_eligible(&snapshot, None));

        let mismatched = (
            ResourceUid::parse("11111111-1111-4111-8111-111111111111").expect("Zone UID"),
            ResourceUid::parse("33333333-3333-4333-8333-333333333333")
                .expect("replacement Guest UID"),
            ResourceGeneration::new(1).expect("Guest generation"),
            ResourceGeneration::new(1).expect("Provider generation"),
            1,
        );
        assert!(!runner_snapshot_is_eligible(&snapshot, Some(&mismatched)));

        let matching = (
            ResourceUid::parse("11111111-1111-4111-8111-111111111111").expect("Zone UID"),
            ResourceUid::parse("22222222-2222-4222-8222-222222222222").expect("Guest UID"),
            ResourceGeneration::new(1).expect("Guest generation"),
            ResourceGeneration::new(1).expect("Provider generation"),
            1,
        );
        assert!(runner_snapshot_is_eligible(&snapshot, Some(&matching)));
    }

    #[test]
    fn authorized_runner_snapshot_persists_the_complete_lifecycle_tuple() {
        let state =
            test_state_with_broker_socket(unreachable_broker_socket_path("authorized-snapshot"));
        let authorization = LifecycleAuthorization::for_test_with_guest(
            "Guest/vm-a",
            "11111111-1111-4111-8111-111111111111",
            "22222222-2222-4222-8222-222222222222",
            4,
            9,
            7,
            "lifecycle-attempt",
        );
        write_runner_snapshot_with_authorization(
            &state,
            "vm-a",
            "ch-runner",
            RunnerRole::CloudHypervisor,
            4242,
            55,
            None,
            Some(&authorization),
        )
        .expect("write authorized runner snapshot");
        let store = FilesystemSnapshotStore::new(&state.daemon_state_dir);
        let snapshot = SnapshotStore::get(&store, "vm-a", "ch-runner")
            .expect("read snapshot")
            .expect("snapshot");
        assert!(snapshot.has_complete_lifecycle_identity());
        assert_eq!(snapshot.zone_uid, Some(authorization.zone_uid().clone()));
        assert_eq!(snapshot.guest_uid, Some(authorization.guest_uid().clone()));
        assert_eq!(
            snapshot.guest_generation,
            Some(authorization.guest_generation())
        );
        assert_eq!(
            snapshot.provider_assignment_generation,
            Some(authorization.provider_assignment_generation())
        );
        assert_eq!(
            snapshot.policy_revision,
            Some(authorization.policy_revision())
        );
        assert_eq!(snapshot.operation_id.as_deref(), Some("lifecycle-attempt"));
    }

    #[test]
    fn vm_stop_signals_registered_pidfd_and_waits() {
        let state = test_state_with_broker_socket(unreachable_broker_socket_path("vm-stop-local"));
        let child = register_sleep_runner(&state, "vm-a", false);

        let response = dispatch_broker_vm_stop(
            &state,
            VmLifecycleRequest {
                vm: "vm-a".to_owned(),
                flags: MutationFlags {
                    apply: true,
                    ..MutationFlags::default()
                },
                force: false,
                no_wait_api: false,
            },
        )
        .expect("vm stop response");

        assert_eq!(
            response.get("outcome").and_then(serde_json::Value::as_str),
            Some("applied")
        );
        assert!(
            response
                .get("summary")
                .and_then(serde_json::Value::as_str)
                .unwrap_or_default()
                .contains("pidfd_table")
        );
        assert!(!state.pidfd_table.contains("vm-a", VM_RUNNER_ROLE_ID));
        let store = FilesystemSnapshotStore::new(&state.daemon_state_dir);
        assert!(
            SnapshotStore::list(&store)
                .expect("list runner snapshots")
                .is_empty()
        );
        let status = child.wait();
        assert!(!status.success());
    }

