    #[test]
    fn stateless_readiness_for_component_session_health_fails_loud() {
        use d2b_core::processes::ReadinessPredicate;
        use d2bd_runtime::readiness::readiness_predicate_ready;

        // The live readiness path intercepts `ComponentSessionHealth` nodes in
        // `VmStartRunner::spawn_and_wait_ready` and never reaches the stateless
        // helper. If the stateless arm is ever hit, the state-aware routing
        // regressed, so it MUST fail loud (not silently never-ready).
        let predicate = ReadinessPredicate::ComponentSessionHealth {
            vm: "work".to_owned(),
        };
        let result = readiness_predicate_ready(&predicate);
        assert_eq!(
            result,
            Err("guest-component-session-needs-state-aware-path".to_owned()),
            "stateless component-session readiness MUST be a loud Err so a routing regression cannot masquerade as a benign never-ready"
        );
    }

    /// Scripted observe-only liveness fake driving the readiness loop
    /// through the same call site as production. Pops the next scripted
    /// verdict each call; repeats the last verdict once exhausted.
    struct ScriptedLivenessProbe {
        inner: std::sync::Mutex<(
            std::collections::VecDeque<
                d2bd_runtime::supervisor::readiness_liveness::RunnerLiveness,
            >,
            d2bd_runtime::supervisor::readiness_liveness::RunnerLiveness,
        )>,
    }

    impl ScriptedLivenessProbe {
        fn always(verdict: d2bd_runtime::supervisor::readiness_liveness::RunnerLiveness) -> Self {
            Self {
                inner: std::sync::Mutex::new((std::collections::VecDeque::new(), verdict)),
            }
        }
    }

    impl d2bd_runtime::supervisor::readiness_liveness::LivenessProbe for ScriptedLivenessProbe {
        fn probe(&self) -> d2bd_runtime::supervisor::readiness_liveness::RunnerLiveness {
            let mut guard = self.inner.lock().expect("scripted liveness mutex");
            if let Some(verdict) = guard.0.pop_front() {
                guard.1 = verdict.clone();
                verdict
            } else {
                guard.1.clone()
            }
        }
    }

